window.JASTROW_CHUNKS[29]={"11600":{"h":"זִמְתָּנֵי","r":"G00557","html":"<div class=\"sense\"> nom. gent. pl. (denom. of <span dir=\"rtl\">זמתא</span> = <a href=\"#\" data-headword=\"זִמָּה\">זִמָּה</a>) <i>Zimthané</i> (schemers). <span class=\"citation\">Targ. Y. Deut. II, 20</span> (Targ. O. <span dir=\"rtl\">חשבני</span>; h. text <span dir=\"rtl\">זמזמים</span>).</div>","alt":["זִימְתָנֵי"]},"11601":{"h":"זַן","r":"G00558","html":"<div class=\"sense\"> ; Syr. <a href=\"#\" data-headword=\"זַן\">זן</a> qualitas, modus, P. Sm. 1138, sq.; cmp. <a href=\"#\" data-headword=\"זֶה\">זֶה</a>, a. <a href=\"#\" data-headword=\"מִן ²\">מִין</a> a. <a href=\"#\" data-headword=\"מָה\">מַה</a>) <i>quality, nature; kind, species</i>. <span class=\"citation\">Targ. Gen. I, 11</span> <span dir=\"rtl\">לִזְנֵיהּ</span> after its kind. <span class=\"citation\">Targ. Lev. XI, 14</span> <span dir=\"rtl\">לִזְנָהּ</span>; a. v. fr.—<span class=\"citation\">Ber. 32ᵃ</span> (prov.) <span dir=\"rtl\">מלי כרסיה זנא בישא</span> Ar. (ed. <span dir=\"rtl\">זְנֵי בישי</span>) filled stomachs are a bad sort (plenty is tempting).—Pl. <a href=\"#\" data-headword=\"זְנֵי\">זְנֵי</a>, <span dir=\"rtl\">זֵינֵי</span>. <span class=\"citation\">Targ. Gen. I, 21</span>; a. fr.—<span class=\"citation\">Dan. II, 5</span>, v. <a href=\"#\" data-headword=\"זְמָרָא I\">זְמָרָא</a>.—<span class=\"citation\">B. Kam. 16ᵇ</span> (expl. <span dir=\"rtl\">זנים</span>, <span class=\"citation\">II Chr. XVI, 14</span>) <span dir=\"rtl\">זני זני</span> Ms. M. a. Ar. (ed. <span dir=\"rtl\">זיני</span>) various species.</div>","alt":["זֵין","זְנָא I"]},"11602":{"h":"זְנָא II","r":"G00559","html":"<div class=\"sense\"><i>to go astray</i>, v. <a href=\"#\" data-headword=\"זְנֵי\">זְנֵי</a>.</div>","alt":[]},"11603":{"h":"זַנַּאי","r":"G00560","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זני\">זני</a>) <i>adulterer; voluptuous</i>. <span class=\"citation\">Sabb. 156ᵃ</span>.—Pl. <span dir=\"rtl\">זַנָּאִין</span>. <span class=\"citation\">Targ. Jer. IX, 1</span>; a. e.—<span class=\"citation\">Targ. Ez. XXIII, 45</span> (h. text <span dir=\"rtl\">נֹאֲפֹת</span>!).</div>","alt":[]},"11604":{"h":"זָנָב","r":"G00561","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>attachment, tail</i>. <span class=\"citation\">Bekh. VI, 9</span> <span dir=\"rtl\">זְנַב הגדי</span> the tail of a kid; a. fr.—<span class=\"citation\">Yoma 41ᵇ</span> <span dir=\"rtl\">זְ׳ לשון</span> the tail-end (fringes) of the band. <span class=\"citation\">Erub. 18ᵃ</span> (ref. to <span dir=\"rtl\">צלע</span>, <span class=\"citation\">Gen. II, 22</span>) <span dir=\"rtl\">ז׳</span> it means the tail (with which Adam was originally created). <span class=\"citation\">Kil. IV, 6</span> <span dir=\"rtl\">ואחת יוצאה ז׳</span> and one vine projects like a tail. <span class=\"citation\">Ukts. I, 3</span> <span dir=\"rtl\">ז׳ של אשכול</span> the skeleton of the cluster of grapes (the thin branches), opp. to <span dir=\"rtl\">יד</span>, the stem; a. fr.—Trnsf. <i>the last, least.</i> <span class=\"citation\">Ab. IV, 15</span>, v. <a href=\"#\" data-headword=\"אֲרִי\">אֲרִי</a>.—Euphem. <i>membrum virile</i>. Tanḥ. Ki Thetsé 10 (expl. <span dir=\"rtl\">ויזנב</span>, <span class=\"citation\">Deut. XXV, 18</span>) <span dir=\"rtl\">הכה אותן מכת ז׳</span> Amalek mutilated them by cutting off &amp;c.; Pesik. Zakh., p. 27ᵃ; <span class=\"citation\">Pesik. R. s. 12</span>; <span class=\"citation\">Num. R. s. 13</span>; v. <a href=\"#\" data-headword=\"זְמוֹרָה\">זְמוֹרָה</a>.—Denom.</div>","alt":[]},"11605":{"h":"זִנֵּב","r":"G00562","html":"<div class=\"sense\"><i>Pi</i>. (b. h.) </div><div class=\"sense\"><b>1)</b>  (v. <span class=\"citation\">Ukts. I, 3</span> quot. in <a href=\"#\" data-headword=\"זָנָב\">preced. w.</a>) <i>to cut off the extreme branches of the vine, to trim.</i> <span class=\"citation\">Shebi. IV, 6</span> <span dir=\"rtl\">המְזַנֵּב בגפנים</span> he who trims grape-vines.—Trnsf. <span dir=\"rtl\">ז׳ באשכולות</span> [<i>to thin the clusters</i>,] <i>to diminish the scholars</i> by persecution (v. <a href=\"#\" data-headword=\"אֶשְׁכּוֹל\">אֶשְׁכּוֹל</a>). <span class=\"citation\">Gen. R. s. 42</span>; <span class=\"citation\">Lev. R. s. 11</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to attack, force a passage</i>. <span class=\"citation\">Gen. R. s. 74</span> בקש לזַנְּבָן Joab wanted to force his passage through their territory; <span class=\"citation\">Yalk. Sam. 147</span>.</div>","alt":[]},"11606":{"h":"זַנְבָא","r":"G00563","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּנְבָא\">דַּנְבָא</a></div>","alt":[]},"11607":{"h":"זְנַבְיָה","r":"G00564","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Zenobia</i>, queen of Palmyra. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">ז׳ מלכתא</span> (not <a href=\"#\" data-headword=\"מַלְכוּתָא\">מלכותא</a>).</div>","alt":[]},"11608":{"h":"זִנְגָּאֵי","r":"G00565","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִינְגָּאֵי\">זִינְ׳</a></div>","alt":[]},"11609":{"h":"זנגבילא","r":"G00566","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Cant. III, 9</span>, read: <a href=\"#\" data-headword=\"זַמְבְּלִיגָא\">זַנְבְּלִיגָא</a> = <a href=\"#\" data-headword=\"זַמְבְּלִיגָא\">זַמְבְּלִיגָא</a>.</div>","alt":[]},"11610":{"h":"זַנְגְּבִילָא","r":"G00567","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ζιγγίβερις, zingiber) an Arabian <i>spice plant</i>, prob. <i>ginger</i>. <span class=\"citation\">Yoma 81ᵇ</span>; <span class=\"citation\">Ber. 36ᵇ</span> (v. Ms. M. in Rabb. D. S. a. l.), v. <a href=\"#\" data-headword=\"הִימַלְתָּא\">הִימַלְתָּא</a>.</div>","alt":[]},"11611":{"h":"זַנְדּוּקָא","r":"G00568","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">זנדיקא</span>, P. Sm. 1141; = <span dir=\"rtl\">זזדוקא</span>, reduplic. of <span dir=\"rtl\">זקק</span>, cmp. <a href=\"#\" data-headword=\"זִיקָא III\"><span dir=\"rtl\">זִיקָא</span> III</a>; for inserted <a href=\"#\" data-headword=\"נ\">נ</a> cmp <a href=\"#\" data-headword=\"מִזְדַּנְדְּזִין\">מזדנדזין</a> s. v. <span dir=\"rtl\">זעזע</span>) <i>jailer</i>. <span class=\"citation\">Taan. 22ᵃ</span> ז׳ אנא Ar. (ed., a. Ar. ed. Koh. <a href=\"#\" data-headword=\"זַנְדּוּקָא\">זַנְדּוּקָנָא</a>, v. Rabb. D. S. a. l. note 50; Ms. M. <a href=\"#\" data-headword=\"*בְּדִיקְנָאָה\">בְּדִיקְנָאָה</a>) I am a jailer.</div>","alt":[]},"11612":{"h":"זָנָה","r":"G00569","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זני\">זני</a></div>","alt":[]},"11613":{"h":"זְנוּ","r":"G00570","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְנוּתָא\">זְנוּתָא</a></div>","alt":[]},"11614":{"h":"זְנוֹחָא","r":"G00571","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Z’noḥa</i>(b. h. , <span class=\"citation\">Josh. XV, 34</span>; <span class=\"citation\">56</span>) in Judaea. <span class=\"citation\">Men. VIII, 1</span> (<span class=\"citation\">83ᵇ</span>) Ar. a. Rashi (ed. <a href=\"#\" data-headword=\"זטחא\">זטחא</a>, Ms. M. <span dir=\"rtl\">זונחא</span>, Mish. ed. <a href=\"#\" data-headword=\"מזוניחה\">מזוניחה</a>, Mish. Nap. <span dir=\"rtl\">וזוניחא</span>; v. Rabb. D. S. a. l. note); Tosef. ib. IX, 2 <span dir=\"rtl\">זו לחה</span> (corr. acc.).</div>","alt":[]},"11615":{"h":"זְנוּנִים","r":"G00572","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><b>1)</b> <i>prostitution;</i> בני ז׳ <i>children begotten in prostitution</i>. <span class=\"citation\">Pes. 87ᵃ</span> bot. <span dir=\"rtl\">בני ז׳</span>; <span class=\"citation\">ib. 87ᵇ</span> ובניך בני ז׳ Ms. M. (ed. <span dir=\"rtl\">בנים ז׳</span>, <span dir=\"rtl\">ובניך ז׳</span>, v. <a href=\"#\" data-headword=\"זָנַן\">זָנַן</a>).</div><div class=\"sense\"><b>—2)</b> <i>sensuality</i>. Ib. 111ᵃ <span dir=\"rtl\">אחדא … רוח ז׳</span> sexual passion will seize him (her).</div>","alt":[]},"11616":{"h":"זִנּוּק","r":"G00573","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִינּוּק\">זִינּוּק</a></div>","alt":[]},"11617":{"h":"זְנוּת","r":"G00574","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>prostitution, unchastity, voluptuousness</i>. <span class=\"citation\">Sot. IX, 15</span> (<span class=\"citation\">49ᵇ</span>) <span dir=\"rtl\">בית הועד יהיה לז׳</span> (= <span dir=\"rtl\">לבית ז׳</span>) the scholars’ meeting house shall become a place of licentiousness (where low people assemble). <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">על ז׳ אחותו</span> for seducing his sister. <span class=\"citation\">Ab. Zar. 36ᵇ</span> <span dir=\"rtl\">דרך ז׳</span> a meretricious connection, opp. <a href=\"#\" data-headword=\"אִישׁוּת\">אִישׁוּת</a>. <span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">על הכל … חוץ מן הז׳ …</span> the Lord is long-suffering to everything except debauchery. <span class=\"citation\">Keth. 3ᵃ</span>, v. <a href=\"#\" data-headword=\"בְּעִילָה\">בְּעִילָה</a>; a. v. fr.</div>","alt":[]},"11618":{"h":"זְנוּתָא","r":"G00575","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Gen. XXXIII, 2</span>. <span class=\"citation\">Targ. Hos. IV, 11</span>; a. fr.—<span class=\"citation\">Targ. Job XXXVI, 14</span> <span dir=\"rtl\">מרי ז׳</span> keepers of brothels.—<span class=\"citation\">Sot. 3ᵇ</span> <span dir=\"rtl\">ז׳ בביתא וכ׳</span> faithlessness in the house is like a worm in poppy-plants.</div>","alt":["זְנוּ"]},"11619":{"h":"זָנַח","r":"G00576","html":"<div class=\"sense\"> (b. h.) <i>to glisten</i> (cmp. <a href=\"#\" data-headword=\"דְּנַח\">דנח</a>) <i>to be fat; to be greasy, foul</i> (cmp. meanings of <span dir=\"rtl\">זהם</span>, <span dir=\"rtl\">צחן</span>, v. Ges. Thes. s. v. <a href=\"#\" data-headword=\"זנח\">זנח</a>); </div><div class=\"sense\"><b>1)</b>  (act. verb) <i>to loathe</i>. <span class=\"citation\">Midr. Till. to Ps. LX</span>; <span class=\"citation\">Yalk. Ps. 777</span> <span dir=\"rtl\">אני זָנַחְתִּי אתכם אתם זְנַחְתֶּם אותי</span> did I loathe you? You loathed me.</div><div class=\"sense\"><b>—2)</b> <i>to be loth</i>. <span class=\"citation\">Pesik. R. s. 41</span> (ref. to <span dir=\"rtl\">זונה</span>, <span class=\"citation\">Ps. LXXIII, 27</span>) <span dir=\"rtl\">שרחקו וזָנְחוּ הימך</span> because they removed themselves from and were loth of Thee.</div><div class=\"sense\"><b>Hif. הִזְנִיחַ</b> <div class=\"sense\"><b>1)</b> <i>to declare rejectable, unclean;</i> (cmp. <span dir=\"rtl\">זהם</span>) <i>to reject;</i> (cmp. <a href=\"#\" data-headword=\"סְאֵב I\">סאב</a>, <span dir=\"rtl\">רחק</span>) <i>to remove</i>. <span class=\"citation\">Ḥull. 7ᵃ</span> <span dir=\"rtl\">אין מַזְנִיחִין אותו</span> we must not detest him (remove him from college). Pesik. R. l. c. <span dir=\"rtl\">מַזְנִיחִים עצמם הימך</span> they (through their sins) remove themselves from thee.</div><div class=\"sense\"><b>—2)</b> <i>to polish, cleanse</i>. Lev. R. s. l, beg. (ref. to <span dir=\"rtl\">אבי זנוח</span>) <span class=\"citation\">I Chr. IV, 18</span>) that is Moses <span dir=\"rtl\">שהיה אב למַזְנִיחִים שהִזְנִיחָם מע&quot;ז</span> for he was the father of the cleaners, for he cleansed them from idolatry; Yalk. ib. 428.</div></div><div class=\"sense\"><b>Pi. זִנֵּחַ</b> <div class=\"sense\"><i>to make glistening, to stroke, dress</i>. <span class=\"citation\">Num. R. s. 20</span>; Tanḥ. Balak 12 באתי … זִנַּחְתִּיהָ I had come to kill her, and now I had to polish her up; (Tanḥ. ed. Bub. ib. 20 <span dir=\"rtl\">זיניתה</span>; <span class=\"citation\">Yalk. Num. 768</span>, Matt. K. to Num. R. l. c. quotes in Tanḥ. l. c. <span dir=\"rtl\">דכיתיה</span>).</div></div>","alt":[]},"11620":{"h":"זנח","r":"G00577","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ps. XV, 5</span> <span dir=\"rtl\">יזנח</span> ed. Lag., read <span dir=\"rtl\">יזוּחַ</span> or <span dir=\"rtl\">יזוּעַ</span>.</div>","alt":[]},"11621":{"h":"זני","r":"G00578","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  [<i>to run to and fro, wander;</i>] (with <span dir=\"rtl\">אחר</span>) <i>to run after</i>, (with <span dir=\"rtl\">מאחרי</span>) <i>to run away from;</i> esp. <i>to run about as a prostitute, to be faithless, be unchaste</i> (cmp. ch. <span dir=\"rtl\">נפקת ברא</span> for <a href=\"#\" data-headword=\"זוֹנָה\">זוֹנָה</a>, a. <a href=\"#\" data-headword=\"טעי\">טעי</a> for our w.). <span class=\"citation\">Sabb. 55ᵇ</span> (play on <span dir=\"rtl\">פ̇ח̇ז̇</span>, <span class=\"citation\">Gen. XLIX, 4</span>) <span dir=\"rtl\">פ̇סעת … ח̇טאת זָ֗נִיתָ</span> thou hast trespassed upon religion, sinned, been unchaste (v. <a href=\"#\" data-headword=\"זוּל\">זוּל</a>).—<span class=\"citation\">Snh. 100ᵇ</span> <span dir=\"rtl\">שמא תִזְנֶה</span> lest she may go astray (be seduced); a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to commit an offense</i>. <span class=\"citation\">Gitt. 6ᵇ</span> explain. <span dir=\"rtl\">ותזנה עליו</span>, <span class=\"citation\">Jud. XIX, 2</span>, cmp. Targ. a. l.</div><div class=\"sense\"><b>Pi. זִינָּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"זנח\">same</a>, also <i>to invite faithlessness, to excite the senses</i>. <span class=\"citation\">Sabb. 88ᵇ</span> <span dir=\"rtl\">עלובה כלה מְזַנָּה בתוך חופתה</span> (v. Rabb. D. S. a. l.) bold is the bride who thinks of faithlessness while getting married; <span class=\"citation\">Gitt. 36ᵇ</span> <span dir=\"rtl\">שזִינְּתָה בקרב וכ׳</span>. <span class=\"citation\">Sot. 10ᵃ</span> <span dir=\"rtl\">כל המְזַנֶּה … מְזַנֶּנֶת עליו</span> if a man is lewd, his wife will think of faithlessness against him; <span class=\"citation\">Yalk. Job 918</span> <span dir=\"rtl\">מְזַנָּה תחתיו</span>. <span class=\"citation\">Meg. 15ᵃ</span> רחב בשמה זִינְּתָה וכ׳ Raḥab suggested impure thoughts by her name (<i>Raḥab hazzonah</i>), Jael with her call (<span class=\"citation\">Jud. IV, 18</span>) &amp;c., v. <a href=\"#\" data-headword=\"זְכִירָה\">זְכִירָה</a>; a. fr.—Trnsf. (of plants) <i>to degenerate</i>. <span class=\"citation\">Gen. R. s. 28</span>, end <span dir=\"rtl\">אף הארץ זינתה</span> the earth, too, became degenerated in her produces; v. <a href=\"#\" data-headword=\"זוֹנַיָּיא\">זוֹנַיָּיא</a>. Y. Kil. I, beg. 26ᵈ <span dir=\"rtl\">הפירות מְזַנִּין</span> the produces may degenerate (ref. to <span class=\"citation\">Lev. XIX, 29</span>).</div></div>","alt":["זָנָה"]},"11622":{"h":"זְנֵי","r":"G00579","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"זני\">same</a>. <span class=\"citation\">Targ. Y. Gen. XXXVIII, 24</span> <span dir=\"rtl\">זַנְיַית</span> (O. <span dir=\"rtl\">זַנִּיאַת</span>); a. e.</div><div class=\"sense\"><b>Pa. זַנֵּי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"זני\">same</a>. <span class=\"citation\">Targ. O. Deut. XXII, 21</span> <span dir=\"rtl\">לזַנָּ׳</span> ed. Berl. (ed. Amst. <span dir=\"rtl\">לזְנָאָה</span>); a. e.—<span class=\"citation\">Keth. 81ᵃ</span> <span dir=\"rtl\">ספק זַנָּאִי וכ׳</span> there is a doubt, did she or did she not commit adultery?—*Denom. <a href=\"#\" data-headword=\"אייזן\">אַיְיזַן</a> f. <i>a runner</i> (<i>after men</i>). <span class=\"citation\">Snh. 106ᵃ</span> bot. (prov.) <span dir=\"rtl\">מסגני ושילטי הואי א׳ לגברי נגרי</span> (<span dir=\"rtl\">נגדי</span>) after (living with) princes and governors she became a runner after ship draggers (or carpenters). [Our w. is absent in <span class=\"citation\">Yalk. Num. 785</span> as well as in Ms. M., the latter having a marginal version <span dir=\"rtl\">אזלא הויא</span>.]</div></div>","alt":["זְנָא"]},"11623":{"h":"זַנְיוּתָא","r":"G00580","html":"<div class=\"sense\">, Ms. <span dir=\"rtl\">זְנָיוּ׳</span>, <span class=\"citation\">Targ. Prov. XXIX, 3</span>, read: <span dir=\"rtl\">זַנְיָיתָא</span>, <a href=\"#\" data-headword=\"זַנְיְתָא\">זְנָיָי׳</a>, v. <a href=\"#\" data-headword=\"זַנְיְתָא\">next w.</a></div>","alt":[]},"11624":{"h":"זַנְיְתָא","r":"G00581","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Joel IV, 3</span> (ed. Wil. <span dir=\"rtl\">וַנְיָתָא</span>). <span class=\"citation\">Targ. Prov. VII, 10</span>. <span class=\"citation\">Ib. VI, 26</span>; a. e.—<span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">ברא דז׳</span> the son of the whore (heretic).—Pl. <a href=\"#\" data-headword=\"זַנְיְתָא\">זַנְיָתָא</a>, <a href=\"#\" data-headword=\"זַנְיְתָא\">זַנְיָי׳</a>, <a href=\"#\" data-headword=\"זַנְיְתָא\">זְנָיָי׳</a>. <span class=\"citation\">Targ. Hos. IV, 14</span>. <span class=\"citation\">Targ. Prov. XXIX, 3</span>, v. <a href=\"#\" data-headword=\"זַנְיוּתָא\">preced.</a> <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot. <span dir=\"rtl\">מיגר ז׳</span> hiring out prostitutes.</div>","alt":["זְנֵיתָא","(זַנָּיָי׳)"]},"11625":{"h":"זָנַן","r":"G00582","html":"<div class=\"sense\"> (sec. r. of <a href=\"#\" data-headword=\"זָנָה\">זָנָה</a>) <i>to be faithless, suspected of faithlessness.</i> <i>—Part. pass</i>. <span dir=\"rtl\">זָנוּן</span>, pl. <a href=\"#\" data-headword=\"זְנוּנִים\">זְנוּנִים</a> <i>of spurious paternity</i>. <span class=\"citation\">Pes. 87ᵃ</span> bot. <span dir=\"rtl\">ותוליד לך בנים ז׳</span> and she will bear thee spurious sons; <span class=\"citation\">ib. 87ᵇ</span> <span dir=\"rtl\">ובניך ז׳</span>; v. <a href=\"#\" data-headword=\"זְנוּנִים\">זְנוּנִים</a>.</div><div class=\"sense\"><b>Pi. זִנֵּן</b> <div class=\"sense\"><i>to think of faithlessness</i>. <span class=\"citation\">Sot. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"זָנָה\">זָנָה</a>.</div></div>","alt":[]},"11626":{"h":"זָנַק","r":"G00583","html":"<div class=\"sense\">, <i>Pi</i>. <span dir=\"rtl\">זִינֵּק</span> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to squirt, sputter, eject with force</i>. <span class=\"citation\">Nidd. 59ᵇ</span> <span dir=\"rtl\">במְזַנֶּקֶת</span> it means a woman discharging urin in a gush. <span class=\"citation\">Ḥull. 38ᵃ</span> <span dir=\"rtl\">זִינְּקָה</span> the animal’s blood sputtered (when its jugular arteries were cut). <span class=\"citation\">Y. Yoma I, 39ᵃ</span> bot. <span dir=\"rtl\">חוטמו מְזַנֵּק תולעים</span> his nose discharging worms.</div><div class=\"sense\"><b>—2)</b>  [<i>to make a persons’ mouth water</i>,] <i>to make a person sick by withholding from him a desired dish</i>. <span class=\"citation\">Ex. R. s. 16</span>, end <span dir=\"rtl\">אתם זִינַּקְתֶּם את בני וכ׳</span></div><div class=\"sense\"><b>Hif. הִזְנִיק</b> <div class=\"sense\"><i>to drop, to pour</i>. Y. Sabb. VIII, 11ᵇ bot. <span dir=\"rtl\">במַזְנִיק שנו</span> the Mishnah means when one uses pitch or sulphur in a liquid state.</div></div>","alt":[]},"11627":{"h":"זָע","r":"G00584","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זוּעַ\">זוּעַ</a> a. <span dir=\"rtl\">זעזע</span>.</div>","alt":[]},"11628":{"h":"זעאתא","r":"G00585","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XII, 21</span> some ed., v. <a href=\"#\" data-headword=\"עָאֲתָא\">עאתא</a>.</div>","alt":[]},"11629":{"h":"זְעוּר","r":"G00586","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְעֵיר I\">זְעֵיר</a>, <a href=\"#\" data-headword=\"זְעֵיר II\">זְעֵירָא</a>, a. <a href=\"#\" data-headword=\"זְעוּרֵי\">next w.</a></div>","alt":["זְעוּרָא"]},"11630":{"h":"זְעוּרֵי","r":"G00587","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְעֵיר I\">זְעַר</a>) = h. <a href=\"#\" data-headword=\"נְעוּרִים\">נְעוּרִים</a>, <i>youth, youthful days</i>. <span class=\"citation\">Targ. I Sam. XII, 2</span> (ed. Wil. <a href=\"#\" data-headword=\"זְעֵיר I\">זְעֵר־</a>). <span class=\"citation\">Targ. II Sam. XIX, 8</span> <span dir=\"rtl\">זְעוּרָךְ</span> (sing.); a. e.</div>","alt":[]},"11631":{"h":"זִעֲזוּעַ","r":"G00588","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זעזע</span>) <i>shock, fright</i>. <span class=\"citation\">Targ. Y. Gen. XXVII, 33</span>.</div>","alt":[]},"11632":{"h":"זִעֲזֵע","r":"G00589","html":"<div class=\"sense\"> (Pilp. of <a href=\"#\" data-headword=\"זוּעַ\">זוּעַ</a>) <i>to move, shake, agitate, trouble</i>. <span class=\"citation\">Ex. R. s. 15</span>, end <span dir=\"rtl\">ז׳ את הימים וכ׳</span> He stirred the seas up and showed to him (Moses) &amp;c. <span class=\"citation\">Y. Ber. IX, 13ᶜ</span> bot. <span dir=\"rtl\">אני מְזַעֲזֵעַ עולמי</span> I will make my world quake. <span class=\"citation\">Orl. I, 3</span> <span dir=\"rtl\">זִיעֲזַעְתּוֹ המחרישה</span> the ploughshare loosened it (the roots of the tree); <span dir=\"rtl\">זִיעֲזָעוֹ ועשאו בעפר</span> he (the husbandman) lifted the tree and placed it in soft earth (v. comment.).</div><div class=\"sense\"><b>Hithpalp. הִזְדַּעְזֵעַ</b> </div><div class=\"sense\"><b>Nithpa. נִזְדַּעְזֵעַ</b> <div class=\"sense\"><b>1)</b> <i>to be shaken, frightened</i>. <span class=\"citation\">Shebu. 39ᵃ</span>. Y. Ber. IV, 7ᵇ <span dir=\"rtl\">נִזְדַּעְזְעָה החומה</span> the wall was removed from its place; <span class=\"citation\">B. Kam. 82ᵇ</span> נז׳ א&quot;י Palestine quaked. <span class=\"citation\">Cant. R. to III, 7</span> <span dir=\"rtl\">מתיראין ומִזְדַּעְזְעִין וכ׳</span> were frightened and shaken; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to rise in rebellion</i>. <span class=\"citation\">Yalk. Num. 763</span> <span dir=\"rtl\">שנזדעזעו בני המדינה</span> against whom the inhabitants of the country rebelled; a. fr.—Contracted part. <a href=\"#\" data-headword=\"מִזְדַּנְדְּזִין\">מִזְדַּנְזִין</a>, or <a href=\"#\" data-headword=\"מִזְדַּנְדְּזִין\">מִזְדַּנְדְּזִין</a> (= <span dir=\"rtl\">מזדעזעין</span>). <span class=\"citation\">Ḥull. 48ᵃ</span> <span dir=\"rtl\">התלמידים מזדנז׳ בדבר</span> ed. (Ar. <span dir=\"rtl\">מזדנדז׳</span>) the students oppose it.</div><div class=\"sense\"><b>—3)</b> <i>to cause to quake</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 8</span> <span dir=\"rtl\">אתה הִזְדַּעְזַעְתָּ … אֶזְדַּעְזֵעַ וכ׳</span> thou hast made thy limbs tremble …, so will I make my world quake, v. supra.</div></div>","alt":["זִיעֲ׳"]},"11633":{"h":"זַעְזַע","r":"G00590","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. LX, 4</span>; a. fr.</div><div class=\"sense\"><b>Ithpalp. אִזְדַּעְזַע</b> <div class=\"sense\"><i>to be frightened</i>. <span class=\"citation\">Targ. Y. Gen. XXVII, 33</span>; a. fr.</div></div>","alt":[]},"11634":{"h":"זַעֲטוּט","r":"G00591","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (redupl. of <span dir=\"rtl\">זעט</span>, v. <a href=\"#\" data-headword=\"זוּטָא\">זוּטָּא</a>) <i>young man, youth, student.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"זַעֲטוּטָא\">זַעֲטוּטִים</a>, constr. <a href=\"#\" data-headword=\"זַעֲטוּטָא\">זַעֲטוּטֵי</a> (a Variant of <span dir=\"rtl\">נערי</span>, <span class=\"citation\">Ex. XXIV, 5</span>, because <span dir=\"rtl\">נערי</span> admits of the meaning of <i>servants, slaves</i>, Greek παιδές). <span class=\"citation\">Sifré Deut. 356</span> (v. <a href=\"#\" data-headword=\"מָעוֹן I\">מָעוֹן</a> a. <a href=\"#\" data-headword=\"הִיא\">הִיא</a>) and one manuscript existed in the Temple which was named <span dir=\"rtl\">ספר זעטוטים</span> the Book of Zaʿăṭûṭim (containing <a href=\"#\" data-headword=\"זַעֲטוּטָא\">זעטוטי</a> for <span dir=\"rtl\">נערי</span>); <span class=\"citation\">Treat. Sof’rim VI, 4</span> <span dir=\"rtl\">זאטוטי</span>; <span class=\"citation\">Y. Taan. IV, 68ᵃ</span> bot. <a href=\"#\" data-headword=\"זַעֲטוּטָא\">זעטוטי</a>.—<span class=\"citation\">Meg. 9ᵃ</span> (reported as one of the changes in the Greek translation of the Pentateuch, and ref. to <span dir=\"rtl\">נערי</span> l. c., and to <span dir=\"rtl\">אצילי</span> <span class=\"citation\">Ex. XXIV, 11</span>) <span dir=\"rtl\">זאטוטי</span> ed. (Ms. Par. <span dir=\"rtl\">זע׳</span>, oth. mss. a. <span class=\"citation\">Yalk. Gen. 3</span> <span dir=\"rtl\">זטוטי</span>) ‘the youths’ (νεανίσκοι, in place of παιδές, v. LXX Ex. l. c.).</div>","alt":["(זַאֲטוּט","זַטּוּט)"]},"11635":{"h":"זַעֲטוּטָא","r":"G00592","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Ex. XXIV, 11</span> Lev. (ed. <a href=\"#\" data-headword=\"עוּלֵימַיָּא\">עולימיא</a>). <span class=\"citation\">Targ. Cant. VI, 5</span>.</div>","alt":["זַעֲטוּטֵי"]},"11636":{"h":"*זְעִי","r":"G00593","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זְעֵיר I\"><span dir=\"rtl\">זְעֵיר</span> I</a>) <i>to be small, diminished</i>. <span class=\"citation\">Targ. Prov. X, 27</span> נזעין Ms. a. Var. ed. Lag. (ed. Lag. a. oth. <a href=\"#\" data-headword=\"זְעֵיר I\">זער</a>).</div>","alt":[]},"11637":{"h":"זַעֲיָא","r":"G00594","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִיעַ\">זֵיעָא</a></div>","alt":["זַעֲיָיא"]},"11638":{"h":"*זַעֲיָיתָא","r":"G00595","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*זְעִי\">זְעִי</a>) <i>small</i>. <span class=\"citation\">Targ. Prov. VII, 6</span> Lev. a. Buxt. (ed. Lag. <span dir=\"rtl\">זעירתא</span>, Var. <span dir=\"rtl\">זעיי׳</span>).</div>","alt":[]},"11639":{"h":"זְעֵיק","r":"G00596","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְעַק\">זְעַק</a></div>","alt":[]},"11640":{"h":"חֲמֵת","r":"H01239","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֵמְתָא\">חֵמְתָא</a>) <i>to get hot, angry</i>. [<span dir=\"rtl\">חמת־</span>, <i>to see</i>, v. <a href=\"#\" data-headword=\"חֲמִי\">חֲמִי</a>.]</div><div class=\"sense\"><b>Pa. חַמֵּית</b> </div><div class=\"sense\"><b>Af. אַחְמֵית</b> <div class=\"sense\"><i>to make angry</i>. <span class=\"citation\">Targ. Prov. XX, 2</span> <span dir=\"rtl\">מְחַמֵּית</span> (Var. <span dir=\"rtl\">מַחְמֵית</span>).</div></div>","alt":[]},"11641":{"h":"חֲמָת","r":"H01240","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (b. h.) <i>Hamath</i>, a Syrian city, near the later Antiochia. <span class=\"citation\">Targ. O. Num. XIII, 21</span> (Y. <a href=\"#\" data-headword=\"אַנְטוּכְיָא\">אנטוכיא</a>); ib. XXXIV, 8 (Y. <span dir=\"rtl\">טיבריא</span>, v. <a href=\"#\" data-headword=\"חַמְּתָא\">חַמְּתָא</a>); a. fr.—<span class=\"citation\">Num. R. s. 10</span> (ref. to <span class=\"citation\">Am. VI, 2</span>) <span dir=\"rtl\">זו חֲמת אנטוכיא</span> that is H. near Antiochia (Yalk. Am. 545 <span dir=\"rtl\">זה אנט׳</span>).</div>","alt":[]},"11642":{"h":"חַמַּת ²","r":"H01241","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (b. h.) <i>Hammath</i>, v. <a href=\"#\" data-headword=\"חַמְּתָא\">חַמְּתָא</a>.</div>","alt":[]},"11643":{"h":"חֵמְתָא","r":"H01242","html":"<div class=\"sense\"><i>anger</i>, v. <a href=\"#\" data-headword=\"חֵימָרָא\">חֵימְ׳</a>.</div>","alt":[]},"11644":{"h":"חֲמָתָא","r":"H01243","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"חָמוֹת\">חָמוֹת</a>. Targ. O. XXVII, 23 (Var. <a href=\"#\" data-headword=\"חֲמוֹתָא\">חֲמוֹתָא</a>).—<span class=\"citation\">Gitt. 67ᵇ</span> bot. (Ar. <a href=\"#\" data-headword=\"חֲמוֹתָא\">חמותא</a>), v. <a href=\"#\" data-headword=\"דִּיסְתָּנָא ²\"><span dir=\"rtl\">דִּיסְתָּנָא</span> I</a>. <span class=\"citation\">Kidd. 12ᵇ</span> <span dir=\"rtl\">חֲמָתֵיה</span>; <span class=\"citation\">Yeb. 52ᵃ</span> <span dir=\"rtl\">חימתיה</span> (corr. acc.), v. <a href=\"#\" data-headword=\"דּוּם\">דּוּם</a>; a. fr.</div>","alt":[]},"11645":{"h":"חַמְּתָא","r":"H01244","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḥamm’tha</i>, [<i>Ḥot Springs</i>], name of several Jewish places, esp. a) <i>Ḥ.</i> <i>, near Tiberias</i>. <span class=\"citation\">Y. Meg. I, 70ᵃ</span> (expl. <span dir=\"rtl\">חמת</span>, <span class=\"citation\">Josh. XIX, 35</span>; Bab. <span class=\"citation\">Meg. 6ᵃ</span> top <span dir=\"rtl\">חמת זו טבריא</span>). <span class=\"citation\">Tosef. Erub. VII</span> (<span class=\"citation\">V), 2</span>; Y. ib. V, 22ᵈ bot.; a. e.—b) <i>Ḥ., near Geder</i>. [Meg. l, c. (expl. <span dir=\"rtl\">חמת</span>, Josh. l. c.) <span dir=\"rtl\">זו חמת גדר</span> Ms. M. 2 (ed. <span dir=\"rtl\">חמי גרר</span>).] <span class=\"citation\">Y. Erub. VI, 23ᶜ</span> bot.; <span class=\"citation\">Y. Kidd. III, 64ᵈ</span> top.—c) <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> bot. <span dir=\"rtl\">ח׳ דפחל</span> <i>Ḥ. near Pella</i> (v. Neub. Géogr. p. 274).—<span class=\"citation\">Lam. R. to I, 16</span> <a href=\"#\" data-headword=\"ח׳\">ח׳</a> (Neub. l. c. p. 115 <a href=\"#\" data-headword=\"חַמְּתן\">חמתן</a>) Emmaus in Judæa.—V. <a href=\"#\" data-headword=\"אִמָּאוּס\">אִמָּאוּס</a>.</div>","alt":["חַמְּתָה"]},"11646":{"h":"חַמְּתן","r":"H01245","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חַמְּתָא\">preced.</a>) pr. n. pl. <i>Ḥamm’than</i>. <span class=\"citation\">Meg. 2ᵇ</span> <span dir=\"rtl\">כמח׳ לטבריא</span> as far as from Ḥ. to Tiberias (one mile).—<span class=\"citation\">Lam. R. to I, 16</span>, v. <a href=\"#\" data-headword=\"חַמְּתָא\">preced.</a></div>","alt":[]},"11647":{"h":"חֶמְתָּנָא","r":"H01246","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֵימְתָא\">חֵימְתָא</a>) <i>irascible</i>. <span class=\"citation\">Targ. Prov. XV, 18</span>; a. e.</div>","alt":[]},"11648":{"h":"חָן","r":"H01247","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָנָה\">חָנָה</a> a. <a href=\"#\" data-headword=\"חָנַן\"><a href=\"#\" data-headword=\"חָנַן\">חָנַן</a>.</a></div>","alt":[]},"11649":{"h":"חַן","r":"H01248","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנַן\">חֲנַן</a></div>","alt":[]},"11650":{"h":"חֵן","r":"H01249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>grace, favor; loveliness</i>. <span class=\"citation\">Ab. Zar. 20ᵃ</span> (ref. to <span dir=\"rtl\">תחנם</span>, <span class=\"citation\">Deut. VII, 2</span>) <span dir=\"rtl\">לא תתן להם חן</span> ascribe no gracefulness to them (pay no attention to their beauty). <span class=\"citation\">Yeb. 63ᵇ</span> (quot. fr. Ben. Sira) <span dir=\"rtl\">אשת חן</span> <i>coquette</i>. <span class=\"citation\">Keth. 17ᵃ</span>; <span class=\"citation\">Snh. 14ᵃ</span>, v. <a href=\"#\" data-headword=\"יְעֵלָה\">יַעֲלָה</a>. <span class=\"citation\">Succ. 49ᵇ</span> <span dir=\"rtl\">אדם שיש עליו חן</span> (Ms. M. <span dir=\"rtl\">לו</span>; Var. <a href=\"#\" data-headword=\"חָסַד I\">חסד</a>) a person that makes a favorable impression on men. <span class=\"citation\">Ber. 60ᵇ</span> <span dir=\"rtl\">ותנני … לחן וכ׳</span> and let me find grace and favor &amp;c. <span class=\"citation\">Keth. 77ᵇ</span> <span dir=\"rtl\">אם חן מעלה וכ׳</span> if the Law makes pleasing those who study it, will it not also protect them?—<span class=\"citation\">Y. Gitt. V, 46ᵈ</span> top <span dir=\"rtl\">מפני חִינָּהּ וכ׳</span> for the sake of her grace (to raise her estimation in the eyes of men), that people may be anxious to marry her; v. next w.—<span class=\"citation\">Gen. R. s. 34</span>, end <span dir=\"rtl\">שנתן חן וכ׳</span> who made every place attractive to its inhabitants; a. fr.—Pl. <span dir=\"rtl\">חִינּוֹת</span>, <span dir=\"rtl\">חִינִּין</span>. <span class=\"citation\">Sot. 47ᵃ</span> <span dir=\"rtl\">ג׳ ח׳ הן וכ׳</span> there are three remarkable favors, the favor in which the inhabitants hold their place &amp;c.; <span class=\"citation\">Y. Yoma IV, beg. 41ᵇ</span></div>","alt":["חֵין"]},"11651":{"h":"חִנָּא","r":"H01250","html":"<div class=\"sense\"><span class=\"citation\">Targ. Prov. XXXI, 30</span>. <span class=\"citation\">Targ. Y. Gen. VI, 8</span>.—<span class=\"citation\">Yeb. 38ᵇ</span> (the law is easy in the case of a woman’s widowhood) <span dir=\"rtl\">משום ח׳</span> in order to make her attractive (v. <a href=\"#\" data-headword=\"חֵן\">preced.</a>); [oth. opin.: in order that women may be willing to marry; oth. opin.: in order to maintain pleasantness between husband and wife;] <span class=\"citation\">Keth. 84ᵃ</span>; a. e.</div>","alt":["חִינָּא"]},"11652":{"h":"חֵנָא","r":"H01251","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">חון</span>, cmp. <span dir=\"rtl\">חבן</span> s. v. <a href=\"#\" data-headword=\"חֲבִינָנוּת\">חֲבִינָנוּתָא</a>) <i>lap, bosom</i>. <span class=\"citation\">Targ. Is. XL, 11</span>. <span class=\"citation\">Targ. II Sam. XII, 3</span>; <span class=\"citation\">8</span> ed. Lag. (oth. ed. <span dir=\"rtl\">חיק׳</span>; Ar. <span dir=\"rtl\">חֲיָינֵ׳</span>). <span class=\"citation\">Targ. I Kings XVII, 19</span>.—Cmp. <a href=\"#\" data-headword=\"לְחֵינְתָא\">לְחֵינָא</a>.</div>","alt":["חֵינָא"]},"11653":{"h":"חֲנַג","r":"H01252","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"חֲנַג\">חַנַּג</a> (denom. of <a href=\"#\" data-headword=\"חִינְגָּא\">חִינְגָּא</a>) <i>to employ the ḥinga, to dance, play</i>. <span class=\"citation\">Targ. Y. Ex. XV, 20</span>. <span class=\"citation\">Ib. XXXII, 19</span>.</div>","alt":[]},"11654":{"h":"חִנגָּא","r":"H01253","html":"<div class=\"sense\"> &amp;c., v. sub <span dir=\"rtl\">חִינְגּ׳</span>.</div>","alt":["חִינְגִּיתָא"]},"11655":{"h":"חָנָה","r":"H01254","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חני\">חני</a></div>","alt":[]},"11656":{"h":"חֶנְוָאָה","r":"H01255","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָנוּת\">חָנוּת</a>) <i>a frequenter of taverns, idler</i> (cmp. <a href=\"#\" data-headword=\"הַטְלֵיס\">הַטְלֵיס</a>). <span class=\"citation\">Pes. 110ᵇ</span></div>","alt":[]},"11657":{"h":"חִנּוּגָא","r":"H01256","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִנְטָא\">חִינּ׳</a></div>","alt":[]},"11658":{"h":"חֶנְוָונִי","r":"H01257","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָנוּת\">חָנוּת</a>) <i>shop-keeper, salesman; tavern-keeper</i>. <span class=\"citation\">Shebu. VII, 1</span> <span dir=\"rtl\">והח׳ על פנקסו</span> and the store-keeper swears to the correctness of his book account. <span class=\"citation\">Kidd. IV, 14</span> <span dir=\"rtl\">רועה וח׳</span> the trade of a shepherd or tavern-keeper; Y. ib. 66ᶜ; <span class=\"citation\">Treat. Sof’rim XV, 10</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"חֶנְוָונִי\">חֶנְוָונִים</a>. <span class=\"citation\">Y. M. Kat. III, 82ᵇ</span> bot. <span dir=\"rtl\">שני ח׳</span> two shop-keepers (in the same shop).—<i>Fem.</i> <a href=\"#\" data-headword=\"חֶנְוָונִי\">חֶנְוָונִית</a>. <span class=\"citation\">Keth. IX, 4</span> … <span dir=\"rtl\">המושיב ח׳</span> if one appoints his wife to be his sales-woman.</div>","alt":["חֶנְוָנִי"]},"11659":{"h":"חֲנוֹיָא","r":"H01258","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> בֶּן ח׳ <i>Ben-Ḥănoya</i>. Pesik. Baḥod., p. 105ᵃ; <span class=\"citation\">Gen. R. s. 31</span> a. <span class=\"citation\">Yalk. Ps. 876</span> <span dir=\"rtl\">בר חטיא</span> (corr. acc.).</div>","alt":[]},"11660":{"h":"חִנּוּךְ","r":"H01259","html":"<div class=\"sense\">, sub <a href=\"#\" data-headword=\"חִנְטָא\">חִינּ׳</a>.</div>","alt":["חִנּוּכָא"]},"11661":{"h":"חֲנוּכָּה","r":"H01260","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>inauguration, dedication, festival of dedication;</i> esp. <i>Ḥănuckah</i>, the eight days’ feast commemorating the rededication of the Temple after its desecration under Antioch Epiphanes, lasting from the 25<sup>ᵗʰ</sup> of Kislev to the second (or third) of Tebeth. <span class=\"citation\">Sabb. 21ᵇ</span> <span dir=\"rtl\">מאי ח׳</span> why dedication ceremonies (illumination)? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מצות ח׳</span> the proper observation of Ḥ. (illumination). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נר ח׳</span> the lights kindled on Ḥ.—<span class=\"citation\">Pesik. R. s. 2</span> <span dir=\"rtl\">חֲנוּכַּת שמים וארץ</span> the dedication of heaven and earth (by illumination, ref. to <span class=\"citation\">Gen. I, 18</span>); <span dir=\"rtl\">ח׳ החומה</span> the dedication of the wall of Jerusalem (<span class=\"citation\">Neh. XII, 27</span>); <span dir=\"rtl\">ח׳ הכהנים</span> the dedication (illumination) instituted by the Asmonean priests; a. fr.—Pl. <span dir=\"rtl\">חֲנוּכּוֹת</span>. Ib.</div>","alt":[]},"11662":{"h":"חֲנוּכְּתָא","r":"H01261","html":"<div class=\"sense\"><span class=\"citation\">Targ. Num. VII, 84</span>. <span class=\"citation\">Targ. Ps. XXX, 1</span>; a. e.—Y. M. Kat. III, end, 83ᵈ. <span class=\"citation\">Sabb. 45ᵃ</span></div>","alt":["חֲנֻכְּ׳"]},"11663":{"h":"חַנּוּן","r":"H01262","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>merciful, gracious</i> <span class=\"citation\">Sabb. 133ᵇ</span>.</div>","alt":[]},"11664":{"h":"חִנּוּן","r":"H01263","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִנְטָא\">חִינּ׳</a>.—[<span dir=\"rtl\">בְּנֵי חִ׳</span>, or <a href=\"#\" data-headword=\"חָנוּן I\">חָנוּן</a> pr. n. pl., v. <a href=\"#\" data-headword=\"הִינִי\">הִינִי</a> 3).]</div>","alt":[]},"11665":{"h":"חָנוּן I","r":"H01264","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> </div><div class=\"sense\"><b>1)</b>  part. pass. of <a href=\"#\" data-headword=\"חָנַן\">חָנַן</a>.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"חָנוּן II\">next w.</a>) <i>supplied with an application of Henna;</i> [oth. opin.: <i>mercifully protected</i>]; fem. <span dir=\"rtl\">חֲנוּנָה</span>, pl. <span dir=\"rtl\">חֲנוּנוֹת</span>. <span class=\"citation\">Sabb. V, 4</span> (expl. <span class=\"citation\">ib. 54ᵇ</span> <i>a compress dipped in oil;</i> Y. ib. 7ᶜ top <i>a wool-cap;</i> oth. opin., v. <a href=\"#\" data-headword=\"חָנוּן II\">next w.</a>). [Ms. Maim. <span dir=\"rtl\">יַחְנוּנוֹת</span>, quot. Löw Pfl. p. 213.]</div>","alt":[]},"11666":{"h":"חָנוּן II","r":"H01265","html":"<div class=\"sense\"><i>Henna, Alcanet</i>, a plant of the leaves of which a paste is made for dyeing nails, hair &amp;c. <span class=\"citation\">Sabb. 54ᵇ</span> (ref. to <span dir=\"rtl\">חנינות</span>, v. <a href=\"#\" data-headword=\"חָנוּן I\">preced.</a>) there is a tree in the sea-towns (Cyprus), <span dir=\"rtl\">וח׳ שמו וכ׳</span> ed. (Ms. M. <span dir=\"rtl\">יחנון</span>) its name is ḥ., and a chip thereof is taken and put into the nostrils (of the sick ewe), that it may sneeze and be released of the worms in the head (v. Löw Pfl. p. 213 a. quotations).—Y. ib. V, 7ᶜ top it is a root <span dir=\"rtl\">ושמיה יַחְנוּנָה</span> its name is <i>yaḥnunah</i></div>","alt":["חֲנוּן","(יַחֲנוּן)"]},"11667":{"h":"חָנוּן III","r":"H01266","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"חָנָן\">חָנָן</a></div>","alt":[]},"11668":{"h":"חֶנְוָנִי","r":"H01267","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶנְוָונִי\">חֶנְוָונִי</a></div>","alt":[]},"11669":{"h":"חֲנוּפָה","r":"H01268","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>hypocrisy, dishonesty, flattery</i>. <span class=\"citation\">Sot. 41ᵇ</span> <span dir=\"rtl\">אדם שיש בו ח׳</span> a man in whom there is insincerity. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אגרופה של ח׳</span> the power of flattery (towards Agrippa). <span class=\"citation\">Ib. 42ᵃ</span> <span dir=\"rtl\">עדה … ח׳</span> a community in which insincerity (flattery to power) prevails. <span class=\"citation\">Snh. 52ᵃ</span> <span dir=\"rtl\">בשביל ח׳ שהחניפו לקרח</span> because they flattered Korah. <span class=\"citation\">Kidd. 49ᵇ</span> <span dir=\"rtl\">ח׳ וגסות וכ׳</span> cringing submission (to power) and haughtiness (towards the weak); a. e.</div><div class=\"sense\"><b>—2)</b> <i>faithlessness to religion, apostasy</i>. <span class=\"citation\">Gen. R. s. 48</span>, beg. <span dir=\"rtl\">כל ח׳ וכ׳</span> where the root <span dir=\"rtl\">חנף</span> is used in the Bible, it means heresy; <span class=\"citation\">Yalk. Is. 304</span>.</div>","alt":[]},"11670":{"h":"חֲנוּפְתָּא","r":"H01269","html":"<div class=\"sense\"><span class=\"citation\">Targ. Jer. XXIII, 15</span>.</div>","alt":["חֲנֻפְ׳"]},"11671":{"h":"חָנוֹקָא","r":"H01270","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲנַק\">חֲנַק</a>) <i>strangler, fighter</i>. <span class=\"citation\">Gen. R. s. 78</span>, beg.; <span class=\"citation\">Cant. R. to I, 2</span>, a. e. <span dir=\"rtl\">ח׳ סברת וכ׳</span> strangler, doest thou mean to choke me, i.e. do you think you can embarrass me with your arguments?</div>","alt":["חָנוֹקָה"]},"11672":{"h":"חָנוּת","r":"H01271","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>tent</i>, esp. <i>tradesman’s shop, tavern; meat-market</i> &amp;c. <span class=\"citation\">Tosef. Pes. I (II), 1</span>9; <span class=\"citation\">Pes. 31ᵇ</span>. <span class=\"citation\">Ab. III, 16</span> <span dir=\"rtl\">הח׳ פתוחה וכ׳</span> the shop is open, the shop-keeper gives on credit, i.e. man has free volition and Providence is long-suffering &amp;c.—<span class=\"citation\">Gitt. 67ᵃ</span> <span dir=\"rtl\">ח׳ מיוזנת</span> well-stocked shop (a man of vast learning and readiness), v. <a href=\"#\" data-headword=\"יָזַן\">יָזַן</a>. <span class=\"citation\">Toh. VI, 3</span> <span dir=\"rtl\">ח׳ שהיא טמאה</span> ed. Dehr. (ed. <span dir=\"rtl\">שהוא טמא</span>); a. fr.—Pl. <span dir=\"rtl\">חֲנֻיּ׳ חֲנוּיּוֹת</span>. Ib.—<span class=\"citation\">B. Mets. 88ᵃ</span>, v. <a href=\"#\" data-headword=\"הִינִי\">הִינִי</a> 3). <span class=\"citation\">Ḥull. 95ᵃ</span> <span dir=\"rtl\">תשע ח׳ וכ׳</span> if there are nine meat-shops (in one market) all of which sell &amp;c.; <span class=\"citation\">Pes. 9ᵇ</span>; <span class=\"citation\">Nidd. 18ᵃ</span>; <span class=\"citation\">Keth. 15ᵃ</span>. <span class=\"citation\">Sabb. 35ᵇ</span> שניה להבטיל מלאכה מעיר וַחֲנוּיּוֹתֶיהָ Ms. M. (ed. <span dir=\"rtl\">להבטיל עיר וחנויות</span>) the second signal was given to stop work in the town and in its shops. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וננעלו הח׳</span> and the stores were closed. <span class=\"citation\">Ib. 15ᵃ</span> <span dir=\"rtl\">גלתה … לה בח׳</span> the Sanhedrin were removed from the Temple and held their meetings in the market; (<span class=\"citation\">Ab. Zar. 8ᵇ</span> <span dir=\"rtl\">בחנות</span>); a. fr.</div>","alt":[]},"11673":{"h":"חֲנוּתָא","r":"H01272","html":"<div class=\"sense\"> <span class=\"citation\">B. Mets. 60ᵃ</span> <span dir=\"rtl\">חמרא מח׳</span> wine from the shop; a. e.—Pl. <a href=\"#\" data-headword=\"חֲנוּתָא\">חֶנְוָתָא</a>, <span dir=\"rtl\">חֶנְוָו׳</span>, <span dir=\"rtl\">חֶנְוָא׳</span>. <span class=\"citation\">Targ. Jer. XXXVII, 16</span>; a. e.—<span class=\"citation\">Sabb. 32ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּזְיוּנָא I\"><span dir=\"rtl\">בִּזְיוּנָא</span> I</a>. <span class=\"citation\">B. Bath. 68ᵃ</span>. <span class=\"citation\">Y. Peah I, 16ᵃ</span> a. e. [read:] <span dir=\"rtl\">חֶנְוָ׳ דבותנאי וכ׳</span> the shops (tradesmen) of Bashan. [<span class=\"citation\">Y. Ber. VI, 10ᵃ</span> top <a href=\"#\" data-headword=\"חוֹזָאֵי\">בי ח׳</a>, v. <a href=\"#\" data-headword=\"חַדְוְתָא\">חַדְוְתָא</a>.]</div>","alt":[]},"11674":{"h":"חָנַט","r":"H01273","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to assume shape, form a texture;</i> (of trees) <i>to show a distinct shape of fruits, to form fruits;</i> (of fruits and leaves) <i>to assume a distinct shape</i> (v. <a href=\"#\" data-headword=\"חֲנָטָה\">חֲנָטָה</a>). <span class=\"citation\">R. Hash. 14ᵇ</span> אתרוג שחָנְטוּ פירותיו Ms. M. (ed. <span dir=\"rtl\">פירותיה</span>) an Ethrog-tree whose fruits were formed before the fifteenth of Shebat. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אילן שחנטו וכ׳</span> a tree whose fruits &amp;c. <span class=\"citation\">Y. Shebi. V, beg. 35ᵈ</span> <span dir=\"rtl\">אילן שח׳</span> a tree which formed fruits. <span class=\"citation\">Tosef. Shebi. IV, 20</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  [<i>to be handsome;</i> (Arab.) <i>to be red</i>,] <i>to make handsome</i>, or <i>flagrant</i>, esp. <i>toembalm</i>. <span class=\"citation\">Gen. R. s. 100</span>.</div>","alt":[]},"11675":{"h":"חֲנַט","r":"H01274","html":"<div class=\"sense\">, <i>to embalm</i>. <span class=\"citation\">Targ. O. Gen. L, 2</span> (Y. <span dir=\"rtl\">בסם</span>); a. e.—<span class=\"citation\">Taan. 5ᵇ</span> <span dir=\"rtl\">וכי בכדי … חַנְטוּ חנטייא</span> was it for nothing that … the embalmers embalmed (Jacob)?</div>","alt":[]},"11676":{"h":"חֶנֶט","r":"H01275","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲנַט\">preced.</a> wds.) <i>formation of fruits</i> or <i>leaves</i>. <span class=\"citation\">Y. Shebi. IV, end 35ᶜ</span>, a. e. <span dir=\"rtl\">שלשולן הוא חַנְטָן</span> their formation of chains is what in other trees is the formation of fruits. Ib. V, beg. 35ᵈ <span dir=\"rtl\">עקרתה חַנְטוֹ</span> thou disregardest the time of its formation. <span class=\"citation\">Y. Maasr. V, 51ᵈ</span> bot. <span dir=\"rtl\">בח׳ והשרשה</span> as regards the law regulating the tithes according to the time of the formation of fruits and of taking root.—<span class=\"citation\">R. Hash. 15ᵇ</span> <span dir=\"rtl\">אחר חנטה לשביעית</span> for the laws concerning the fruits of the Sabbatical year the formation of fruits is the deciding mark. <span class=\"citation\">Ib.ᵃ</span> (in Chald. diction) <span dir=\"rtl\">זיל בתר ח׳</span> be guided by &amp;c. <span class=\"citation\">Men. 69ᵃ</span> <span dir=\"rtl\">ח׳ דפירא</span> the formation of the fruit, <span dir=\"rtl\">ח׳ דעלה</span> the formation of the texture of leaves; v. <a href=\"#\" data-headword=\"הֲנָצָה\">הֲנָצָה</a>.</div>","alt":["חֲנָטָה"]},"11677":{"h":"חַנָּטָא","r":"H01276","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲנַט\">חֲנַט</a>) <i>embalmer</i>.—Pl. <span dir=\"rtl\">חַנָּטַיָּיא</span>. <span class=\"citation\">Taan. 5ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲנַט\">חֲנַט</a>.</div>","alt":[]},"11678":{"h":"חִנְטָא","r":"H01277","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חִיטָּא\">חִיטָּא</a>.—Pl. <a href=\"#\" data-headword=\"חִינְטָא\">חִנְטִין</a>, <a href=\"#\" data-headword=\"חִינְטָא\">חִנְטַיָּיא</a>. <span class=\"citation\">Targ. Y. Ex. XXIX, 2</span>. <span class=\"citation\">Targ. Job XXXI, 40</span>; a. e.</div>","alt":["חִינְ׳"]},"11679":{"h":"חֲנָטָה","r":"H01278","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶנֶט\">חֶנֶט</a></div>","alt":[]},"11680":{"h":"חֲנִטַּיָּא","r":"H01279","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנִיטַּיָּא\">חֲנִיטַּיָּא</a></div>","alt":[]},"11681":{"h":"חני","r":"H01280","html":"<div class=\"sense\"> [<i>to be covered, surrounded</i>,] <i>to encamp, rest</i>. <span class=\"citation\">Num. R. s. 11</span> (ref. to <span dir=\"rtl\">ויחנך</span>, <span class=\"citation\">Num. VI, 25</span>) <span dir=\"rtl\">יַחֲנֶה ד׳ אצלך</span> the Lord have His tent with thee. Lam. R. introd. (R. Naḥm.) (ref. to <span class=\"citation\">Is. XXIX, 1</span>) <span dir=\"rtl\">שח׳ בה וכ׳</span> where David (lawfully) resided, v. <a href=\"#\" data-headword=\"חַנְיָיא\">חַנְיָיא</a>. Ib. (R. Alex. 1) <span dir=\"rtl\">נוסעים … וחוֹנִים וכ׳</span> they moved in discord and encamped in discord; Mekh. Yithro, Baḥod., s. 1; <span class=\"citation\">Lev. R. s. 9</span>; a. fr.—Apocop. form: <a href=\"#\" data-headword=\"חָן\">חָן</a> (as if from <span dir=\"rtl\">חון</span>). <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 47</span> (play on <span dir=\"rtl\">ב̇ח̇נ̇מ̇ל</span> ib.) <span dir=\"rtl\">ב̇א ח̇ן̇ מ̇ל̇</span> he (the locust) came, encamped, cut; (Tanḥ. Vaëra 14 <span dir=\"rtl\">בא נ&quot;ח מ&quot;ל</span>; <span class=\"citation\">Ex. R. s. 12</span> interpol. from Midr. Till. l. c.: <a href=\"#\" data-headword=\"נֹחַ\">נח</a>).</div><div class=\"sense\"><b>Hif. הֱחֱנָה</b> <div class=\"sense\"><i>to cause to rest</i>. Fut. apocop. <a href=\"#\" data-headword=\"יַחַן\">יַחַן</a>. Y. Taan. III, 66ᶜ (play on <span dir=\"rtl\">י̇ח̇נ̇יף̇</span>, <span class=\"citation\">Num. XXXV, 33</span>) <span dir=\"rtl\">הדם י̇ח̇ן אף̇ וכ׳</span> bloodshed causes the anger (of the Lord) to rest upon the ground (rain being withheld); Sifré Num. 161, Yalk. ib. 788 <span dir=\"rtl\">יחון</span> (corr. acc.).</div></div>","alt":["חָנָה"]},"11682":{"h":"חַנְיָא","r":"H01281","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"חֲנִיָּיה\">חֲנִיָּיה</a>. <span class=\"citation\">Targ. Y. Num. XIII, 19</span> <a href=\"#\" data-headword=\"חַנְיָיא\">חַנְיָין</a> their encampment.—Lam. R. introd. (R. Naḥm.) <span dir=\"rtl\">לא ח׳ ליה בה וכ׳</span> (not <a href=\"#\" data-headword=\"לַיִת\">לית</a>; some ed. <span dir=\"rtl\">חֲנָיָה</span> h. form) where none but David had a right of encampment.</div>","alt":["חַנְיָיא"]},"11683":{"h":"חֲניֹּות","r":"H01282","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָנוּת\">חָנוּת</a></div>","alt":[]},"11684":{"h":"חֲנִיטַּיָּא","r":"H01283","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>embalming</i>. <span class=\"citation\">Targ. O. Gen. L, 3</span>.</div>","alt":["חֲנִטַּיָּא"]},"11685":{"h":"חַנְיָיא","r":"H01284","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַנְיָא\">חַנְיָא</a></div>","alt":[]},"11686":{"h":"חֲנִיָּיה","r":"H01285","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָנָה\">חָנָה</a>) <i>encampment, rest;</i> opp. <a href=\"#\" data-headword=\"נְסִיעָה\">נְסִיעָה</a>. <span class=\"citation\">Y. Erub. VI, 22ᶜ</span> bot. <span dir=\"rtl\">בחֲנִיָּיתָן</span> in the order of their encampment. <span class=\"citation\">Men. 95ᵃ</span> בחנייתן Ms. M. (ed. incorr. <span dir=\"rtl\">תו …</span>) when they were at rest. <span class=\"citation\">Sot. 34ᵇ</span>.—Esp. <i>right of colonization, acquiring property</i>. <span class=\"citation\">Ab. Zar. 20ᵃ</span> (ref. to <span dir=\"rtl\">תחנם</span>, <span class=\"citation\">Deut. VII, 2</span>, as if <span dir=\"rtl\">תַחֲנֵם</span>) <span dir=\"rtl\">לא תתן להם ח׳ וכ׳</span> give them no chance of acquiring property (sell them no trees in the ground); <span class=\"citation\">Yalk. Deut. 845</span>.</div>","alt":[]},"11687":{"h":"חֲנֵיךְ","r":"H01286","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנַךְ\">חֲנַךְ</a></div>","alt":[]},"11688":{"h":"חַנִּיךְ","r":"H01287","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָנַךְ\">חָנַךְ</a>) <i>educator, father</i>. <span class=\"citation\">M. Kat. 25ᵇ</span> Ms. M., v. <a href=\"#\" data-headword=\"חֲנִיכָה\">next w.</a></div>","alt":[]},"11689":{"h":"חֲנִיכָה","r":"H01288","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָנַךְ\">חָנַךְ</a>) [<i>rubbing the infant’s palate with a chewed fig</i>, v. Fl. to Levy Talm. Dict. II, 206,] <i>the name given to the child</i> by the person rubbing is palate; in gen. <i>surname.</i> <span class=\"citation\">Gitt. IX, 8</span> <span dir=\"rtl\">כתב חֲנִיכָתוֹ וחֲנִיכָתָהּ</span> if in the letter of divorce his and her family names are written. <span class=\"citation\">Ib. 88ᵃ</span> <span dir=\"rtl\">הֲנִיכַת אבות</span> the surname of ancestors. <span class=\"citation\">Taan. 20ᵇ</span>; <span class=\"citation\">Meg. 28ᵃ I</span> never called my neighbor <span dir=\"rtl\">בחֲנִיכָתִי וא&quot;ל בחֲנִיכָתוֹ</span> (Ar.) by an opprobrious surname given him by myself or, as others relate, by his by-name (which others had given him); ed.: <span dir=\"rtl\">בהכינתו וא&quot;ל בחניכתו</span> by his <i>ḥăkhina</i> (v. <a href=\"#\" data-headword=\"*הֲכִינָה\">הֲכִינָה</a>); some say, (Rab Ada used the expression)<i>ḥăkhina</i>. <span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">בעת חֲנִיכָתוֹ אבד חַנִּיכוֹ</span> (Ms. M. 2) at the time when he was to receive his name (when his palate was rubbed) died he who was to rear him (his father); (ed., v. <a href=\"#\" data-headword=\"חֲנִינָה II\"><span dir=\"rtl\">חֲנִינָה</span> II</a>). <span class=\"citation\">Gen. R. s. 43</span>, beg. (expl. <span dir=\"rtl\">חניכיו</span>, <span class=\"citation\">Gen. XIV, 14</span>) <span dir=\"rtl\">בעלי חֲנִיכָתוֹ וכ׳</span> those bearing his name, their name being Abram, like his own.</div>","alt":[]},"11690":{"h":"חֲנִיכַיִים I","r":"H01289","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (<a href=\"#\" data-headword=\"חָנַךְ\">חָנַךְ</a>; cmp. <a href=\"#\" data-headword=\"חִינְכֵי\">חִינְכֵי</a>) <i>palate and tongue</i>, contrad. to teeth. <span class=\"citation\">Ḥull. 103ᵇ</span> <span dir=\"rtl\">בין הח׳</span> in the posterior part of the mouth, i.e. if he spit out the forbidden foot just before swallowing.</div>","alt":[]},"11691":{"h":"חַנִּין","r":"H01290","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָנַן\">חָנַן</a>) <i>he who bestows love, affectionate father</i>. <span class=\"citation\">M. Kat. 25ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲנִינָה II\"><span dir=\"rtl\">חֲנִינָה</span> II</a>.</div>","alt":[]},"11692":{"h":"חַנִּין II","r":"H01291","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥannin</i>. <span class=\"citation\">M. Kat. 25ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"חָנָן\">חָנָן</a>.</div>","alt":[]},"11693":{"h":"חֲנִינָא","r":"H01292","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥănina</i>, name of several Tannaim and Amoraim. <i>Ḥ. b. Antigonos:</i> <span class=\"citation\">Tosef. Arakh. I, 15</span> (ed. Zuck. <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניא</a>); <span class=\"citation\">Arakh. II, 4</span> (<span class=\"citation\">10ᵃ</span>) Talm. ed. (Mish. <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניא</a>). <span class=\"citation\">Tem. VI, 5</span> <a href=\"#\" data-headword=\"חֲנִינָא\">חנינא</a>.; <span class=\"citation\">Tosef. ib. IV, 10</span> <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניה</a>. <span class=\"citation\">Nidd. 52ᵃ</span>. <span class=\"citation\">Bekh. VI, 3</span>; a. fr. (v. Darkhe Mish. p. 128).—<i>Ḥ. b. Gamliel:</i> <span class=\"citation\">Macc. III, 15</span> (<span class=\"citation\">23ᵃ</span>) Ms. M. (ed. <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניא</a>). <span class=\"citation\">B. Bath. X, 1</span>. (<span class=\"citation\">Tosef. Yoma I, 6</span> <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניא</a>; Sifra Emor ch. I, Par. 2, a. e. <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניה</a>). <span class=\"citation\">Snh. 111ᵃ</span> <span dir=\"rtl\">ח׳ בן גמלא</span> (v. Rabb. D. S. a. l. note).—<span class=\"citation\">Nidd. 8ᵃ</span> (v. Darkhe Mish. p. 130).—<i>Ḥ. b. Ḥăkhinai:</i> <span class=\"citation\">Kil. IV, 8</span> (Ms. M. a. Y. <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניה</a>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Men. 62ᵃ</span>; a. e. (mostly <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניא</a>, <span dir=\"rtl\">הנניה</span>).—<i>Ḥ., S’gan hak-Kohanim</i> (v. <a href=\"#\" data-headword=\"סָגָן\">סָגָן</a>). <span class=\"citation\">Eduy. II, 1</span>; a. fr. (v. Darkhe Mish. p. 59, sq.).—Rabbi Ḥ.: <span class=\"citation\">Sabb. 59ᵇ</span>; a. fr. (v. Frank. M’bo, p. 86ᵇ, sq.).—Other Amoraim by that name, v. Frank. l. c. 87ᵇ, sq.—<span class=\"citation\">Snh. 98ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲנִינָה II\">next w.</a></div>","alt":["חֲנִינָה I"]},"11694":{"h":"חֲנִינָה II","r":"H01293","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>mercy</i>. <span class=\"citation\">Gen. R. s. 78</span>; s. 92 <span dir=\"rtl\">שמענו ח׳ בי&quot;א וכ׳</span> we find <i>grace</i> applied to the eleven tribes (before Benjamin was born; <span class=\"citation\">Gen. XXXIII, 5</span>).</div><div class=\"sense\"><b>—2)</b> <i>caressing</i> (of the new-born child). <span class=\"citation\">M. Kat. 25ᵇ</span> (play on Ḥannin) <span dir=\"rtl\">בעת חֲנִינָתוֹ אבד חַנִּינוֹ</span> (v. <a href=\"#\" data-headword=\"חֲנִיכָה\">חֲנִיכָה</a>) at the moment of his receiving caresses died he who was to caress him.</div><div class=\"sense\"><b>—3)</b>  (name of fiction, v. <a href=\"#\" data-headword=\"חֲנִינָא\">preced.</a>) <i>Ḥăninah</i> (Love). <span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">דבי ר׳ חנינה אמרי ח׳ שמו</span> the disciples of R. Ḥ. said, the Messiah’s name is Ḥ.</div>","alt":[]},"11695":{"h":"חניניא","r":"H01294","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Deut. XXXII, 24</span> some ed., read: <span dir=\"rtl\">תַּנִּינַיָּא</span>.</div>","alt":[]},"11696":{"h":"חֲנִיסְנְסַיָּא","r":"H01295","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><b>1)</b> <i>gauzy dresses</i> or <i>veils</i>. <span class=\"citation\">Targ. Is. III, 19</span> (h. text <span dir=\"rtl\">רעל</span>).</div><div class=\"sense\"><b>—2)</b> <i>obscene statutary devoted to the Sun</i> (h. <a href=\"#\" data-headword=\"חַמָּן\">חַמָּנִים</a>). <span class=\"citation\">Targ. O. Lev. XXVI, 30</span>. <span class=\"citation\">Targ. Ezek. VI, 4</span>; <span class=\"citation\">6</span>. <span class=\"citation\">Targ. Is. XVII, 8</span>; a. e. [In various ed. our w. is written <span dir=\"rtl\">חניס נ׳</span> in two words, also <a href=\"#\" data-headword=\"חֲנִיסְנְסַיָּא\">חֲנִיסְסַיָּא</a>. Our w. seems to be a derivative of a stem <span dir=\"rtl\">חסס</span>, with anorganic <a href=\"#\" data-headword=\"נ\">נ</a>, having the meaning of <i>nakedness, shame</i>. (cmp <a href=\"#\" data-headword=\"חָסִית I\"><span dir=\"rtl\">חָסִית</span> I</a>, <a href=\"#\" data-headword=\"חֲסַד\">חֲסַד</a>, <a href=\"#\" data-headword=\"חֲסַף I\">חסף</a>).]</div>","alt":["חֲנִסְנְ׳","(חֲנִיסְסַיָּא)"]},"11697":{"h":"חֲנֵיף","r":"H01296","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנֵף\">חֲנֵף</a></div>","alt":[]},"11698":{"h":"חֲנֵיפָא","r":"H01297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנֵפָא\">חֲנֵפָא</a></div>","alt":[]},"11699":{"h":"חֲנֵיקָא","r":"H01298","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנָקָא\">חֲנָקָא</a></div>","alt":[]},"11700":{"h":"חֲנִיקָה","r":"H01299","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָנַק\">חָנַק</a>) <i>death by strangulation</i>. <span class=\"citation\">Y. Snh. VII, beg. 24ᵇ</span>, v. <a href=\"#\" data-headword=\"חֶנֶק\">חֶנֶק</a>.</div>","alt":[]},"11701":{"h":"חֲנִית","r":"H01300","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> חנה <i>to bend</i>, v. Ges. Thes. s. v.) <i>spear</i>. <span class=\"citation\">Yalk. Job. 927</span>.—Pl. <span dir=\"rtl\">חֲנִיתוֹת</span>. Ib. Gen. 133.</div>","alt":[]},"11702":{"h":"חֲנִיתָא","r":"H01301","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḥănitha</i>, a place in the district of Tyre. <span class=\"citation\">Tosef. Shebi. IV, 9</span> ח׳ עיליתא וח׳ ארעיתא Upper and Lower Ḥ.; <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top <span dir=\"rtl\">עלייתה וח׳ תחתיה</span> (corr. acc.).</div>","alt":["חֲנִיתָה"]},"11703":{"h":"חָנַךְ","r":"H01302","html":"<div class=\"sense\"><i>to rub, polish, finish;</i> trnsf. <i>to train; to dedicate</i>.</div><div class=\"sense\"><b>Pi. חִנֵּךְ</b> <div class=\"sense\"><i>to train, initiate</i> (a child); <i>to inaugurate, prepare for office; to dedicate</i>. Y. Yoma I, 38ᵇ top … <span dir=\"rtl\">מה מְחַנְּכִין אותו וכ׳</span> as the Highpriest’s inauguration lasted seven days (<span class=\"citation\">Lev. VIII, 33</span>, sq.), so is the Highpriest prepared for the service of the Day of Atonement seven days. <span class=\"citation\">Naz. 29ᵃ</span> <span dir=\"rtl\">כדי לחַנְּכוֹ במצות</span> in order to initiate his son into the performance of religious duties. <span class=\"citation\">Yoma VIII, 4</span>; Tosef. ib. V (IV), 2 <span dir=\"rtl\">מְחַנְּכִין וכ׳</span> you must train them gradually (to fast on the Day of Atonement) a year or two before religious maturity.—<span class=\"citation\">M. Kat. I, 6</span> <span dir=\"rtl\">מח׳ את הכוכין וכ׳</span> you may finish up the excavated chambers; v. <a href=\"#\" data-headword=\"חִינּוּךְ\">חִינּיּךְ</a>; a. fr.</div></div><div class=\"sense\"><b>Pu. חֻנָּךְ</b> </div><div class=\"sense\"><b>Hithpa. הִתְחַנֵּךְ</b> <div class=\"sense\">, <i>Nithpa.</i> נִתְחַנֵּךְ <i>to be inaugurated, to be dedicated</i>. <span class=\"citation\">Yalk. Prov. 964</span> <span dir=\"rtl\">יצחק ח׳ וכ׳</span>; Pesik. Baḥod., p. 101ᵃ יצחק נתח׳ וכ׳ Isaac was initiated into the covenant on his eighth day. Sifra Vayikra, Ḥoba, ch. III, Par. 3 <span dir=\"rtl\">שיִתְחַנֵּךְ המזבח וכ׳</span> that the altar must be dedicated by offering frankincense. <span class=\"citation\">Zeb. 40ᵇ</span>; a. e.</div></div>","alt":[]},"11704":{"h":"זְעֵיר I","r":"G00597","html":"<div class=\"sense\">, fut. <span dir=\"rtl\">יִזְעַר</span>, <span dir=\"rtl\">נִזְעַר</span> (cmp. <a href=\"#\" data-headword=\"זוּעַ\">זוּעַ</a>; b. h. <a href=\"#\" data-headword=\"זְעֵיר I\">זְעֵיר</a>) </div><div class=\"sense\"><b>1)</b> <i>to be slender, small; to be reduced, diminished</i>. <span class=\"citation\">Targ. Prov. X, 27</span>, v. <a href=\"#\" data-headword=\"*זְעִי\">זְעִי</a>. <span class=\"citation\">Targ. Jer. XXIX, 6</span>; a. fr.—<span class=\"citation\">Y. Sabb. VIII, 11ᵃ</span> bot. <span dir=\"rtl\">זַעֲרַת ולא ז׳ וכ׳</span> it (the measure) was reduced, but was not made as small as it had been before; v. <i>Ithpe.</i></div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">צער</span>) <i>to get sick</i>. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">ותִזְעַר נפשיה</span> and he may get sick.</div><div class=\"sense\"><b>—3)</b> <i>to restrain</i>. <span class=\"citation\">Targ. II Sam. XVIII, 16</span> ed. Lag. a. Ar. (ed. <span dir=\"rtl\">מנע</span>; h. text <span dir=\"rtl\">חשך</span>).</div><div class=\"sense\"><b>Af. אַזְעֵיר  אַזְעֵר</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"זְעֵיר I\">אַזְעַר</a> </div><div class=\"sense\"><b>1)</b> <i>to reduce, do little</i>. <span class=\"citation\">Targ. Ex. XVI, 17</span>; <span class=\"citation\">18</span> (h. text <a href=\"#\" data-headword=\"מָעַט\">הִמְעִיט</a>). <span class=\"citation\">Targ. Lev. XXV, 16</span>; a. fr.—<span class=\"citation\">Targ. Y. Num. XXII, 6</span> <span dir=\"rtl\">לאַזְעוֹרֵיה</span> to reduce (defeat) him (h. text <span dir=\"rtl\">נכה</span>).</div><div class=\"sense\"><b>—2)</b> <i>to be small</i>. <span class=\"citation\">Targ. O. Ex. XII, 4</span>; a. e.</div></div><div class=\"sense\"><b>Ithpe. אִזְדְּעַר  אִזְּעַר</b> <div class=\"sense\"><i>to be made smaller</i>. <span class=\"citation\">Targ. Y. Gen. I, 16</span>.—Y. Shek. III, 47ᶜ top [read:] <span dir=\"rtl\">אִזְּעִירָא ולא אִזְּעָרַת וכ׳</span> it was reduced, but not made as small &amp;c., v. supra.</div></div>","alt":["זְעֵר","זְעַר"]},"11705":{"h":"זְעֵיר II","r":"G00598","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְעֵיר I\">preced.</a>) <i>small, young, tender; lesser; a little</i>. <span class=\"citation\">Targ. Gen. I, 16</span>. <span class=\"citation\">Targ. O. ib. XLIV, 25</span>.—<span class=\"citation\">Targ. Gen. XIX, 31</span>; a. fr.—<span class=\"citation\">Y. Ber. II, 4ᵇ</span> <span dir=\"rtl\">ז׳ לא … דרבה</span> the inferior does not greet the superior; <span class=\"citation\">Y. Shek. II, 47ᵃ</span> top <span dir=\"rtl\">דז׳</span> (not <span dir=\"rtl\">ר׳ ז׳</span>).—<span class=\"citation\">Y. Snh. III, 21ᵃ</span> bot. <span dir=\"rtl\">משום דזעיר מיניה</span> in behalf of one his junior. <span class=\"citation\">Y. Keth. V, beg. 29ᶜ</span> <span dir=\"rtl\">ומר ז׳</span> and said something small (insignificant). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והדא היא ז׳</span> is this something small?; a. fr.—<a href=\"#\" data-headword=\"זְפִירִין\">זְעִירִין</a>, <span dir=\"rtl\">זְעֵירַיָּא</span>. <span class=\"citation\">Targ. Y. Ex. XII, 4</span>. <span class=\"citation\">Targ. Ps. CXV, 13</span>; a. fr.—Y. M. Kat. III, 82ᵈ top <span dir=\"rtl\">והוא שאיל לז׳</span> and he asked the inferior (scholars)?—Fem. <a href=\"#\" data-headword=\"זְעֵיר II\">זְעֵירָן</a>, <a href=\"#\" data-headword=\"זְעֵירְתָּא\">זְעֵירָתָא</a>. <span class=\"citation\">Targ. O. Gen. XXXII, 10</span>.—<span class=\"citation\">Targ. Ps. CIV, 25</span> (Ms. <a href=\"#\" data-headword=\"זוּטַרְתָּא\">זוטרתא</a>).</div>","alt":["זְעֵירָא","זְעֵירָא","זְעֵירְתָּא","זְעֶרְתָּא"]},"11706":{"h":"זְעֵיר III","r":"G00599","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Z’er</i> (<i>Little</i>), an Amora. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">ז׳ בר חיננא</span>. Y. Ber. V, end, 8ᵈ <span dir=\"rtl\">ר׳ ז׳</span>; a. e.</div>","alt":[]},"11707":{"h":"זְעֵירָא I","r":"G00600","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְעֵיר II\"><span dir=\"rtl\">זְעֵיר</span> II</a></div>","alt":[]},"11708":{"h":"זְעֵירָא II","r":"G00601","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Z’era</i>, [also: <a href=\"#\" data-headword=\"זְעוּר\">זְעוּרָא</a>, <span dir=\"rtl\">רָה …</span>] name of several Amoraim. <span class=\"citation\">Y. Ter. XI, 47ᵈ</span> bot.; a. fr. (in Bab. <a href=\"#\" data-headword=\"זֵירָא\">זֵירָא</a>).—<span class=\"citation\">Y. Ber. VI, 10ᵈ</span> top; a. e.—Ib. I, 3ᵃ top <span dir=\"rtl\">ר׳ ז׳ תנאי</span>.—Ib. VIII, 12ᶜ top; <span class=\"citation\">Gen. R. s. 3</span> <span dir=\"rtl\">ר׳ ז׳ בר אבהו</span>.—<span class=\"citation\">Y. Sabb. I, 3ᵈ</span> <span dir=\"rtl\">ר׳ ז׳ בר אבינא</span>. V. Fr. M’bo p. 77ᵇ, sq.</div>","alt":[]},"11709":{"h":"זְעֵירוּתָא","r":"G00602","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְעֵיר I\">זעיר</a>) <i>smallness, small number</i>. <span class=\"citation\">Targ. Lev. XXV, 16</span>; a. e.</div>","alt":[]},"11710":{"h":"זְעֵירְתָּא","r":"G00603","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְעֵיר II\"><span dir=\"rtl\">זְעֵיר</span> II</a></div>","alt":[]},"11711":{"h":"זָעַם","r":"G00604","html":"<div class=\"sense\"> (b. h.) <i>to be excited, angry</i>.—<i>Part. pass</i>. <span dir=\"rtl\">זָעוּם</span>; f. <span dir=\"rtl\">זְעוּמָה</span>; pl. <span dir=\"rtl\">זְעוּמוֹת</span>. <span class=\"citation\">Num. R. s. 11</span> <span dir=\"rtl\">פנים ז׳</span> morose countenance, opp. <span dir=\"rtl\">מאירות</span>; cmp. <a href=\"#\" data-headword=\"זָעַף\">זָעַף</a>.</div>","alt":[]},"11712":{"h":"זַעַם","r":"G00605","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זָעַם\">preced.</a>) <i>anger, displeasure</i>. <span class=\"citation\">Num. R. s. 11</span> <span dir=\"rtl\">פנים של ז׳</span>, v. <a href=\"#\" data-headword=\"זָעַם\">preced.</a> <span class=\"citation\">Kidd. 66ᵃ</span> <span dir=\"rtl\">ויבדלו … בז׳</span> and Israel’s scholars parted under (the king’s) displeasure.</div>","alt":[]},"11713":{"h":"זעע","r":"G00606","html":"<div class=\"sense\">, v. <span dir=\"rtl\">זעזע</span>, a. <a href=\"#\" data-headword=\"זוּעַ\">זוע</a>.</div>","alt":[]},"11714":{"h":"זָעַף","r":"G00607","html":"<div class=\"sense\"><i>to be excited, troubled, serious</i>.—Part. act. <span dir=\"rtl\">זוֹעֵף</span>; f. <span dir=\"rtl\">זוֹעֶפֶת</span>, pl. <span dir=\"rtl\">זוֹעֲפוֹת</span>, part. pass. <span dir=\"rtl\">זָעוּף</span>; f. <span dir=\"rtl\">זְעוּפָה</span>; pl. <span dir=\"rtl\">זְעוּפוֹת</span>. <span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">פנים זוע׳</span> (a. <span dir=\"rtl\">זעו׳</span>) serious (commanding) countenance. Pesik. Baḥod. p. 110ᵃ; <span class=\"citation\">Yalk. Ex. 286</span> <span dir=\"rtl\">פנים זו׳</span>, contrad. to <span dir=\"rtl\">בינוניות</span> indifferent, <span dir=\"rtl\">מסבירות</span> inviting, kind countenance.</div>","alt":[]},"11715":{"h":"זְעַף","r":"G00608","html":"<div class=\"sense\">, <i>to rage, threaten, storm</i>. <span class=\"citation\">Targ. Ps. L, 3</span> (h. text <span dir=\"rtl\">נשערה</span>). <span class=\"citation\">Ib. X, 5</span> (h. text <span dir=\"rtl\">יפיח</span>).—<span class=\"citation\">Gen. R. s. 63</span> בעא רבי דיִזְעוֹף ביה Rabbi wanted him (R. S.) to threaten him; Yalk. ib. 110 <span dir=\"rtl\">דיִזְעַף</span> (<span class=\"citation\">Y. Ter. VIII, end, 46ᶜ</span> <span dir=\"rtl\">למינזף</span>).</div>","alt":[]},"11716":{"h":"זַעַף","r":"G00609","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְעַף\">preced.</a> wds.) <i>stormwind, vehemence</i>;<i> anger</i>. <span class=\"citation\">Taan. III, 8</span> <span dir=\"rtl\">התחילו לירד בז׳</span> the rain began to come down with vehemence. <span class=\"citation\">Pesik. R. s. 15</span>, v. <a href=\"#\" data-headword=\"אַגְרִיאוֹן\">אַגְרִיאוֹן</a>. <span class=\"citation\">Treat. S’maḥ. III, 9</span> <span dir=\"rtl\">מיתה של ז׳</span> a sudden death (by the anger of the Lord); cmp. <span class=\"citation\">M. Kat. 28ᵃ</span>, s. v. <a href=\"#\" data-headword=\"דָּחַף\">דָּחַף</a>.</div>","alt":[]},"11717":{"h":"זַעֲפָא","r":"G00610","html":"<div class=\"sense\">, <i>stormwind, hurricane</i>. <span class=\"citation\">Targ. Job I, 19</span> (ed. Wil. <a href=\"#\" data-headword=\"זַעֲפָא\">זַעְפָּא</a>); a. e.—<span class=\"citation\">Ber. 59ᵃ</span> (expl. <span dir=\"rtl\">הרוחות</span> Mish. <span class=\"citation\">ib. IX, 2</span>).</div>","alt":[]},"11718":{"h":"זֶעְפְּרָנָא","r":"G00611","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Arab. a. Pers. zafrân) <i>saffron</i>. <span class=\"citation\">Targ. Y. Lev. XV, 19</span> (ed. Amst. <a href=\"#\" data-headword=\"זֶעְפְּרָנָא\">זְעָפָרָנָא</a>).</div>","alt":[]},"11719":{"h":"זָעַק","r":"G00612","html":"<div class=\"sense\"> (b. h.) <i>to cry</i>. <span class=\"citation\">Ex. R. s. 1</span> (ref. to <span class=\"citation\">Ex. II, 23</span>) <span dir=\"rtl\">אין וַיִזְעָקוּ אלא וכ׳</span> ‘they cried’ has the meaning of lamenting.</div><div class=\"sense\"><b>Hif. הִזְעִיק</b> <div class=\"sense\"><i>to cause to cry</i>. <span class=\"citation\">Gen. R. s. 67</span>, v. <a href=\"#\" data-headword=\"זְעָקָה\">זְעָקָה</a>.</div></div>","alt":[]},"11720":{"h":"זְעַק","r":"G00613","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ex. II, 23</span>; a. e.</div>","alt":["זְעֵיק"]},"11721":{"h":"זְעָקָה","r":"G00614","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְעַק\">preced.</a> wds.) <i>cry, prayer</i>. <span class=\"citation\">Yalk. Deut. 811</span>; <span class=\"citation\">Yalk. Sam. 157</span> (as one of the expressions for prayer; <span class=\"citation\">Deut. R. s. 2</span> <a href=\"#\" data-headword=\"צְעָקָה\">צְעָקָה</a>). <span class=\"citation\">Gen. R. s. 67</span> ז׳ אחת וכ׳ Jacob caused Esau to utter one cry.</div>","alt":[]},"11722":{"h":"זעקפי","r":"G00615","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 98</span>, v. <a href=\"#\" data-headword=\"זְקִיפִין\">זְקִיפִין</a></div>","alt":[]},"11723":{"h":"זְעֶרְתָּא","r":"G00616","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְעֵיר II\"><span dir=\"rtl\">זְעֵיר</span> II</a></div>","alt":[]},"11724":{"h":"זֵפָא","r":"G00617","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  = h. <span dir=\"rtl\">זֶפֶת</span> <i>pitch</i>. <span class=\"citation\">Targ. Is. XXXIV, 9</span>. <span class=\"citation\">Targ. Ex. II, 3</span>.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"זִיפּוּת\">זִיפּוּת</a> <i>pitch-coating</i>. Y. M. Kat. II, 81ᵇ top [read:] <span dir=\"rtl\">דזִיפְתָּהּ</span>, v. <a href=\"#\" data-headword=\"דַּקְדְּקִירָא\">דַּקְדְּקִירָא</a>.</div>","alt":["זִיפְתָּא","זִפְתָּא"]},"11725":{"h":"זְפִירִין","r":"G00618","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Ζεφύριον) <i>Z’firin, Zifirin</i> &amp;c., prob. <i>the headland of Cyprus</i> (v. Sm. Class. Dict. s. v. Zephyrium a. Neub. Géogr. p. 391), a place mentioned in connection with R. Akiba’s travels. (v. Sm. Class. Dict. s. v. Zephyrium a. Neub. Géogr. p. 391), a place mentioned in connection with R. Akiba’s travels. <span class=\"citation\">Y. B. Kam. IX, end, 7ᵃ</span> <a href=\"#\" data-headword=\"זְפִירִין\">זופ׳</a>; Sifré Num. s. 4 <span dir=\"rtl\">זופרי׳</span>, <a href=\"#\" data-headword=\"זִפְרוֹנָה\">זפרונה</a>; <span class=\"citation\">Num. R. s. 8</span> <a href=\"#\" data-headword=\"זִפְלָן\">זיפ׳</a>; <span class=\"citation\">B. Kam. 113ᵃ</span> <span dir=\"rtl\">זפי׳</span> (v. Rabb. D. S. a. l. note); <span class=\"citation\">Yalk. Num. 701</span> <a href=\"#\" data-headword=\"כּוּפְרִי I\">כופרי</a>.</div>","alt":["זִיפִירִין","(זִיפְרִין","זוּפְ׳","זוּפְרִים)"]},"11726":{"h":"זִפְלָן","r":"G00619","html":"<div class=\"sense\"> c. pl. (Syr. <a href=\"#\" data-headword=\"זִפְלָן\">זפלן</a>, P. Sm. 1146; <span dir=\"rtl\">פלא</span>, v. <a href=\"#\" data-headword=\"פְּלַן\">פְּלֵן</a>, with preform. <span dir=\"rtl\">ז׳</span>) <i>a certain number, so and so many</i>. Targ. II Esth. I, 8.</div>","alt":["זִיפְ׳"]},"11727":{"h":"זָפַף","r":"G00620","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זוּף\">זוּף</a> a. <span dir=\"rtl\">זֶפֶת</span>), <i>Pi</i>. <span dir=\"rtl\">זִיפֵּף</span> <i>to line vessels with pitch</i>.—<i>Part. pass. Kal</i> <span dir=\"rtl\">זָפוּף</span>, <i>Part. Pual</i> <span dir=\"rtl\">מְזוּפָּף</span>. <span class=\"citation\">Tosef. Ab. Zar. IV</span> (<span class=\"citation\">V), 10</span> <span dir=\"rtl\">זְפוּפוֹת</span>; <span class=\"citation\">Ab. Zar. 33ᵃ</span> <span dir=\"rtl\">מְזוּפָּפִין</span>. <span class=\"citation\">B. Mets. 40ᵇ</span> <span dir=\"rtl\">במז׳</span> when the oil vessels are lined. V. <span dir=\"rtl\">זָפַת</span>.</div>","alt":[]},"11728":{"h":"זֶפֶק","r":"G00621","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זפק</span>, cmp. <a href=\"#\" data-headword=\"סָפַק I\">ספק</a>, <a href=\"#\" data-headword=\"שָׂפַק\">שׂפק</a>; cmp. <a href=\"#\" data-headword=\"*אִיסְפְּקָא\">אִיסְפְּקָא</a>) <i>bird’s crop</i>. <span class=\"citation\">Ḥull. III, 4</span>. <span class=\"citation\">Ib. 6</span> (one of the signs of clean birds). <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">ז׳ של תרנגולת</span>, v. <a href=\"#\" data-headword=\"שַׁלְפּוּחִית\">שַׁלְפּוּחִית</a>.</div>","alt":[]},"11729":{"h":"זְפַק","r":"G00622","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Lev. I, 16</span>.—<span class=\"citation\">Targ. Y. Deut. XIV, 11</span> <span dir=\"rtl\">זפק</span>; ib. <span class=\"citation\">Lev. XI, 13</span> <a href=\"#\" data-headword=\"זְפַקְתָּא\">זְפַקְתָּא</a>. V. <a href=\"#\" data-headword=\"*זְלוּקְפָא\">זְלוּקְפָא</a>.</div>","alt":["זְפָקָא"]},"11730":{"h":"זְפַקְתָּא","r":"G00623","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"זְפַק\">preced.</a></div>","alt":[]},"11731":{"h":"זִפְרוֹנָה","r":"G00624","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְפִירִין\">זְפִירִין</a></div>","alt":["זִפְרִין"]},"11732":{"h":"זֵקָה","r":"G00625","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִיקָא II\"><span dir=\"rtl\">זִיקָא</span> II</a></div>","alt":[]},"11733":{"h":"זְקוֹף","r":"G00626","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זקף</span>. cmp. <span dir=\"rtl\">אסקופא</span>) <i>lintel;</i> trnsf. <i>upper lip</i>. <span class=\"citation\">Targ. Ps. CXLI, 3</span> (h. text <a href=\"#\" data-headword=\"דַּל I\">דַּל</a>, cmp. <a href=\"#\" data-headword=\"דֶּלֶת\">דֶּלֶת</a>),</div>","alt":[]},"11734":{"h":"זָקוּף","r":"G00627","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זָקַף\">זָקַף</a></div>","alt":[]},"11735":{"h":"זָקוֹף","r":"G00628","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְקִיפִין\">זְקִיפִין</a></div>","alt":["זְקוֹפִים","זְקוֹפִין"]},"11736":{"h":"זְקוּפָא","r":"G00629","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (a. Hebraism, v. <a href=\"#\" data-headword=\"זָקַף\">זָקַף</a>) <span dir=\"rtl\">קימה ז׳</span> (<a href=\"#\" data-headword=\"קוֹמָא I\">קומא</a>) <i>erect stature, pride</i>. <span class=\"citation\">Targ. Hos. XI, 7</span>. <span class=\"citation\">Targ. Y. Lev. XXVI, 13</span>. [זקופה <i>gallows</i>, v. <a href=\"#\" data-headword=\"זְקִיפָא II\"><span dir=\"rtl\">זְקִיפָא</span> II</a>.]</div>","alt":["זְקוּפָה"]},"11737":{"h":"זְקוּקָה","r":"G00630","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<span dir=\"rtl\">זקק</span>) <i>strainer</i>. <span class=\"citation\">Y. Sabb. II, 5ᵃ</span> top, v. <a href=\"#\" data-headword=\"דיקלון\">דיקלון</a>.</div>","alt":[]},"11738":{"h":"זְקֵינָה","r":"G00631","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זָקֵן II\"><span dir=\"rtl\">זָקֵן</span> II</a></div>","alt":[]},"11739":{"h":"זְקִיף","r":"G00632","html":"<div class=\"sense\"><i>to erect</i>, v. <a href=\"#\" data-headword=\"זְקַף\">זְקַף</a>.</div>","alt":[]},"11740":{"h":"זְקִיף ²","r":"G00633","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקִיף\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>erect, upright</i>. <span class=\"citation\">Pes. 40ᵃ</span> <span dir=\"rtl\">ז׳ אסיר</span> if it (the pot) stands upright (so that the moisture cannot run out), the grain is forbidden. [Ms. M. <a href=\"#\" data-headword=\"זְקִיפָא II\">זִיקְפָּא</a> as a noun, <i>an upright standing vessel</i>.]</div><div class=\"sense\"><b>—2)</b> <i>elevated, projecting</i>. <span class=\"citation\">Targ. Y. Lev. XIII, 2</span> <span dir=\"rtl\">שומא ז׳</span> (h. text <a href=\"#\" data-headword=\"שְׂאֵת\">שְׂאֵת</a>; some ed. <a href=\"#\" data-headword=\"זַקִּיפָא\">זַקִּיפָא</a>).—Pl. <a href=\"#\" data-headword=\"זְקִיפִין\">זְקִיפִין</a>. <span class=\"citation\">Targ. Y. Ex. XXVII, 2</span>.</div>","alt":["זְקִיפָא I"]},"11741":{"h":"זְקִיפָא II","r":"G00634","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקִיף ²\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>pole, scaffolding, gallows</i>. Targ. II Esth. II, 7; a. e.—<span class=\"citation\">Targ. I Chr. X, 10</span> <a href=\"#\" data-headword=\"זקַת\">זיק׳</a>.—<span class=\"citation\">Meg. 16ᵇ</span> <span dir=\"rtl\">וי&quot;ו … למימתחה כז׳</span> (Asheri <span dir=\"rtl\">כי ז׳</span>; ed. <a href=\"#\" data-headword=\"בִּיזּוּעַ\">בז׳</a> incorr.; v. Rabb. D. S. a. l. note 6) you must extend the <i>Vav</i> of <span dir=\"rtl\">ויזתא</span> (<span class=\"citation\">Esth. IX, 9</span>) as long as a pole; <span dir=\"rtl\">כולהו בחד ז׳ וכ׳</span> (ed. <a href=\"#\" data-headword=\"זְקִיפָה\">זקיפה</a>, Ms. H. 2 <span dir=\"rtl\">בז׳ חדא</span>; Asheri <span dir=\"rtl\">בחדא ז׳</span>) they were all hanged on one pole (at the same execution, v. infra).—<span class=\"citation\">B. Mets. 83ᵇ</span> <span dir=\"rtl\">תותי ז׳</span> under the gallows. <span class=\"citation\">Ab. Zar. 18ᵇ</span> <span dir=\"rtl\">אסקוה לז׳</span> they took him out for execution.</div><div class=\"sense\"><b>—2)</b>  (part. pass. of <a href=\"#\" data-headword=\"זְקַף\">זְקֵף</a>) <i>hanged, culprit</i>. <span class=\"citation\">B. Mets. 59ᵇ</span>, v. <a href=\"#\" data-headword=\"*דְּיוּקְתָּא\">דְּיוּקְתָּא</a>.</div><div class=\"sense\"><b>—3)</b>  (fem.) <i>execution</i>, v. supra.</div>","alt":["(זִיקְפָּא)"]},"11742":{"h":"זַקִּיפָא","r":"G00635","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקִיפָא II\">preced.</a>) <i>raising, lifting up</i>. <span class=\"citation\">Targ. Y. Gen. XV, 12</span>. [<span class=\"citation\">Targ. Y. Lev. XVIII, 2</span>, v. <a href=\"#\" data-headword=\"זְקִיף ²\"><span dir=\"rtl\">זְקִיפָא</span> I</a>.]</div>","alt":[]},"11743":{"h":"זְקִיפָה","r":"G00636","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָקַף\">זָקַף</a>) <i>putting up, erection</i>. <span class=\"citation\">Ab. Zar. 46ᵃ</span> <span dir=\"rtl\">דמינכרא זְקִיפָתָהּ</span> the erection of which is noticeable. <span class=\"citation\">Succ. 43ᵇ</span> <span dir=\"rtl\">דלמא בז׳</span> perhaps the proper ceremony consists in posting it (by the side of the altar).—<span class=\"citation\">M. Kat. 24ᵃ</span>, a. e. <span dir=\"rtl\">זְקִיפַת המטה</span> the putting up of the couch (on the Sabbath during mourning), opp. <a href=\"#\" data-headword=\"כְּפִיָיה\">כְּפִיָּיה</a>.</div>","alt":[]},"11744":{"h":"זְקִיפִין","r":"G00637","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָקַף\">זָקַף</a>) <i>officers for restoring the line of battle, guards against desertions</i>. <span class=\"citation\">Sot. VIII, 6</span> (<span class=\"citation\">44ᵃ</span> <span dir=\"rtl\">זקי׳</span>; Y. ed. <a href=\"#\" data-headword=\"זָקוֹף\">זְקוֹפִים</a>, Rashi <span dir=\"rtl\">זוֹקְפִין</span>). <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">זעקפי מלחמה</span> (read <span dir=\"rtl\">זְקִיפֵי</span> or <span dir=\"rtl\">זוֹקְפֵי</span>).</div>","alt":["זְקוֹפִין"]},"11745":{"h":"זְקִיפְתָּא","r":"G00638","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקַף\">זְקַף</a>) <i>rising up</i>. <span class=\"citation\">Targ. Lam. III, 63</span>. [<span class=\"citation\">Ab. Zar. 46ᵃ</span> <span dir=\"rtl\">האי זקיפת׳</span>, read: <span dir=\"rtl\">זְקִיפָתָהּ</span>, v. <a href=\"#\" data-headword=\"זְקִיפָה\">זְקִיפָה</a>.]</div>","alt":[]},"11746":{"h":"זְקִירָא","r":"G00639","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקַר\">זְקַר</a>) <i>leap</i>. <span class=\"citation\">B. Kam. 22ᵃ</span> top (Rashi: <a href=\"#\" data-headword=\"זְקִירָה\">זְקִירָה</a> h. fem.).</div>","alt":[]},"11747":{"h":"זְקִירָה","r":"G00640","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקִירָא\">preced.</a>) <i>leap</i>, v. preced.—<span class=\"citation\">R. Hash. 18ᵃ</span> Ar., v. <a href=\"#\" data-headword=\"סְקִירָה\">סְקִירָה</a> a. <a href=\"#\" data-headword=\"זָקַר\">זָקַר</a>.</div>","alt":[]},"11748":{"h":"זָקִיתָא","r":"G00641","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זקק</span>) [<i>the transparent one</i>, cmp. <a href=\"#\" data-headword=\"*זְבוּגָא\">זְבוּגָא</a>,] <i>chamæleon</i> (v. Sm. Ant. s. v.). <span class=\"citation\">Snh. 108ᵇ</span> ed. (Ms. M. <span dir=\"rtl\">זקותא</span>, Ms. F. <span dir=\"rtl\">רקיתא</span>); <span class=\"citation\">Yalk. Gen. 59</span> (some ed. <span dir=\"rtl\">רקיתא</span>). [Mus. derives our w. fr. <a href=\"#\" data-headword=\"זִיקָא I\">זיקא</a>, cmp. <a href=\"#\" data-headword=\"זַוְקָאנָא\">זַוְקָאנָא</a>, the chamæleon being believed to live on air.]</div>","alt":[]},"11749":{"h":"זָקֵן I","r":"G00642","html":"<div class=\"sense\"> (b. h.) [<i>to be thin, shrunk, hard</i>,] <i>to be old</i>. <span class=\"citation\">Gen. R. s. 48</span> (ref. to <span class=\"citation\">Gen. XVIII, 13</span>) <span dir=\"rtl\">ואני זָקַנְתִּי מלעשות וכ׳</span> am I (the Lord) too old to do wonders?</div><div class=\"sense\"><b>Hif. הִזְקִין</b> <div class=\"sense\"><b>1)</b> <i>to grow old</i>. <span class=\"citation\">Snh. 100ᵇ</span> <span dir=\"rtl\">הִזְקִינָה שמא וכ׳</span> when she arrives at old age, he is afraid lest &amp;c. <span class=\"citation\">Erub. 56ᵃ</span> <span dir=\"rtl\">מַזְקִינִים בחצי וכ׳</span> they age in the middle of their days (prematurely). <span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">כל זמן שמַזְקִינִין</span> the older they grow; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make old, consider old</i> (<i>feeble</i>). <span class=\"citation\">Gen. R. s. 48</span> <span dir=\"rtl\">אתם … ומזקינים חביריכם</span> you consider each himself young, and each his partner old (<span class=\"citation\">Yalk. ib. 82</span> <span dir=\"rtl\">ומז׳ אדניכם</span> and believe your Lord too old [to do wonders]); v. supra.</div></div><div class=\"sense\"><b>Nif. נִזְקַן</b> </div><div class=\"sense\"><b>Nithpa. נִזְדַּקֵּן</b> <div class=\"sense\"><b>1)</b> <i>to become old, weak, frail</i>. Y. Ber. IX, end 14ᶜ (ref. to prov. XXIII, 22) <span dir=\"rtl\">אם נִזְדַּקְּנָה אומתך וכ׳</span> if thy nation is decaying (in faith), stand up and fence her in (prevent her being trodden upon); <span class=\"citation\">Yalk. Prov. 960</span>.—2) (cmp. <span dir=\"rtl\">דקדק</span>) <i>to be maturely considered, be clear</i> (beyond doubt);</div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"קַשִּׁישׁ\">קשיש</a>) <i>to be hard, difficult</i>. <span class=\"citation\">Tosef. Snh. VII, 7</span> (the presiding judge declares) <span dir=\"rtl\">(<a href=\"#\" data-headword=\"זָקֵן I\">נִיזְקַן</a>) <span dir=\"rtl\">נִזְקַן הדין</span></span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"זָקֵן I\">נזדקן</a>, <a href=\"#\" data-headword=\"זָקַק\">נזדקק</a>); discussed in <span class=\"citation\">Snh. 42ᵃ</span> <span dir=\"rtl\">מאי נזד׳ הדין</span> what does <i>nizdakken</i> mean? Does it mean <span dir=\"rtl\">קש דינא</span> the case is hard (difficult, so as to demand a reconsideration)?… It means <span dir=\"rtl\">חכם דינא</span> the case is clear; Y. Snh. V, end, 23ᵃ</div></div>","alt":[]},"11750":{"h":"זְקַן","r":"G00643","html":"<div class=\"sense\"><b>Af. אַזְקֵן</b> <div class=\"sense\"><b>1)</b> <i>to make old, weaken</i>. <span class=\"citation\">Erub. 56ᵃ</span> <span dir=\"rtl\">הני מולייתא אַזְקְנוּן …</span> those ascents … made us (me) old, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a>.</div><div class=\"sense\"><b>—2)</b> <i>to grow old</i>. <span class=\"citation\">Nidd. 47ᵃ</span> <span dir=\"rtl\">אַזְקְנָא לה</span> (some ed. <span dir=\"rtl\">אזקונא</span>, Asheri <span dir=\"rtl\">אזקנה</span>) this would be a sign that she has entered old age (passed the change of life).</div></div>","alt":[]},"11751":{"h":"זָקֵן II","r":"G00644","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְקַן\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>old man</i>. <span class=\"citation\">Gen. R. s. 39</span>, opp. <a href=\"#\" data-headword=\"בָּחוּר\">בחור</a>. <span class=\"citation\">Y. Bicc. III, 65ᶜ</span> bot. <span dir=\"rtl\">עמידת ז׳</span> (<span class=\"citation\">Yalk. Lev. 670</span> <span dir=\"rtl\">מצות ז׳</span>) the duty of standing up before an old man. <span class=\"citation\">Ḥag. 14ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>elder, judge, scholar</i>. Ib. (ref. to <span class=\"citation\">Is. III, 2</span>) <span dir=\"rtl\">ז׳ זה שראוי וכ׳</span> <i>zaken</i> means one fit to sit in college sessions. <span class=\"citation\">Ber. 8ᵇ</span> <span dir=\"rtl\">ז׳ ששכח וכ׳</span> a scholar who forgot what he had learned, &amp;c., v. <a href=\"#\" data-headword=\"אוֹנֶס\">אוֹנֶס</a>. <span class=\"citation\">Kidd. 32ᵇ</span> <span dir=\"rtl\">אין ז׳ אלא חכם</span> under <i>zaken</i> (<span class=\"citation\">Lev. XIX, 32</span>) a scholar is meant; Sifra K’dosh. Par. 3, ch. VII <span dir=\"rtl\">אין ז̇ק̇ן̇ אלא ז̇ה שק̇נ̇ה חכמה</span> a <i>zaken</i> is he who has acquired wisdom (through study).—<span dir=\"rtl\">ז׳ אשמאי</span>, v. <a href=\"#\" data-headword=\"אַשְׁמַאי\">אַשְׁמַאי</a>. <span class=\"citation\">Yoma 28ᵇ</span> <span dir=\"rtl\">ז׳ ויושב בישיבה</span> a scholar and member of college. Y. M Kat. III, beg. 81ᶜ איני מכירך ז׳ I shall not recognize thee as (give thee the diploma of) a <i>zaken;</i> a. fr.—Pl. <span dir=\"rtl\">זְקֵנִים</span>. <span class=\"citation\">Snh. I, 3</span>, v. <a href=\"#\" data-headword=\"סְמִיכָה\">סְמִיכָה</a>. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">מצות הז׳</span> rabbinical law. <span class=\"citation\">Ber. 11ᵃ</span> <span dir=\"rtl\">זִקְנֵי ב&quot;ש</span> the graduates of the Shammai school; a. v. fr.</div><div class=\"sense\"><b>—3)</b> <i>grandfather, ancestor</i>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">מעשה זְקֵנָן</span> the conduct of their ancestor (Abraham). Pesik. Zakh., p. 27ᵇ; a. fr.—Fem. <a href=\"#\" data-headword=\"זִקְנָה\">זְקֵנָה</a>, <a href=\"#\" data-headword=\"זְקֵינָה\">זְקֵינָה</a>. 1) <i>old woman</i>. <span class=\"citation\">Gen. R. s. 39</span>.—<span class=\"citation\">Nidd. 9ᵃ</span> ז׳ <i>one who is past the change of life</i>. <span class=\"citation\">Ib. 9ᵇ</span>; a. fr.—2) <i>grandmother, ancestress</i>. <span class=\"citation\">Kidd. 31ᵇ</span> <span dir=\"rtl\">הוה ליה ההיא אמא זקי׳</span> had a grandmother. <span class=\"citation\">Gen. R. s. 93</span> <span dir=\"rtl\">זְקֵינָתוֹ של זה</span> this man’s (my) ancestress (Sarah); a. e.—3) (sub. <a href=\"#\" data-headword=\"נְטִיעָה\">נְטִיעָה</a>) <i>old plantation</i>. <span class=\"citation\">Tosef. Shebi. I, 2</span>; a. e., opp. <a href=\"#\" data-headword=\"נְטִיעָה\">נטיעה</a> young plantation.—Pl. <span dir=\"rtl\">זְקֵינוֹת</span>. Y. ib. I, 33ᵇ bot.; a. e.</div>","alt":[]},"11752":{"h":"זָקָן","r":"G00645","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>beard, hair-covered spot</i>. <span class=\"citation\">Ber. 11ᵃ</span> <span dir=\"rtl\">זְקָנְךָ וכ׳</span> thy beard is &amp;c., v. <a href=\"#\" data-headword=\"גָּדַל I\">גָּדַל</a>. <span class=\"citation\">Snh. VIII, 1</span> (<span class=\"citation\">68ᵇ</span>) <span dir=\"rtl\">עד שיקיף ז׳ התחתון וכ׳</span> until he grows a beard, by which is meant the hair of the genitals &amp;c.; a. fr.—Pl. <span dir=\"rtl\">זְקָנִים</span>. <span class=\"citation\">Lev. R. s. 3</span>.</div>","alt":[]},"11753":{"h":"זִקְנָה","r":"G00646","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>old age; frailty</i>. <span class=\"citation\">Ber. 39ᵃ</span> <span dir=\"rtl\">ז׳ אין כאן</span> is there not (the claim of) old age here?—<span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">ז׳ קופצת עליו</span> frailty of old age will overtake him (prematurely). <span class=\"citation\">B. Bath. 120ᵃ</span> <span dir=\"rtl\">מפליג בז׳</span> extremely old. <span class=\"citation\">Snh. 17ᵃ</span>, a. e. <span dir=\"rtl\">בעלי ז׳</span> men commanding repect for their age. <span class=\"citation\">B. Mets. 87ᵃ</span>; <span class=\"citation\">Snh. 107ᵇ</span> <span dir=\"rtl\">עד אברהם לא הואי ז׳</span> (v. Rabb. D. S. a. l. note 1) up to Abraham’s days, there was no distinction in appearance of old age (v. <span class=\"citation\">Gen. XXIV, 1</span>); a. fr.</div>","alt":[]},"11754":{"h":"זִקְנוּת","r":"G00647","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"זִקְנָה\">same</a>. <span class=\"citation\">Kidd. 82ᵇ</span> <span dir=\"rtl\">זִקְנוּתוֹ</span> (interch. with <span dir=\"rtl\">זִקְנָתוֹ</span>). <span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">שימרתי כחי לזִיקְנוּתִי</span> I save my strength for my old age; a. fr.</div>","alt":[]},"11755":{"h":"זִקְנוּתָא","r":"G00648","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. LXXI, 18</span> (Ms. <span dir=\"rtl\">זקנו׳</span>).</div>","alt":["זִקְנְתָא"]},"11756":{"h":"זָקַף","r":"G00649","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to join, put together, put up, erect, restore</i> (to proper position). <span class=\"citation\">Bets. II, 6</span> <span dir=\"rtl\">אין זוֹקְפִין וכ׳</span> you must not set up (put together the links of) a lamp on a Holy Day (v. <span class=\"citation\">ib. 22ᵃ</span>). <span class=\"citation\">M. Kat. 27ᵃ</span> <span dir=\"rtl\">מאימתי זוֹקְפִין וכ׳</span> from what time on the eve of the Sabbath are the mourners’ couches put up again? <span class=\"citation\">Ab. Zar. 46ᵃ</span> <span dir=\"rtl\">ז׳ לבינה וכ׳</span> if one put a brick up to worship it, v. <a href=\"#\" data-headword=\"זְקִיפָה\">זְקִיפָה</a>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"זָקוּף\">זָקוּף</a>, f. <a href=\"#\" data-headword=\"זְקוּפָא\">זְקוּפָה</a>. <span class=\"citation\">M. Kat. III, 7</span> <span dir=\"rtl\">מטה ז׳</span> a put-up couch, opp. <span dir=\"rtl\">מ׳ כפויה</span> an upset couch whereon mourners are seated; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"לָוָה\">לָוָה</a> a. Lat. nexus) <i>to establish a loan, to obligate, enjoin upon</i> (with <span dir=\"rtl\">על</span>). <span class=\"citation\">B. Mets. 72ᵃ</span> <span dir=\"rtl\">וזְקָפָן עליו במלוה</span> and the creditor settles the interests on the debtor as a loan (the note stating the combined amount of principle and interest as principle). <span class=\"citation\">Gitt. 18ᵃ</span> <span dir=\"rtl\">עד שתפגום ותִזְקוֹף</span> until she accepts partial payment (of her widowhood) and settles the balance as a loan (by taking a note &amp;c.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זָקְפָה ולא פגמה</span> if she allows her widowhood to be entered as a loan without taking a partial payment. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אונס … שזְקָפָן במלוה</span> indemnity for outrage, fines … which were settled in the way of a loan; a. e.</div><div class=\"sense\"><b>—3)</b>  (neut. verb) <i>to stand upright, to be restored again</i>. <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">לא נפלו … ולא זָקְפוּ</span> the bent walls did not fall, nor did they assume their straight position. <span class=\"citation\">Ber. 11ᵃ</span> וז׳ ר׳ ישמ׳ R. Y. remained upright, opp. <a href=\"#\" data-headword=\"נטי\">הִטָּה</a>. Ib. <span dir=\"rtl\">כשאני … אתה זָקַפְתָּ</span> when I bowed, thou didst remain upright. Y. ib. IV, beg. 7ᵃ <span dir=\"rtl\">זוֹקֵף</span> he erects himself (from his bowed position).—Part. pass. <a href=\"#\" data-headword=\"זָקוּף\">זָקוּף</a>, f. <a href=\"#\" data-headword=\"זְקוּפָא\">זְקוּפָה</a> <i>upright, erect</i>. Ber. l. c.—<span dir=\"rtl\">קומה זקופה</span> erect stature, <i>proud carriage</i>. Ib. 43ᵇ; a. fr.</div><div class=\"sense\"><b>Nif. נִזְקַף</b> <div class=\"sense\"><b>1)</b> <i>to be put up, to erect one’s self</i>. Tosef. ib. I, 6; <span class=\"citation\">Sifré Deut. 34</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be converted into a loan</i>. Gitt. l. c. <span dir=\"rtl\">מאימתי נִזְקָפִים במלוה</span> from what time are fines &amp;c. considered as converted loans (so as to be subject to limitation)?</div></div>","alt":[]},"11757":{"h":"זְקַף","r":"G00650","html":"<div class=\"sense\"><b>1)</b> <i>to put up, rear, erect, raise</i> (arms, head &amp;c.). <span class=\"citation\">Targ. Gen. XXXI, 45</span>. <span class=\"citation\">Targ. Y. Ex. XVII, 11</span> <a href=\"#\" data-headword=\"זְקִיף\">זָקֵיף</a>; a. fr.—<span class=\"citation\">Bets. 22ᵃ</span> <span dir=\"rtl\">ז׳ לה לשרגא</span> he put the lamp up. <span class=\"citation\">M. Kat. 25ᵃ</span> <span dir=\"rtl\">זַקְפֵיה לארוניה</span> he set his coffin upright.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"זְקִיף\">זְקִיף</a> q. v.</div><div class=\"sense\"><b>—2)</b> <i>to stand erect</i>. <span class=\"citation\">Targ. Job XXIX, 8</span>. <span class=\"citation\">Ib. XXIV, 24</span> זקופו Ms. (ed. <span dir=\"rtl\">אוריכו</span>) stand undiscouraged (wait).</div><div class=\"sense\"><b>—3)</b> <i>to hang up</i>. <span class=\"citation\">Targ. I Chr. X, 10</span>; a. e.—Part. pass. <a href=\"#\" data-headword=\"זְקִיף\">זְקִיף</a> <i>hanged</i>. <span class=\"citation\">B. Mets. 59ᵇ</span>, v. <a href=\"#\" data-headword=\"*דְּיוּקְתָּא\">דְּיוּקְתָּא</a>.</div><div class=\"sense\"><b>Af. אַזְקֵיף</b> <div class=\"sense\"><i>to elevate</i>, <span class=\"citation\">Targ. Ps. XXX, 2</span> (Regia <i>Pe</i>.; h. text <span dir=\"rtl\">דלה</span>).</div></div><div class=\"sense\"><b>Ithpa. אִזְדַּקֵּיף</b> </div><div class=\"sense\"><b>Ithpe. אִזְדְּקֵיף</b> <div class=\"sense\"><b>1)</b> <i>to be erect, to rise</i>. <span class=\"citation\">Targ. Gen. XXXVII, 7</span>. <span class=\"citation\">Targ. Ps. XXI, 14</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be hanged</i>. <span class=\"citation\">Meg. 16ᵇ</span> <span dir=\"rtl\">אִזְדַּקִּיפוּ</span>, v. <a href=\"#\" data-headword=\"זְקִיפָא II\"><span dir=\"rtl\">זְקִיפָא</span> II</a>.</div></div>","alt":["זְקוֹף"]},"11758":{"h":"זְקָפוּתָא","r":"G00651","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְקַף\">preced.</a>) <i>raising, lifting up</i>. <span class=\"citation\">Targ. Ps. CXLI, 2</span>.</div>","alt":[]},"11759":{"h":"זָקַק","r":"G00652","html":"<div class=\"sense\"> [<i>to make thin, fine, clear</i>,] </div><div class=\"sense\"><b>1)</b> <i>to distil, smelt</i>, v. <i>Pi.</i></div><div class=\"sense\"><a href=\"#\" data-headword=\"צָרַף\">צָרַף</a>) <i>to rivet, forge; to chain, to join; to bind, obligate</i>.—<i>Part. pass</i>. <span dir=\"rtl\">זָקוּק</span>, f. <a href=\"#\" data-headword=\"זְקוּקָה\">זְקוּקָה</a>; pl. <span dir=\"rtl\">זְקוּקִים</span>, <span dir=\"rtl\">זְקוּקִין</span>, f. <span dir=\"rtl\">זְקוּקוֹת</span>, with <a href=\"#\" data-headword=\"ל\">ל</a> <i>chained to, connected with, dependent on</i>. <span class=\"citation\">Men. 27ᵃ</span> <span dir=\"rtl\">העושין פירות יהיו ז׳ וכ׳</span> the fruit-bearing species of the festive wreath shall be combined with those which bear no fruits. <span class=\"citation\">Y. Ber. VI, 10ᵃ</span> bot. <span dir=\"rtl\">כשהיו כולן ז׳ וכ׳</span> when they were, all of them, dependent on one loaf (for saying grace). <span class=\"citation\">Pesik. R. s. 43</span> <span dir=\"rtl\">כנגד שלש … זקוקות להן</span> (not <span dir=\"rtl\">זקוקין</span>) corresponding to the three laws for which, our Rabbis taught, women are made responsible (<span class=\"citation\">Sabb. II, 6</span>). <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> top <span dir=\"rtl\">ז׳ למלכות</span> in constant intercourse with the government.—<span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">לשנים היא זקוקה</span> she is responsible to two (her husband and the Lord).—<span class=\"citation\">Shebu. VI, 3</span>. <span dir=\"rtl\">נכסים … זוֹקְקִין וכ׳</span> movable chattel binds the immovable with reference to the obligation of making oath, i.e. the two claims preferred in one suit are considered as one lawsuit, and the oath must refer to both; Y. Keth. XII, 36ᵃ bot. [read:] <span dir=\"rtl\">לזוֹקְקָן לשבועה</span> to combine the two (as one lawsuit) with regard to the oath. <span class=\"citation\">Yeb. II, 5</span> <span dir=\"rtl\">זוֹקֵק את וכ׳</span> he holds his brother’s wife tied to the leviratical marriage, i.e. she cannot marry otherwise until released from him; a. fr. V. <a href=\"#\" data-headword=\"זִיקָה\">זִיקָה</a>.</div><div class=\"sense\"><b>Nif. נִזְקַק</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"זָוַג\">זָוַג</a> <i>Nithpa.</i>) </div><div class=\"sense\"><b>1)</b> <i>to join, meet; to be engaged in</i>. <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">מעולם לא נ׳ וכ׳</span> the Lord never engaged in communication with woman. <span class=\"citation\">Gen. R. s. 42</span>; <span class=\"citation\">Pesik. R. s. 5</span>; a. e. <span dir=\"rtl\">נ׳ המלך וכ׳</span> the king was attached to, took an interest in the affairs of the country. <span class=\"citation\">Sabb. 12ᵇ</span> <span dir=\"rtl\">אין מ&quot;ה נִזְקָקִין לו</span> the angels do not attend to his prayers.—[</div><div class=\"sense\"><b>2)</b>  (in a hostile sense) <i>to attack</i>. Gen. R. l. c. <span dir=\"rtl\">באו ברברים לִיוָּקֵק לו</span> (Pesik. R. l. c.; Ruth R. introd., a. e. <span dir=\"rtl\">להִזְדַּוֵּוג</span>) Barbarians came to attack him.]</div><div class=\"sense\"><b>—3)</b> <i>to live with; to be coupled</i>. <span class=\"citation\">Ruth R. to IV, 3</span> <span dir=\"rtl\">ע&quot;מ שלא אֶזָּקֵק לה</span> with the condition that I will not live with her. <span class=\"citation\">Gen. R. s. 20</span> איני נִזְקֶקֶת וכ׳ I shall never again live with &amp;c.—<span class=\"citation\">Pesik. R. s. 15</span>; Pesik. Haḥod., p. 43ᵇ <span dir=\"rtl\">שיהא אדם נִזְקָק לביתו</span> in order that man be attached to his house (love his wife); <span class=\"citation\">Yalk. Ps. 738</span>; a. e.</div></div><div class=\"sense\"><b>Hif. הִזְקִיק</b> <div class=\"sense\"><i>to oblige</i>. <span class=\"citation\">Succ. 28ᵃ</span> <span dir=\"rtl\">הִזְקַקְתּוּנִי וכ׳</span></div></div><div class=\"sense\"><b>Hof. הוּזְקָק</b> <div class=\"sense\"><i>to be made dependent on, to obligate one’s self, to be obliged to regard</i>. <span class=\"citation\">B. Bath. 170ᵃ</span> אם הוּזְקָקוּ וכ׳ Ms. M. (ed. <span dir=\"rtl\">אם כתוב בו הוּזְקַקְנוּ</span></div></div><div class=\"sense\"><b>Nithpa. נִזְדַּקֵּק</b> <div class=\"sense\"><b>1)</b> <i>to be engaged in, to care</i>. Tanḥ. Korah 6 <span dir=\"rtl\">לא נִזְדַּקְּקוּ להשיבו</span> (<span class=\"citation\">Yalk. Num. 750</span> <span dir=\"rtl\">נִזְקָקוּ</span>) they did not care to answer him.</div><div class=\"sense\"><b>—2)</b> <i>to attach one’s self to, to make love to</i>. <span class=\"citation\">Num. R. s. 9</span>.</div><div class=\"sense\"><b>—3)</b>  (in an evil sense) <i>to get at, to harm</i>. <span class=\"citation\">Num. R. s. 5</span> <span dir=\"rtl\">בקש להִזְדּקֵּק להם</span> wanted to harm them.</div></div><div class=\"sense\"><b>Pi. זִיקֵּק</b> <div class=\"sense\"> (b. h.) <i>to smelt, refine, distil</i>. <span class=\"citation\">Lev. R. s. 31</span> <span dir=\"rtl\">עד שמְזַקְּקוֹ</span> until he has refined the gold.—<i>Part. pass</i>. <span dir=\"rtl\">מְזוּקָּק</span>, f. <span dir=\"rtl\">מְזוּקֶּקֶת</span>. <span class=\"citation\">Pesik. R. s. 14</span> <span dir=\"rtl\">התורה … ומז׳ וכ׳</span> the Torah is clarified and distilled in forty nine ways.—2) <i>to chain, tie, connect</i>.—Part. pass. as ab. Y. Ḥag. III, beg. 78ᵈ <span dir=\"rtl\">במז׳ לקדש</span> it treats of an object which is tied (has been made subject) to the law regulating sacred matter, i.e. treated as if it were sacred matter, v. <a href=\"#\" data-headword=\"טָהֳרָה\">טָהֳרָה</a>.</div></div>","alt":[]},"11760":{"h":"זְקַק","r":"G00653","html":"<div class=\"sense\"><b>1)</b> <i>to refine</i>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"זְקַק\">זָקִיק</a>. <span class=\"citation\">Targ. Ps. XII, 7</span>. <span class=\"citation\">Targ. Cant. I, 11</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to chain</i>. Part. pass. as above. <span class=\"citation\">Targ. Is. LX, 11</span> <a href=\"#\" data-headword=\"זְקִיפִין\">זְקִיקִין</a> led in chains (h. text <span dir=\"rtl\">נהוגים</span>).</div><div class=\"sense\"><b>—3)</b> <i>to obligate</i>. Part. pass. as ab. <span class=\"citation\">Y. Ber. I, 3ᶜ</span> bot. <span dir=\"rtl\">זְקִיקִינָן למברכה</span> we are bound to say the blessing. <span class=\"citation\">Y. B. Mets. X, beg. 12ᶜ</span> <span dir=\"rtl\">ז׳ את וכ׳</span> thou art bound to carry me (the lower story must be kept in repair at the expense of its owner). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דאינון זקוקין</span> (read: <span dir=\"rtl\">זקי׳</span>).</div><div class=\"sense\"><b>Pa. זַקֵּיק</b> <div class=\"sense\"><b>1)</b> <i>to refine</i>.—Part. pass. <span dir=\"rtl\">מְזוּקַּק</span> (Hebraism). <span class=\"citation\">Targ. Cant. I, 11</span>.</div><div class=\"sense\"><b>—2)</b> <i>to obligate, tie</i>. <span class=\"citation\">Yeb. 22ᵇ</span> top <span dir=\"rtl\">מיזקק נמי זַקִּיקָהּ</span> Rashi (ed. <a href=\"#\" data-headword=\"זְקַק\">זקיק</a>) he (the bastard brother) also ties her (prevents her from remarrying).</div></div><div class=\"sense\"><b>Ithpa. אִזְּדַּקֵּק</b> <div class=\"sense\">, contr. <span dir=\"rtl\">אִידַּקֵּק</span> <i>to be cleared</i>. <span class=\"citation\">Targ. Y. II, Num. V, 19</span> <span dir=\"rtl\">הִדַּקִּי</span> (h. text <span dir=\"rtl\">הִנָּקִי</span>).</div></div><div class=\"sense\"><b>Ithpe. אִיזְדְּקֵיק</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"זָקַק\">preced.</a> <i>Nif.</i> <span class=\"citation\">Ned. 77ᵃ</span> <span dir=\"rtl\">איזְדְּקִיקוּ ליה רבנן וכ׳</span> the Rabbis attended to (the absolution from vows of) the son &amp;c. Ib., sq. <span dir=\"rtl\">א׳ ליה רב וכ׳</span> Rab attended to Rabbah’s vows in a private room of the school-house &amp;c.—Y. Keth. II, 26ᶜ bot. <span dir=\"rtl\">אִיזְדְּקזּקֵי וכ׳</span></div></div>","alt":[]},"11761":{"h":"זַקָּק","r":"G00654","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"זִיקָא II\"><span dir=\"rtl\">זִיקָא</span> II</a>; cmp. <a href=\"#\" data-headword=\"זִיקוּקָא II\"><span dir=\"rtl\">זִיקוּקָא</span> II</a>) <i>maker of and dealer in leather bags</i>.—Pl. <span dir=\"rtl\">זַקָּקִין</span>. <span class=\"citation\">Mikv. IX, 5</span> <span dir=\"rtl\">של ז׳</span> saddles used by the dealers in hose (Ar.: <span dir=\"rtl\">של זִיקִין</span> saddles on which hose is carried).</div>","alt":[]},"11762":{"h":"זָקַר","r":"G00655","html":"<div class=\"sense\"> (cmp. Syr. <span dir=\"rtl\">זקר</span> P. Sm. 1151) <i>to thrust, fling</i>. <span class=\"citation\">Yoma 67ᵇ</span> זוֹקְרוֹ בת וכ׳ Ar. a. Mss. M. 2 a. O. (ed. <span dir=\"rtl\">זורקו</span>, v. Rabb. D. S. a. l. note), v. <a href=\"#\" data-headword=\"בַּת II\"><span dir=\"rtl\">בַּת</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to cast lots; to decide</i>.</div><div class=\"sense\"><b>Nif. נִזְקָר</b> </div><div class=\"sense\"><b>Nithpa. נִזְדַּקֵּר</b> <div class=\"sense\"><b>1)</b> <i>to be thrown; to leap, to stagger</i>. Ib. 38ᵇ, v. <a href=\"#\" data-headword=\"בַּת II\"><span dir=\"rtl\">בַּת</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>to be decided upon, to be decreed upon</i>. <span class=\"citation\">Erub. 52ᵇ</span> <span dir=\"rtl\">למקום שרובו הוא נזקר</span> (Var. <span dir=\"rtl\">נזד׳</span>) he is judged to belong to where the larger portion of his body is.—<span class=\"citation\">R. Hash. 18ᵃ</span> כולן נזקרין בזקירה אחת Ar. (Var. Ar., a. ed. <span dir=\"rtl\">נסקרין … בסקירה</span>) the fate of all of them is decided in one decree.—<span class=\"citation\">Ber. 46ᵃ</span> <span dir=\"rtl\">אל יִזְדַּקֵּר וכ׳</span> (Alf. a. oth. <span dir=\"rtl\">יִזְדַּקֵּק</span>, v. <a href=\"#\" data-headword=\"זָקַק\">זָקַק</a></div></div>","alt":[]},"11763":{"h":"זְקַר","r":"G00656","html":"<div class=\"sense\">, <i>Ithpa.</i> אִזְדַּקֵּר <i>to leap forth, to leap with joy; to stagger, reel</i>. <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">אִזְדַּקּוּר וכ׳</span> they leaped and ate and drank. <span class=\"citation\">Nidd. 17ᵇ</span> <span dir=\"rtl\">אִזְדַּקְּרָה</span> she staggered, jumped backward; <span class=\"citation\">ib. 57ᵇ</span>.—<span class=\"citation\">Lev. R. s. 5</span> (ref. to <span class=\"citation\">Is. XXII, 17</span>, v. <a href=\"#\" data-headword=\"גֶּבֶר\">גֶּבֶר</a>) <span dir=\"rtl\">כהדא תרנגולא … מִזְדַּקֵּר</span> Ar. (in ed. a. <span class=\"citation\">Yalk. Is. 291</span> our w. omitted) like a (slaughtered) cock that rolls from place to place in spasmodic thrusts.</div>","alt":[]},"11764":{"h":"זקַת","r":"G00657","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זקת <i>to sting</i>, P. Sm. 1151; cmp. <a href=\"#\" data-headword=\"זֵיק\">זֵיק</a>, <a href=\"#\" data-headword=\"זִיקָא I\">זִיקָא</a>) <i>goad</i>. <span class=\"citation\">Targ. I Sam. XIII, 21</span> (h. text <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽרְבָן</a>). <span class=\"citation\">Targ. Prov. XIV, 3</span> (some ed. <span dir=\"rtl\">וק׳</span>, corr. acc.).—Pl. <span dir=\"rtl\">זִקְתִּין</span>, <a href=\"#\" data-headword=\"זקַת\">זִיקְ׳</a>. <span class=\"citation\">Targ. Koh. XII, 11</span>. [<span class=\"citation\">B. Mets. 94ᵃ</span>, v. <a href=\"#\" data-headword=\"זִיקְתָא\">זִיקְתָא</a>.]</div>","alt":["זַקְתָּא","זִיקְ׳"]},"11765":{"h":"זֵר","r":"G00658","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זֵיר\">זֵיר</a></div>","alt":[]},"11766":{"h":"זָר","r":"G00659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"זוּר\">זוּר</a> a. </div><div class=\"sense\"><b>1)</b> <i>stranger;</i> (in Talm. mostly) <i>non-priest, layman</i>. <span class=\"citation\">Zeb. II, 1</span>. <span class=\"citation\">Ib. 14ᵃ</span>; <span class=\"citation\">Yoma 49ᵃ</span>; a. fr.—Fem. <a href=\"#\" data-headword=\"זָרָה\">זָרָה</a>. <span class=\"citation\">Yeb. 85ᵇ</span> <span dir=\"rtl\">ותהא ז׳ וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>oppressor, enemy</i>. <span class=\"citation\">Y. Ned. IX, beg. 41ᵇ</span> (ref. to <span dir=\"rtl\">אל זר</span>, <span class=\"citation\">Ps. LXXXI, 10</span>) <span dir=\"rtl\">זר שבקרבך וכ׳</span> do not make the enemy within thyself thy king; <span class=\"citation\">Sabb. 105ᵇ</span> <span dir=\"rtl\">איזהו אל זר וכ׳</span> which is the tyrannical power within thee?—<span class=\"citation\">Ex. R. s. 34</span> (play on <a href=\"#\" data-headword=\"זֵר\">זֵר</a> a. <a href=\"#\" data-headword=\"זָר\">זָר</a>, v. <a href=\"#\" data-headword=\"זֵיר\">זֵיר</a>) if one is worthy <span dir=\"rtl\">נעשים לו זֵר ואם לאו זר</span> they are to him a crown, if not—an enemy; Tanḥ. Vayakh. 8.—Fem. <a href=\"#\" data-headword=\"זָרָה\">זָרָה</a>. <span class=\"citation\">Yoma 72ᵇ</span> נעשית לו ז׳ Ms. O. (Ms. M. <span dir=\"rtl\">נעשית ז׳ ממנו</span>) the Law appears to him a tyrant (Ms. M. she becomes estranged from him, v. <a href=\"#\" data-headword=\"זוּר\">זוּר</a>).</div><div class=\"sense\"><b>—3)</b> <i>outcast; shunned, loathsome</i> (v. <a href=\"#\" data-headword=\"זָרָא\">זָרָא</a>). <span class=\"citation\">Num. R. s. 7</span> (play on <a href=\"#\" data-headword=\"זָרָא\">זָרָא</a>, <span class=\"citation\">Num. XI, 20</span>) <span dir=\"rtl\">והיאך נעשה ז׳ וכ׳</span> and how does he become an outcast? Leprosy overcomes him.—Pl. <span dir=\"rtl\">זָרִים</span>. Ib. <span dir=\"rtl\">ז׳ מן הקהל</span> excluded from the congregation.—<span class=\"citation\">Zeb. III, 1</span>; a. fr.</div>","alt":[]},"11767":{"h":"זָר ²","r":"G00660","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. XLIV, 19</span>, v. <a href=\"#\" data-headword=\"זְהַהּ\">זְהַהּ</a>.—<span class=\"citation\">Sabb. 82ᵇ</span>, v. <a href=\"#\" data-headword=\"נְכַר\">נְכַר</a>.</div>","alt":[]},"11768":{"h":"חֲנַךְ","r":"H01303","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Deut. XX, 5</span>; a. e.</div><div class=\"sense\"><b>Pa. חַנֵּיךְ</b> </div><div class=\"sense\"><b>Af. אַחְנִיךְ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָנַךְ\">same</a>. Ib. <span dir=\"rtl\">חַנְּכֵיה</span> (ed. Berl. <a href=\"#\" data-headword=\"חֲנוּכְּתָא\">חַנְכֵ׳</a> <i>Pe</i>.). <span class=\"citation\">Targ. Y. I Deut. XXXII, 3</span>, <span class=\"citation\">Targ. Y. II, Deut. XXXII, 3</span> (sanctified his mouth); a. e.</div></div>","alt":["חֲנֵיךְ"]},"11769":{"h":"חֲנֻכָּה","r":"H01304","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנוּכָּה\">חֲנוּכָּה</a></div>","alt":[]},"11770":{"h":"חִנְכֵי","r":"H01305","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִינְכֵי\">חִינְכֵי</a></div>","alt":[]},"11771":{"h":"חֲנֻכְּתָא","r":"H01306","html":"<div class=\"sense\">, v. <span dir=\"rtl\">חֲנוּכְּ׳</span></div>","alt":[]},"11772":{"h":"חִנָּם","r":"H01307","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>gratuitous act, favor</i>, mostly adv. <span dir=\"rtl\">בח׳</span>, <span dir=\"rtl\">לח׳</span>, <span dir=\"rtl\">על ח׳</span> <i>gratuitously; for no reason</i>. <span class=\"citation\">Ex. R. s. 41</span> <span dir=\"rtl\">על ח׳ בראתני וכ׳</span> hast thou created me for no purpose?—<span class=\"citation\">B. Kam. 92ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"זַרְזִיר I\">זַרְזִיר</a>. <span class=\"citation\">Ex. R. s. 28</span>, beg. <span dir=\"rtl\">נטלה ח׳</span> he took it gratuitously. <span class=\"citation\">Num. R. s. 1</span> <span dir=\"rtl\">מה אלו ח׳ וכ׳</span> as these things (fire, water &amp;c.) are free to all &amp;c.—מַתְּנַת ח׳ <i>an undeserved gift</i>. <span class=\"citation\">Num. R. s. 11</span>; a. fr.—שִׂנְאַת ח׳ <i>gratuitous hatred, hostility without cause</i>. <span class=\"citation\">Sabb. 32ᵇ</span>; a. fr.</div>","alt":[]},"11773":{"h":"חֲנַמְאֵל","r":"H01308","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Hanameel</i>, </div><div class=\"sense\"><b>1)</b>  cousin of Jeremiah. <span class=\"citation\">Meg. 14ᵇ</span>; a. e.</div>","alt":[]},"11774":{"h":"חֲנָמַל","r":"H01309","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>beetle</i>, prob. a species of <i>locusts</i>. <span class=\"citation\">Yalk. Ex. 185</span>, quot. fr. Tanḥ. (ed. Bub., Vaëra 19) <span dir=\"rtl\">כח׳ הזה היה יורד</span> the hail came down formed like the <i>ḥănâmal</i>, as it says (<span class=\"citation\">Ps. LXXVIII, 47</span>) &amp;c.—Midr. Till. to Ps. l. c., v. <a href=\"#\" data-headword=\"חָנָה\">חָנָה</a>.</div>","alt":[]},"11775":{"h":"חנן","r":"H01310","html":"<div class=\"sense\">, <span class=\"citation\">Y. Peah I, 16ᵇ</span> <span dir=\"rtl\">מה ח׳ קיימין</span>, read, as <span class=\"citation\">Y. Snh. X, beg. 27ᶜ</span>, <span dir=\"rtl\">מה נן</span>. [חנן Syr., rare form, v. P. Sm. 250 s. v. <span dir=\"rtl\">אנא</span>.]</div>","alt":[]},"11776":{"h":"חָנַן","r":"H01311","html":"<div class=\"sense\"> [<i>to cover, surround</i>,] <i>to caress, grace, favor</i>. <span class=\"citation\">Sabb. 104ᵃ</span> (in children’s acrostics) <span dir=\"rtl\">זֹן אותך וחָ֗ן אותך</span> sustains and graces thee. <span class=\"citation\">Num. R. s. 11</span> (ref. to <span class=\"citation\">Num. VI, 25</span>) <span dir=\"rtl\">יָחוֹן איתך בבנים</span> may He favor thee with (good) children. Ib. (quot. from daily prayers) <span dir=\"rtl\">אתה חוֹנֵן לאדם דעת</span> thou graciously endowest man with knowledge. Ib. <span dir=\"rtl\">עתיד הקב&quot;ה לָחוֹן עליהם</span> the Lord will in due time protect them. <span class=\"citation\">Sifré Num. 41</span> <span dir=\"rtl\">יָחְנְךָ בתלמוד תורה</span> may He grace thee by enabling thee to study the Law. Pesik. Asser, p. 97ᵃ (ref. to <span dir=\"rtl\">מהונך</span>, <span class=\"citation\">Prov. III, 9</span>) <span dir=\"rtl\">ממה שחֲנָנְךָ</span> out of what He has endowed thee with; a. fr.—[<span class=\"citation\">Midr. Till. to Ps. LXXVIII</span> <a href=\"#\" data-headword=\"חָן\">חָן</a>, v. <a href=\"#\" data-headword=\"חָנָה\">חָנָה</a>.]—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חַנִּין\">חָניּן</a>, pl. <span dir=\"rtl\">חֲנוּנִים</span> </div><div class=\"sense\"><b>1)</b> <i>graced, endowed</i>. Num. R. l. c. <span dir=\"rtl\">חֲנוּנֵי</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<a href=\"#\" data-headword=\"דַּעַת\">דעת</a> endowed with knowledge. <span class=\"citation\">Pes. 87ᵃ</span> <span dir=\"rtl\">בני חֲנוּנֶיךָ</span> children of thy favored ones, Abraham &amp;c. (Ms., v. <a href=\"#\" data-headword=\"בָּחַן\">בָּחַן</a>).</div><div class=\"sense\"><b>—2)</b> <i>bandaged.</i> Pl. fem. <span dir=\"rtl\">חֲנוּנוֹת</span>. <span class=\"citation\">Sabb. V, 4</span>, v. <a href=\"#\" data-headword=\"חָנוּן I\"><span dir=\"rtl\">חָנוּן</span> I</a>, 2.</div><div class=\"sense\"><b>Nif. נֶחֱנָן</b> <div class=\"sense\"><i>to be shown favor</i>. <span class=\"citation\">Deut. R. s. 7</span> (ref. to <span class=\"citation\">Is. XXVI, 10</span>) <span dir=\"rtl\">אבל אם למד … אינו נ׳</span> but if he has learned …, he will be shown no favor (will not be forgiven).</div></div><div class=\"sense\"><b>Hithpa. מִתְחַנֵּן</b> <div class=\"sense\"><i>to bend one’s self, to supplicate</i> (v. <a href=\"#\" data-headword=\"תְּחִנָּה\">תְּחִנָּה</a>). <span class=\"citation\">Deut. R. s. 2</span>, beg. <a href=\"#\" data-headword=\"חָנַן\">מִתְחַנֵּן</a>, v. <a href=\"#\" data-headword=\"חָבַט\">חָבַט</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">התחיל להִתְחַנֵּן</span> (<span dir=\"rtl\">התחיל מתחנן</span>) he began to pray; a. fr.</div></div><div class=\"sense\"><b>Hithpol. חוּן</b> <div class=\"sense\"> = <a href=\"#\" data-headword=\"חָנָה\">חָנָה</a>) <i>to come to rest, to be collected</i>. <span class=\"citation\">Ber. 30ᵇ</span> (adopting the expression in conformity with <span dir=\"rtl\">ואתחנן</span>, <span class=\"citation\">Deut. III, 23</span>) until his mind be collected again (for prayer), v. <a href=\"#\" data-headword=\"חוּל\">חוּל</a>.</div></div>","alt":["(חוּן)"]},"11777":{"h":"חֲנַן","r":"H01312","html":"<div class=\"sense\"> ch., pret. <a href=\"#\" data-headword=\"חַן\">חַן</a> same. <span class=\"citation\">Targ. O. Gen. XXXIII, 5</span>.—<span class=\"citation\">Targ. O. Ex. XXXIII, 19</span> <span dir=\"rtl\">אֵיחוֹן</span>. <span class=\"citation\">Targ. Jud. XXI, 22</span> <span dir=\"rtl\">חֲנוּנוּן להון</span> ed. Lag. (oth. ed. <span dir=\"rtl\">חנינינון</span>) be gracious to them.—<span class=\"citation\">Pes. 110ᵇ</span> (in an incantation) <span dir=\"rtl\">אדחֲנַנִי וחֲנַנְכִי וכ׳</span> while He graced me and yourselves, I had not come to that (v. Ar. s. v. <a href=\"#\" data-headword=\"הַר\">הר</a> 8, a. Rabb. D. S. a. l. note for var. lect.).</div>","alt":["חוּן"]},"11778":{"h":"חָנָן","r":"H01313","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Hanan</i>, name of several Tannaim and of several Amoraim, esp. <i>H.</i>, one of the Justices of Peace in Jerusalem, v. <a href=\"#\" data-headword=\"אַדְמוֹן\">אַדְמוֹן</a>. <span class=\"citation\">Keth. XIII, 1</span>. Y. ib. 35ᶜ a. fr.—<i>Ḥ. the Egyptian</i>: <span class=\"citation\">Snh. 17ᵇ</span>; a. e.—H. (interch. with <span dir=\"rtl\">הנין</span>). <span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">אסיקו ליה ח׳ וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"חַנִּין\">חנין</a>) they gave him the name of H. from his father (Hanin).—<span class=\"citation\">Y. Yeb. XI, 12ᵃ</span> top (ed. Krot. <a href=\"#\" data-headword=\"חָנוּן I\">חָנוּן</a>). <span class=\"citation\">Y. Sot. VII, 21ᵈ</span> bot. <span dir=\"rtl\">חנינן</span>.—<span class=\"citation\">Y. Ber. IV, beg. 7ᵃ</span> <span dir=\"rtl\">(<span dir=\"rtl\">ח׳ בר ווא</span>) <span dir=\"rtl\">ח׳ בר אבא</span></span>; <span class=\"citation\">Y. Pes. IV, 31ᵃ</span> <a href=\"#\" data-headword=\"חַנִּין\">חנין</a>; a. oth.—V. Frank. M’bo p. 86ᵃ</div>","alt":[]},"11779":{"h":"חַנָּנָא","r":"H01314","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"חַנּוּן\">חַנּוּן</a>. <span class=\"citation\">Targ. Ex. XXII, 26</span>. <span class=\"citation\">Targ. Ps. CXI, 4</span> (ed. Lag. <a href=\"#\" data-headword=\"חֵינָנָא\">חֵינָנָא</a>); a. e.</div>","alt":["חֲנָנָא"]},"11780":{"h":"חֲנַנְאֵל","r":"H01315","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Hananeel</i>. <span class=\"citation\">Y. Keth. XIII, 35ᵈ</span> top; a. e.</div>","alt":[]},"11781":{"h":"חֲנַנְיָא","r":"H01316","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Hanania;</i> </div><div class=\"sense\"><b>1)</b>  H., one of the Babylonian exiles at the Babylonian court. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">אישתא דח׳ וכ׳</span> the fire prepared for H., Mishael and Azariah. <span class=\"citation\">Snh. 93ᵃ</span> <span dir=\"rtl\">כי היכי … לחּ׳ וכ׳</span> as I tested H. &amp;c.; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  several Tannaim and Amoraim (interchanging with <a href=\"#\" data-headword=\"חֲנִינָא\">חֲנִינָא</a> q. v.); esp. <i>Ḥ.</i> <i> b. ʿAkashia</i>: <span class=\"citation\">Macc. III, 16</span>. <span class=\"citation\">Tosef. Shek. III, 18</span>.—<i>H. b. T’radion</i>, a martyr of the Adrianic persecution. <span class=\"citation\">Tosef. Kel. B. Kam. IV, 17</span>. <span class=\"citation\">Ab. Zar. 17ᵇ</span>, sq. <a href=\"#\" data-headword=\"חֲנִינָא\">(חנינא</a>). <span class=\"citation\">Taan. 16ᵇ</span>; a. fr.—<i>H. b. ʿAkabia</i>: <span class=\"citation\">M. Kat. 21ᵃ</span>; (<span class=\"citation\">Keth. VIII, 1</span>, a. fr. <a href=\"#\" data-headword=\"חֲנִינָא\">חנינא</a>); a. e.—<i>H.</i>, ‘<i>the Haber of the Rabbis</i>’. <span class=\"citation\">Y. Ter. VIII, 45ᶜ</span>; (<span class=\"citation\">Y. Ber. I, 2ᶜ</span> top. <a href=\"#\" data-headword=\"חֲנִינָא\">חנינא</a>); a. fr.—Other Amoraim by that name, v. Frank. M’bo, p. 88ᵇ, sq.—<a href=\"#\" data-headword=\"חֲזִיז II\">כְּפַר ח׳</a> pr. n. pl. <i>K’far Hanania</i> in Galilee. <span class=\"citation\">Shebi. IX, 2</span>; a. fr.</div>","alt":["חֲנַנְיָה"]},"11782":{"h":"חנסי","r":"H01317","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָגָס\">חָגָס</a></div>","alt":[]},"11783":{"h":"חֲנִסְנְסַיָּא","r":"H01318","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲנִיסְנְסַיָּא\">חֲנִיסְנְ׳</a></div>","alt":[]},"11784":{"h":"חָנַף","r":"H01319","html":"<div class=\"sense\"> (b. h.) [<i>to bend, decline</i> from the right path,] <i>to be insincere, to flatter; to show favor in court; to deceive</i>. <span class=\"citation\">Der. Er. Zuta ch. II</span></div><div class=\"sense\"><b>Hif. הֶחְנִיף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲנִסְנְסַיָּא\">same</a>. <span class=\"citation\">Sot. 41ᵇ</span> <span dir=\"rtl\">הִחְנִיפוּ לו וכ׳</span> thy flattered Agrippa (saying to him, ‘Thou art our brother’). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מותר להַחְנִיף וכ׳</span> it is permissible to flatter (submit to the power of) the wicked &amp;c. Y. Ber. VII, 11ᶜ. <span class=\"citation\">Pesik. R. s. 25</span> (ref. to <span class=\"citation\">Is. XXIV, 5</span>) <span dir=\"rtl\">הבריות מַהֲנִיפִים זה לזה</span> men deal insincerely with one another; <span dir=\"rtl\">והוא מַחֲנִיפוֹ וכ׳</span> and he puts him (the priest or Levite) off with deceptive intent, and says &amp;c.; a. fr.</div></div>","alt":["חָנֵף"]},"11785":{"h":"חֲנֵף","r":"H01320","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"חֲנֵיף\">חַנֵּיף</a> ch. same. <span class=\"citation\">M. Kat. 17ᵃ</span> <span dir=\"rtl\">דאפי׳ … לא חַנִּיפִי ליה</span> not even a man like thee did I flatter. <span class=\"citation\">Shebu. 30ᵃ</span> <span dir=\"rtl\">לחַנּוּפֵי ליה</span> that I should favor him in court?—<span class=\"citation\">Keth. 84ᵇ</span> <span dir=\"rtl\">מְחַנְּפִיתוּ להו</span> would you favor them?; <span class=\"citation\">ib. 63ᵇ</span> <span dir=\"rtl\">מַחְנִיפִיתוּ ליה</span> (<i>Af.</i>) would you favor him?—Pesik. Asser, p. 98ᵃ (ref. to <span class=\"citation\">Is. XXIV, 5</span>) <span dir=\"rtl\">את סבר מְחַנְּפָא לה והיא מְחַנְּפָה לך</span> thou meanest to deceive it (the land by withholding the tithes, v. <a href=\"#\" data-headword=\"חָנַף\">preced.</a>), but it will disappoint thee; Tanḥ. R’eeh 14 <span dir=\"rtl\">את כבר מחנף וכ׳</span> (corr. acc.).</div><div class=\"sense\"><b>Af. אַחְנִיף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָנַף\">same</a>, v. supra.</div></div>","alt":[]},"11786":{"h":"חָנֵף","r":"H01321","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חֲנֵף\">preced.</a> wds.) <i>hypocrite, flatterer; faithless, arbitrary, fickle</i>. <span class=\"citation\">Esth. R. to I, 1</span> (ref. to <span class=\"citation\">Job XXXIV, 30</span>) <span dir=\"rtl\">בשעה שהמלך ח׳ וכ׳</span> when a king is arbitrary and rules tyrannically &amp;c. Ib. <span dir=\"rtl\">שהיה ח׳ וכ׳</span> for he (Ahasverus) was arbitrary, for he put to death &amp;c.—Pl. <span dir=\"rtl\">חֲנֵפִים</span>, <span dir=\"rtl\">חֲנֵפִין</span>, <span dir=\"rtl\">חֲנֵי׳</span>. Tosef. Yoma V (IV), 12; <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">מפרסמין את החנ׳ וכ׳</span> you may expose the hypocrites to prevent defamation of the divine Name. <span class=\"citation\">Koh. R. to IV, 1</span> <span dir=\"rtl\">חֲנֵיפֵי תורה</span> pretenders of scholarship. <span class=\"citation\">Sot. 42ᵃ</span>; <span class=\"citation\">Treat. Der. Er. ch. II</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חֲנֵפוֹת</span> (masc., v. <a href=\"#\" data-headword=\"מָסוֹר\">מָסוֹר</a>); a. e.</div>","alt":[]},"11787":{"h":"חֲנֵפָא","r":"H01322","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. X, 6</span>.—<span class=\"citation\">Esth. R. to I, 1</span> <span dir=\"rtl\">מלכא ח׳</span> an arbitrary King, v. preced.—Pl. <span dir=\"rtl\">חֲנֵפִין</span>, <span dir=\"rtl\">חֲנִי׳</span>. <span class=\"citation\">Targ. Is. IX, 16</span>.</div>","alt":["חֲנֵיפָא"]},"11788":{"h":"חֲנֻפְתָּא","r":"H01323","html":"<div class=\"sense\">, v. <span dir=\"rtl\">חֲנוּפְ׳</span></div>","alt":[]},"11789":{"h":"חָנַק","r":"H01324","html":"<div class=\"sense\"> [<i>to press</i>,] <i>to seize by the throat, to choke</i>. <span class=\"citation\">Tosef. Sabb. III</span> (<span class=\"citation\">IV), 6</span> <span dir=\"rtl\">ואין חוֹנְקִין בשבת</span> you must not press (the jugular veins, to relieve from belly-ache) on the Sabbath; v. infra <i>Pi.</i>—<span class=\"citation\">B. Bath. X, 8</span> (<span class=\"citation\">175ᵇ</span>) <span dir=\"rtl\">הרי החוֹנֵק את וכ׳</span> if one seizes a debtor by the throat (threatening violence). Ib. 176ᵃ <span dir=\"rtl\">בחָנוּק</span> in the case of one being threatened (and another pledging himself for him). <span class=\"citation\">Sabb. 57ᵃ</span> <span dir=\"rtl\">אין אשה חוֹנֶקֶת וכ׳</span> a woman will not choke herself (will not tie a band around her neck so closely that no water could get under it when bathing); <span class=\"citation\">ib.ᵇ</span> <span dir=\"rtl\">אשה ח׳ וכ׳</span> a woman does tie a chain closely in order to appear fleshy. <span class=\"citation\">Gen. R. s. 34</span> (ref. to <span dir=\"rtl\">דם האדם באדם</span>, <span class=\"citation\">Gen. IX, 6</span>) <span dir=\"rtl\">אף החוֹנְקוֹ</span> (the gentile is guilty of bloodshed) even if he only chokes a man (‘shedding the blood of man in man’); <span class=\"citation\">Y. Kidd. I, 58ᶜ</span> top <span dir=\"rtl\">בחונקו מפני עצמו</span> (read: <span dir=\"rtl\">ממונו</span>) when he merely chokes him to take his money; a. e.—Esp. <i>to strangle to death</i>. <span class=\"citation\">B. Kam. 47ᵇ</span> <span dir=\"rtl\">ח׳ את עצמו</span> (the ox) strangled himself (by being caught in a rope). <span class=\"citation\">Y. Sot. IX, 23ᶜ</span> <span dir=\"rtl\">נמצא חָנוּק</span> if he was found strangled; a. e.—Trnsf. <i>to produce anguish, agony</i>. <span class=\"citation\">Ḥull. I, 2</span> <span dir=\"rtl\">מפני שהן חוֹנְקִין</span> because they (a saw &amp;c.) cause agony as if by choking (instead of cutting).—[<span class=\"citation\">Kidd. 62ᵃ</span> (ref. to <span class=\"citation\">Num. V, 19—20</span>) according to R. Meïr (who says that a condition is not valid unless both the negative and the positive alternatives are stated) <span dir=\"rtl\">חִנְקִי מיבעי ליה</span> it ought to have been added (to vers 20) ‘die in agony’. <span dir=\"rtl\">א&quot;ר תנחום הנקי כתיב</span> said R. T. it says (verse 19) <i>hnki</i> (which may be read <i>hinnaki</i> for the one alternative and <i>hinki</i> for <i>ḥinki</i> for the other); Ar. reads <span dir=\"rtl\">הנקי</span>, v. <a href=\"#\" data-headword=\"נָּקִי I\">נָקִי</a>.]</div><div class=\"sense\"><b>Nif. נֶחְנַק</b> <div class=\"sense\"><b>1)</b> <i>to be strangled</i>. <span class=\"citation\">Snh. XI, 1</span> (<span class=\"citation\">84ᵇ</span>) <span dir=\"rtl\">הנֶחְנָקִין</span> those sentenced to death by strangulation. <span class=\"citation\">Pes. 112ᵃ</span> <span dir=\"rtl\">לֵיחָנֵק</span>, v. <a href=\"#\" data-headword=\"אִילָּן\">אִילָּן</a>.</div><div class=\"sense\"><b>—2)</b> <i>to feel like choking, to be sorry</i> (cmp. <a href=\"#\" data-headword=\"אֲנַק\">אָנַק</a>). <span class=\"citation\">Cant. R. to IV, 12</span> <span dir=\"rtl\">התחיל … רואה ונ׳</span> the seller sees it and grieves (over his loss); <span class=\"citation\">Yalk. Ex. 225</span> Mekh. B’shall. s. 1 <span dir=\"rtl\">לֵיחָנֵק</span>.—[<span class=\"citation\">Sabb. 66ᵇ</span>, v. infra.]</div></div><div class=\"sense\"><b>Pi. חִינֵּק</b> <div class=\"sense\"><b>1)</b> <i>to squeeze in, immure</i>. <span class=\"citation\">Pirké d’R. El. ch. XLVIII</span>; <span class=\"citation\">Yalk. Ex. 169</span> <span dir=\"rtl\">(<span dir=\"rtl\">היו</span>) <span dir=\"rtl\">מְחַנְּקִין את ישראל וכ׳</span></span> pressed Israelites between the walls (having mingled their bodies with the clay).</div><div class=\"sense\"><b>—2)</b> <i>to strangle</i>. <span class=\"citation\">Tosef. M. Kat. I, 5</span> <span dir=\"rtl\">מְחַנְּקִין וכ׳</span> (<span class=\"citation\">M. Kat. 6ᵇ</span> <span dir=\"rtl\">חונקין</span>) the aunts choke each other to death.</div><div class=\"sense\"><b>—3)</b> <i>to press the throat, to squeeze the jugular veins</i> (an operation applied in cases of abdominal affection, Ar. s. v. <span dir=\"rtl\">חנק</span>; <i>to reset a laryngal muscle or ring</i>, Rashi; oth. defin., v. Ar. s. v.). <span class=\"citation\">Sabb. 66ᵇ</span> <span dir=\"rtl\">לְחַנֵּק</span> to perform the operation (Rashi a. Ar. ed. Koh. <span dir=\"rtl\">לֵיחָנֵק</span> to have the operation performed).</div></div>","alt":[]},"11790":{"h":"חֲנַק","r":"H01325","html":"<div class=\"sense\"><i>to strangle</i>. Targ. II Esth. I, 3.—<span class=\"citation\">Keth. 60ᵇ</span> <span dir=\"rtl\">וחֲנַקְתֵּיה</span> she choked her child to death; <span dir=\"rtl\">דלא … דחַנְקַן בנייהו</span> for women (of sound mind) will not choke their children (in order to be allowed to marry again before the lapse of a certain time). <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> top … <span dir=\"rtl\">הוה והוה ח׳ ליה</span> air burst forth out of the bottle and choked him. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> <span dir=\"rtl\">חַנְקַת גרמה</span> she hanged herself. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> top <span dir=\"rtl\">בעייא … מִיחְנְקוּנֵיה</span> I would rather choke him; a. e.—<span class=\"citation\">Gitt. 67ᵇ</span> <span dir=\"rtl\">דחַנְקָא</span>, v. <a href=\"#\" data-headword=\"דִּיסְתָּנָא ²\"><span dir=\"rtl\">דִּיסְתָּנָא</span> I</a>.</div><div class=\"sense\"><b>Ithpa. אִתְחַנֵּק</b> <div class=\"sense\"><i>to hang one’s self</i>. <span class=\"citation\">Targ. II Sam. XVII, 23</span>.—Y. Snh. X, 29ᵃ bot. <span dir=\"rtl\">כדון דוד מִתְחַנֵּק</span> now David will die in despair (cmp. <a href=\"#\" data-headword=\"חָנַק\">preced.</a> <i>Nif.</i>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יהא סופיה מִתְחַנְּקָא</span> will end his life by suicide.</div></div>","alt":[]},"11791":{"h":"חֶנֶק","r":"H01326","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲנַק\">preced.</a> wds.) <i>execution by strangulation</i>. <span class=\"citation\">Snh. VII, 1</span>; a. fr.</div>","alt":[]},"11792":{"h":"חֲנָקָא","r":"H01327","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֶנֶק\">preced.</a> wds.), pl. <span dir=\"rtl\">חֲנָקִין</span>, <span dir=\"rtl\">חֲנֵיקִ׳</span> <i>ropes</i> or <i>chains</i> around the neck. <span class=\"citation\">Targ. Jer. II, 20</span>. <span class=\"citation\">Ib. XXVII, 2</span>; a. e.</div>","alt":["חֲנֵיקָא"]},"11793":{"h":"חַס","r":"H01328","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חוּס\">חוּס</a>) <i>sparing, forbearance</i>, only (adverbial) <span dir=\"rtl\">חַס וְשָׁלוֹם</span> <i>forbearance and peace!, God forfend!, don’t say that!</i> <span class=\"citation\">Eduy. V, 6</span> ח׳ וש׳ שעקביא וכ׳ God forbid (to think) that ʿAkabia was excommunicated! <span class=\"citation\">Sabb. 138ᵇ</span> ח׳ וש׳ שתשתכח וכ׳ God forbid (to entertain the idea) that the Law will be forgotten &amp;c. <span class=\"citation\">B. Mets. 85ᵇ</span> <span dir=\"rtl\">ח׳ וש׳ אי וכ׳</span> if, which God forfend, the Law should be forgotten &amp;c.—Y. Pes. VI, 33ᵃ bot. (in Chald. phraseology) <span dir=\"rtl\">ח׳ וש׳ דהוה בעי לה</span> God forbid (to think) that he would have done it!; a. v. fr.</div>","alt":[]},"11794":{"h":"חַס ²","r":"H01329","html":"<div class=\"sense\">; <span dir=\"rtl\">חס ל־</span> [<i>God spare him!</i>,] <i>far from him!</i> <span class=\"citation\">Targ. Gen. XLIV, 7</span> (h. text <a href=\"#\" data-headword=\"חָלִילָה\">חָלִילָה</a>); a. e.,—<span class=\"citation\">Kidd. 44ᵇ</span> <span dir=\"rtl\">וחס ליה לזרעיה וכ׳</span> and far it is from the son of Abba … (Samuel) to have said so; <span class=\"citation\">Ḥull. 111ᵇ</span>. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. <span dir=\"rtl\">חס ליה לא וכ׳</span></div>","alt":[]},"11795":{"h":"חֲסָא","r":"H01330","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*חֲסִי\">חֲסִי</a></div>","alt":[]},"11796":{"h":"חָסָא I","r":"H01331","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. fr. <a href=\"#\" data-headword=\"חוּס\">חוס</a> <i>to bend</i>, cmp. <span class=\"citation\">Ber. 56ᵃ</span> quoted below) <i>lettuce</i> (h. <a href=\"#\" data-headword=\"חֲזֶרֶת\">חֲזֶרֶת</a>). <span class=\"citation\">Pes. 39ᵃ</span>, v. <a href=\"#\" data-headword=\"חוּס\">חוּס</a> ch. <span class=\"citation\">Ib. 116ᵃ</span>, v. <a href=\"#\" data-headword=\"חַמָּא\">חַמָּא</a>. <span class=\"citation\">Ber. 56ᵃ</span> (to one who dreamt that he saw lettuce on the wine keg) <span dir=\"rtl\">עיף עיסקך כח׳</span> thy business will be doubled (thrive) like lettuce; <span dir=\"rtl\">מריר … ח׳</span>, v. <a href=\"#\" data-headword=\"מָרִיר I\"><span dir=\"rtl\">מָרִיר</span> I</a>. Y. Kil. I, 27ᵃ top (expl. <span dir=\"rtl\">חזרת גלים</span>) <span dir=\"rtl\">חַס דגורין</span> (constr.), v. <a href=\"#\" data-headword=\"דְּגוֹרָא\">דְּגוֹרָא</a>.—Pl. <a href=\"#\" data-headword=\"חָסִין\">חָסִין</a>. Y. Maas. Sh. IV, end, 55ᶜ top., v. <a href=\"#\" data-headword=\"*בַּסִּין\">בַּסִּין</a>. <span class=\"citation\">Gen. R. s. 67</span> <span dir=\"rtl\">ח׳ רברבין</span> large (old) lettuce plants. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳ 1) <span dir=\"rtl\">מיסרא דח׳</span></div>","alt":[]},"11797":{"h":"חָסָא II","r":"H01332","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥasa</i>. <span class=\"citation\">Yeb. 121ᵇ</span></div>","alt":[]},"11798":{"h":"חסאין","r":"H01333","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. V, 13</span>, read: <span dir=\"rtl\">הס׳</span>, v. <a href=\"#\" data-headword=\"סוּג II\"><span dir=\"rtl\">סוּג</span> II</a></div>","alt":[]},"11799":{"h":"חָסַד I","r":"H01334","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָסַד II\">next w.</a>) <i>to be white, pure, charitable, graceful</i>.—Part. pass. <span dir=\"rtl\">חָסוּד</span>, fem. <a href=\"#\" data-headword=\"חֲסוּדָה I\">חֲסוּדָה</a>, <i>endowed with</i> <a href=\"#\" data-headword=\"חֶסֶד\">חֶסֶד</a>, <i>graceful</i>. <span class=\"citation\">Keth. 17ᵃ</span> (in a bridal song) <span dir=\"rtl\">כלה נאה וח׳</span> handsome and graceful bride. <span class=\"citation\">Num. R. s. 12</span>; <span class=\"citation\">Cant. R. to III, 10</span> (not <a href=\"#\" data-headword=\"חֲסִידָה\">חסידה</a>).</div>","alt":[]},"11800":{"h":"חָסַד II","r":"H01335","html":"<div class=\"sense\"> ; <i>Pi</i>. <a href=\"#\" data-headword=\"חָסַד I\">חִסֵּד</a>, <span dir=\"rtl\">חִשֵּׂד</span> [<i>to scrape off</i>,] (cmp. <span dir=\"rtl\">גדף</span>, <span dir=\"rtl\">גרף</span>) <i>to jeer, scoff at, to shame</i>. <span class=\"citation\">Ruth R. to IV, 8</span> <span dir=\"rtl\">שחִסְּדָן ברבים</span> (or <span dir=\"rtl\">שחֲסָדָן</span>; ed. Wil. <span dir=\"rtl\">שחשדן</span>) he scoffed at them publicly (speaking ironically, with ref. to <span class=\"citation\">II Chr. XIII, 8</span>); Y. Yeb. XVII, beg. 15ᶜ <span dir=\"rtl\">שחִישֵּׂד וכ׳</span> he jeered at Jeroboam; <span class=\"citation\">Gen. R. s. 65</span>; ib. s. 73 <span dir=\"rtl\">שחסדם</span> ed. Wil. (oth. <span dir=\"rtl\">שחש׳</span>); <span class=\"citation\">Lev. R. s. 33</span>; Midr. Sam. ch. XVIII <span dir=\"rtl\">שחִיסְּדָן</span>; <span class=\"citation\">Yalk. Kings 205</span> <span dir=\"rtl\">ומְחַשֵּׂד</span>.—<span class=\"citation\">Ex. R. s. 30</span> (ref. to <span class=\"citation\">Ex. II, 14</span>) <span dir=\"rtl\">שחִיסְּדוּ וכ׳</span> when Dathan and Abiram sneered at him. Ib. <span dir=\"rtl\">בזה שחִיסַּדְתֶּם אותו וכ׳</span> with the very word (<a href=\"#\" data-headword=\"שׁוֹפֵט\">שופט</a>) with which you sneered at him, I shall give him the rulership <span dir=\"rtl\">(משפטים</span>). <span class=\"citation\">Pesik. R. s. 42</span> <span dir=\"rtl\">מְחַסְּדִים את שרה</span> (not <span dir=\"rtl\">מחסרו׳</span>) jeered at Sarah; a. e.—V. <a href=\"#\" data-headword=\"חִיסּוּד\">חִיסּוּד</a>.</div>","alt":[]},"11801":{"h":"חֲסַד","r":"H01336","html":"<div class=\"sense\"><b>1)</b> <i>to be put to shame</i> (<i>be whitened</i>). <span class=\"citation\">Targ. Ps. XXXIV, 6</span> Ms. (ed. <span dir=\"rtl\">עצבו</span>). <span class=\"citation\">Ib. XL, 15</span> (ed. Lag. a. oth. Ithpa.; some ed. <a href=\"#\" data-headword=\"ר\">ר</a> for <a href=\"#\" data-headword=\"ד\">ד</a>).</div><div class=\"sense\"><b>—2)</b> <i>to shame</i> &amp;c.; v. infra.</div><div class=\"sense\"><b>Pa. חַסֵּד</b> </div><div class=\"sense\"><b>Af. אַחְסִיד</b> <div class=\"sense\"><i>to jeer, blaspheme, disgrace</i> (in ed. frequ. <i>Pe</i>.). <span class=\"citation\">Targ. I Sam. XVII, 36</span>. <span class=\"citation\">Targ. Prov. XXV, 10</span> נַחְסִידָךְ Lev. (ed. <span dir=\"rtl\">נֶחְסְדָךְ</span>); a. fr. [Some ed. <a href=\"#\" data-headword=\"ר\">ר</a> for <a href=\"#\" data-headword=\"ד\">ד</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִתְחַסַּד</b> <div class=\"sense\"><i>to be reviled, put to shame</i>. <span class=\"citation\">Targ. Ps. LXXI, 24</span>; a. e.; v. supra. <span class=\"citation\">Targ. Prov. XX, 4</span> (v. LXX).</div></div>","alt":[]},"11802":{"h":"חֶסֶד","r":"H01337","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>grace, kindness, love, charity</i>. Sifra K’dosh., Par. 4, ch. X (ref. to <a href=\"#\" data-headword=\"חָסַד I\">חסד</a>, <span class=\"citation\">Lev. XX, 17</span>) <span dir=\"rtl\">שמא תאמר … ח׳ הוא</span> if you will object, why did Cain marry his sister? (Answ.) It was an act of kindness (to secure the propagation of the race); <span class=\"citation\">Y. Yeb. XI, 11ᵈ</span> top <span dir=\"rtl\">ח׳ עשיתי וכ׳</span> I (the Lord) dealt kindly with &amp;c.—<span dir=\"rtl\">חוט של ח׳</span>, v. <a href=\"#\" data-headword=\"חוּט\">חוּט</a>. <span class=\"citation\">Succ. 49ᵇ</span> <span dir=\"rtl\">אין צדקה … לפי ח׳ שבה</span> charity is rewarded only in proportion to the benevolence in it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תורה של ח׳</span> a study of love (for its own sake); a. fr.—Ruth R. Par. 3, beg., v. <a href=\"#\" data-headword=\"חִסְדָּאָה\">חִסְדָּאָה</a>.—<span class=\"citation\">Gen. R. s. 8</span> ח׳ אומר Charity said &amp;c.—Pl. <span dir=\"rtl\">חֲסָדִים</span> <i>acts of kindness</i>. Succ. l. c.; a. fr.; v. <a href=\"#\" data-headword=\"גָּמַל\">גָּמַל</a> a. <a href=\"#\" data-headword=\"גְּמִילוּת\">גְּמִילוּת</a>.</div>","alt":[]},"11803":{"h":"חֶסֶד ²","r":"H01338","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. XX, 17</span> (v. Y. Yeb. Xl, 11ᵈ top, quot. in preced). <span class=\"citation\">Targ. Gen. XXXIX, 21</span>; a. fr.—<span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top; <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot., v. <a href=\"#\" data-headword=\"גְּמַל\">גְּמַל</a>; a. e.—Pl. <span dir=\"rtl\">חִסְדַּיָּא</span>, <span dir=\"rtl\">חַסְ׳</span>; <span dir=\"rtl\">חִסְדִּין</span>, <span dir=\"rtl\">חַסְ׳</span>, <a href=\"#\" data-headword=\"חֶסֶד ²\">חִיסְ׳</a>. <span class=\"citation\">Targ. O. Gen. XXXII, 11</span>. <span class=\"citation\">Targ. Ps. CVII, 43</span>; a. e.</div>","alt":["חִסְדָּא","חִיסְ׳ I"]},"11804":{"h":"חִסְדָּא","r":"H01339","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <a href=\"#\" data-headword=\"חֶסֶד\">חֶסֶד</a>) <i>shame, revilement</i>, interch. with <a href=\"#\" data-headword=\"חִיסּוּדָא\">חִיסּוּדָא</a> q. v.</div>","alt":["חִי׳ II"]},"11805":{"h":"חִסְדָּא ²","r":"H01340","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥisda</i>, name of several Amoraim. <span class=\"citation\">Ber. 8ᵃ</span>; Y. ib. IV, 9ᵃ top.—<span class=\"citation\">Ḥull. 10ᵃ</span>.—<span class=\"citation\">Y. Ḥall. I, 57ᶜ</span> top; a. fr. V. Fr. M’bo, p. 89ᵇ, sq.</div>","alt":["חִי׳ III"]},"11806":{"h":"חִסְדָּאָה","r":"H01341","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"חִסְדָּא ²\"><span dir=\"rtl\">חִסְדָּא</span> I</a>) <i>kind, pleasing</i>.—Pl. <span dir=\"rtl\">חִסְדָּאִין</span>. <span class=\"citation\">Gitt. 7ᵃ</span> <span dir=\"rtl\">חיסדא שמך וח׳ מילך</span> thy name is Ḥisda (Love), and lovable are thy words; [Ruth R. Par. 3, beg. <span dir=\"rtl\">את חסד ומה לך חסד</span>, read: <span dir=\"rtl\">ומִילָּךְ</span>].</div>","alt":[]},"11807":{"h":"חִסְדַּאי","r":"H01342","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥisdai</i> (interch. with <a href=\"#\" data-headword=\"חִסְדָּא\">חִסְדָּא</a>). Ruth R. Par. 3, beg. <a href=\"#\" data-headword=\"חִסְדַּאי\">חסדאי</a>; (<span class=\"citation\">Gitt. 7ᵃ</span> <a href=\"#\" data-headword=\"חִיסְדָּא\">חיסדא</a>). <span class=\"citation\">Y. Snh. I, 18ᵈ</span> bot., <span class=\"citation\">Y. Erub. IV, end, 22ᵃ</span>; a. fr.—V. Fr. M’bo, p. 90ᵃ</div>","alt":["חִסְדַּיי"]},"11808":{"h":"חִסְדּוּתָא","r":"H01343","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"חֲסִידוּתָא\">חֲסִידוּתָא</a>. <span class=\"citation\">Targ. Cant. VII, 6</span> (ed. Lag. <a href=\"#\" data-headword=\"חָסֵר II\">חֲסִי׳</a>). <span class=\"citation\">Targ. Ps. LXIX, 11</span> Ms. (ed. Lag. <span dir=\"rtl\">חסיד׳</span>, oth. ed. <span dir=\"rtl\">חִסוּדְתּ׳</span>).</div>","alt":[]},"11809":{"h":"חסדיגרון","r":"H01344","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָסָא I\"><span dir=\"rtl\">חָסָא</span> I</a> a. <a href=\"#\" data-headword=\"דְּגוֹרָא\"><a href=\"#\" data-headword=\"דְּגוֹרָא\">דְּגוֹרָא</a>.</a></div>","alt":[]},"11810":{"h":"חִסּוּדָא","r":"H01345","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶסֶד ²\">חִיסּ׳</a></div>","alt":[]},"11811":{"h":"חֲסוּדָא","r":"H01346","html":"<div class=\"sense\"> f. ch. = <a href=\"#\" data-headword=\"חֲסוּדָה I\">next w.</a> Targ. II Esth. II, 7; 8.</div>","alt":[]},"11812":{"h":"חֲסוּדָה I","r":"H01347","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>amiable</i>, v. <a href=\"#\" data-headword=\"חָסַד I\"><span dir=\"rtl\">חָסַד</span> I</a>.</div>","alt":[]},"11813":{"h":"חֲסוּדָה II","r":"H01348","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (prob. fr. <a href=\"#\" data-headword=\"חָסַד II\"><span dir=\"rtl\">חָסַד</span> II</a>) <i>the vein opened for blood-letting</i>. <span class=\"citation\">Sabb. 108ᵇ</span> bot. (old ed. <span dir=\"rtl\">חסורה</span>); (cmp. <span class=\"citation\">Taan. 21ᵇ</span> bot.).</div>","alt":[]},"11814":{"h":"חִסּוּדְתָּא","r":"H01349","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִסְדּוּתָא\">חִסְדּוּתָא</a></div>","alt":[]},"11815":{"h":"חסוח","r":"H01350","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָסוּת\">חָסוּת</a></div>","alt":[]},"11816":{"h":"חסוסה","r":"H01351","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲסִיסָה\">חֲסִיסָה</a></div>","alt":[]},"11817":{"h":"חֲסוֹךְ I","r":"H01352","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַךְ\">חֲסַךְ</a>) <i>sparing, clemency</i>. <span class=\"citation\">Targ. Jer. XXX, 11</span>; <span class=\"citation\">XLVI, 28</span>. <span class=\"citation\">Ib. X, 24</span> ed. Lag. a. Rashi (ed. <a href=\"#\" data-headword=\"חֲשַׁךְ\">חֲשׂוֹךְ</a>, not <a href=\"#\" data-headword=\"שׁוּלָמִי\">הֲשׁ׳</a>).</div>","alt":[]},"11818":{"h":"חֲסוֹךְ II","r":"H01353","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֲסִיךְ\">חֲסִיךְ</a>) <i>diminution</i>; (adv.) <i>less</i>. <span class=\"citation\">Targ. Ez. XVI, 47</span>.</div>","alt":[]},"11819":{"h":"חִסּוּלָא","r":"H01354","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"חֶסֶד ²\">חִיסּ׳</a>.</div>","alt":["חִסּוּם"]},"11820":{"h":"חֲסוֹם","r":"H01355","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (חָסַם I; b. h. <i>muzzle.</i> <span class=\"citation\">Kel. XVI, 7</span> (ed. Dehr. <a href=\"#\" data-headword=\"חִיסּוּם\">חִיסּוּם</a>; Mish. ed. <a href=\"#\" data-headword=\"חֲסִים\">חסים</a>, incorr.). <span class=\"citation\">Tosef. Sabb. IV</span> (<span class=\"citation\">V), 5</span> <span dir=\"rtl\">חוסם</span>; <span class=\"citation\">Sabb. 53ᵃ</span></div>","alt":["(חוֹסָם)"]},"11821":{"h":"חֲסוֹמִית","r":"H01356","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַחֲסוֹמִית\">מַחְסוֹמִית</a></div>","alt":[]},"11822":{"h":"חֲסוּסָה","r":"H01357","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲסִיסָה\">חֲסִיסָה</a></div>","alt":[]},"11823":{"h":"חִסּוּר","r":"H01358","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶסֶד ²\">חִיסּ׳</a></div>","alt":[]},"11824":{"h":"חֲסוֹרִין","r":"H01359","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָסֵר\">חָסֵר</a> ch.</div>","alt":[]},"11825":{"h":"חָסוּת","r":"H01360","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a projecting rock, shady place</i>. <span class=\"citation\">Ex. R. s. 2</span>, beg. (some ed. <a href=\"#\" data-headword=\"חָסִית I\">חָסִית</a>). [Levy Talm. Dict. reads: <a href=\"#\" data-headword=\"חסוח\">חסוח</a>, cmp. next wds.]</div>","alt":[]},"11826":{"h":"חסחום","r":"H01361","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִסְחוּס\">next w.</a></div>","alt":[]},"11827":{"h":"חִסְחוּס","r":"H01362","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">חסחס</span>, <i>Pilp</i>. of <a href=\"#\" data-headword=\"חָסַם I\">חסם</a>, v. <a href=\"#\" data-headword=\"חוּס\">חוּס</a> a. <a href=\"#\" data-headword=\"חסחום\">preced. art.</a>) [<i>projection, protection</i>,] <i>the cartilages forming the ear, helix</i> &amp;c. <span class=\"citation\">Bekh. VI, 1</span> (<span class=\"citation\">37ᵃ</span>) <span dir=\"rtl\">נפגמה אזני מן הח׳</span> (ed. <a href=\"#\" data-headword=\"חסחום\">חסחום</a>; Mish. ed. a. Ar. <a href=\"#\" data-headword=\"הַסְחוּס\">הסּחוֹס</a>) if its ear it split (defective) from the cartilages (inward).—Pl. <span dir=\"rtl\">חִסְחוּסִים</span>, <span dir=\"rtl\">סִין …</span> <i>gristles</i>. <span class=\"citation\">Pes. VII, 11</span> (<span class=\"citation\">84ᵃ</span>) Y. ed. (Mish. a. Bab. ed. <span dir=\"rtl\">הַסְּחוּסִין</span>; Ms. M. 2 also <span dir=\"rtl\">הסחיסין</span>, v. Rabb. D. S. a. l. note 30).—Y. Snh. VIII, beg. 26ᵃ <span dir=\"rtl\">אכלו הסוקים</span>, read: <span dir=\"rtl\">אכל ח׳</span>.—V. <span dir=\"rtl\">חַסְחָסִית</span>.</div>","alt":[]},"11828":{"h":"חַסְחוּס","r":"H01363","html":"<div class=\"sense\"><span class=\"citation\">Targ. Am. III, 12</span> (h. text <span dir=\"rtl\">בדיל</span>). <span class=\"citation\">Targ. Y. Lev. VIII, 23</span> (h. text <span dir=\"rtl\">תְּנוּךְ</span>, v. <a href=\"#\" data-headword=\"גְּדֵירָא\">גְּדֵירָא</a>); a. e.</div>","alt":[]},"11829":{"h":"חסחף","r":"H01364","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Deut. XXXII, 11</span> <span dir=\"rtl\">מח׳</span>, read: <span dir=\"rtl\">מחפחף</span>, v. <a href=\"#\" data-headword=\"חָפַף I\"><span dir=\"rtl\">חֲפַף</span> I</a></div>","alt":[]},"11830":{"h":"חַסְחָסוּת","r":"H01365","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <span dir=\"rtl\">חסחוס</span>) <i>the system of cartilages of the ear, helix and anti-helix</i>. <span class=\"citation\">Bekh. 40ᵇ</span> <span dir=\"rtl\">אזניו … בח׳ אחת</span> (Rashi <span dir=\"rtl\">חסחיס</span>, read: <span dir=\"rtl\">חסחוס</span>) double ears with one system of &amp;c.—Pl. <span dir=\"rtl\">חַסְחָסִיּוֹת</span>. Ib.—V. <a href=\"#\" data-headword=\"חֲסִיסָה\">חֲסִיסָה</a>.</div>","alt":[]},"11831":{"h":"*חֲסִי","r":"H01366","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָסַד II\"><span dir=\"rtl\">חסד</span> II</a>) <i>to be scraped</i>. Denom. <a href=\"#\" data-headword=\"חַסְיָא\">חַסְיָא</a>.</div><div class=\"sense\"><b>Af. אַחְסֵי</b> <div class=\"sense\"><i>to revile, sneer at</i>. <span class=\"citation\">Targ. I Sam. I, 6</span> ומרגזה פנינה ארתח ומַחְסָא לה Ar. s. v. <span dir=\"rtl\">מחס</span> (ed. differ. vers.). V. <a href=\"#\" data-headword=\"*מְחוֹסָא\">מְחוֹסָא</a>.</div></div>","alt":["חֲסָא"]},"11832":{"h":"זָרָא","r":"G00661","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"זָר ²\">preced.</a> a. <a href=\"#\" data-headword=\"זְרָא\">next w.</a>) <i>nausea, loathing</i>. <span class=\"citation\">Num. R. s. 7</span>; <span class=\"citation\">Lev. R. s. 18</span>, v. <a href=\"#\" data-headword=\"דּוּרָא III\"><span dir=\"rtl\">דּוּרָא</span> III</a>, <a href=\"#\" data-headword=\"דְּרַרְיָא\">דְּרַרְיָא</a>, <a href=\"#\" data-headword=\"זָרָנָא\">זָרָנָא</a>.</div>","alt":[]},"11833":{"h":"זְרָא","r":"G00662","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זרי\">זרי</a> ch.</div>","alt":[]},"11834":{"h":"זָרָב","r":"G00663","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זְרַב\">next w.</a>) <i>rim, lining, trimming.</i> <span class=\"citation\">Kil. IX, 7</span> מנעול של ז׳ Ms. M. a. oth. (v. Rabb. D. S. a. l. note; ed. <span dir=\"rtl\">זרד</span>) a cloth-lined shoe; Y. ib. 32ᵈ top.</div>","alt":[]},"11835":{"h":"זְרַב","r":"G00664","html":"<div class=\"sense\"><i>to surround, line, trim</i>. <span class=\"citation\">Y. Kil. IX, 32ᵈ</span> top (ref. to <span dir=\"rtl\">מנעול של זרב</span>, v. <a href=\"#\" data-headword=\"זָרָב\">preced.</a>) <span dir=\"rtl\">אית אתרין דזַרְבִּין עימרא וכ׳</span> (not <span dir=\"rtl\">עימיה</span>) there are places where they put wool around the shoe from inside.</div><div class=\"sense\"><b>Ithpe. אִזְדְּרִיב</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"זָרָב\">preced.</a>) <i>to be made to flow over the rim, to be upset</i>. <span class=\"citation\">Yoma 78ᵃ</span> <span dir=\"rtl\">משום דמִזְדְּרִיב</span> ed. (Ar. <span dir=\"rtl\">משום דאתי לאִזְדַּרְבּוּיֵי</span>, Ms. O. <span dir=\"rtl\">דילמא אתי לא׳</span>, v. Rabb. D. S. a. l. note 70) because the silver vessel (being smooth) may be upset and liquid flow over. V. <a href=\"#\" data-headword=\"זִרְזֵיף\">זִרְזֵיף</a>.</div></div>","alt":[]},"11836":{"h":"זַרְבּוּבִית","r":"G00665","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זָרָב\">זָרָב</a>) <i>a tray</i> or <i>saucer</i> fastened to the bottom of a drinking vessel for the reception of drippings; in gen. <i>saucer, dish, disk</i>. <span class=\"citation\">Pesik. R. s. 35</span> <span dir=\"rtl\">שנדמה כז׳ קטנה וכ׳</span> (ed. Fr. <span dir=\"rtl\">זרבוכ׳</span>, corr. acc.) whose face appeared (over the camp) like a small disk of fire; Yalk. Dan. 1062 <span dir=\"rtl\">כביבית</span> (corr. acc., or <span dir=\"rtl\">כגִיגִית</span>).—Pl. <a href=\"#\" data-headword=\"זַרְבּוּבִית\">זַרְבּוּבִיֹּות</a>. <span class=\"citation\">Lev. R. s. 5</span>; <span class=\"citation\">Num. R. s. 10</span> (expl. <span dir=\"rtl\">מזרקי</span>, <span class=\"citation\">Am. VI, 6</span>) <span dir=\"rtl\">כוסות שיש להם ז׳</span> cups with saucers; Yalk. Am. 545 <span dir=\"rtl\">שאין בהם זכוכית</span> (corr. acc.).</div>","alt":[]},"11837":{"h":"זרבונין","r":"G00666","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"יַרְבּוּזָא\">יַרְבּוּזָה</a></div>","alt":[]},"11838":{"h":"*זַרְגֹּון","r":"G00667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <span dir=\"rtl\">זרג</span> a. denom. P. Sm. 1154) <i>zargon</i>, name of a plant, prob. a species of <i>beet</i>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> bot. <span dir=\"rtl\">ז׳ ולפת</span> <i>z</i>. crossed with carrot. [It is evident that our w. cannot mean a vine-shoot, as Fl. to Levy Talm. Dict. I, 564, a. Löw Pfl. p. 87 suggest.—R. S. to <span class=\"citation\">Kil. I, 4</span> reads <span dir=\"rtl\">וגדין</span> or <span dir=\"rtl\">זגדין</span>.]</div>","alt":[]},"11839":{"h":"*זַרְגּוּנָה","r":"G00668","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>zargunah</i>, name of a <i>tree</i> or <i>shrub</i> with copious twigs, but bare beneath. <span class=\"citation\">Y. Succ. III, beg. 53ᶜ</span></div>","alt":[]},"11840":{"h":"זֶרֶד","r":"G00669","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זְרַז I\">זרז</a>) </div><div class=\"sense\"><b>1)</b> <i>strength, alertness, valor</i>. <span class=\"citation\">Yoma 47ᵃ</span> (a metaphor in imitation of <span class=\"citation\">Prov. XXXI, 29</span>) <span dir=\"rtl\">כל הנשים זֶ׳ זָרָדוּ וזֶ׳ אמי עלת׳ לגג</span> Ar. (read <span dir=\"rtl\">עלה</span>; ed. <span dir=\"rtl\">הנשים זרדו וז׳ אימא וכ׳ …</span>; Ms. M. <span dir=\"rtl\">זֶרֶז זָרָזוּ אימא</span>, insert <span dir=\"rtl\">וזֶ׳</span>; Ms. M. 2 <span dir=\"rtl\">זריד זרדו וזֶ׳</span>; v. Rabb. D. S. a. l. note) all women have done valiantly, but the valor of my mother excelled them all (a metaphor of careful maternity).</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"זָרַד\">next w.</a>) pl. <span dir=\"rtl\">זְרָדִים</span>, <span dir=\"rtl\">זְרָרִין</span> <i>shoots, greens</i>. <span class=\"citation\">Tosef. Sabb. IX</span> (<span class=\"citation\">X), 16</span>; <span class=\"citation\">Sabb. 103ᵃ</span> <span dir=\"rtl\">המְזָרֵד ז׳ וכ׳</span> he who cuts greens, if for human food &amp;c. <span class=\"citation\">Ib. XVIII, 2</span> (<span class=\"citation\">126ᵇ</span>) <span dir=\"rtl\">חבילי ז׳</span> bundles of greens (young reeds &amp;c., available for fodder); ib. 128ᵃ; Tosef. ib. XIV (XV), 10 <a href=\"#\" data-headword=\"זרדן\">זרדן</a> ed. Zuck. (read <span dir=\"rtl\">זרדין</span>, Var. <span dir=\"rtl\">דים …</span>).—Esp. <span dir=\"rtl\">לולבי ז׳</span> <i>the young sprouts of the service-tree</i>, the interior of which is eaten as a relish. <span class=\"citation\">Shebi. VII, 5</span>. <span class=\"citation\">Tosef. Sabb. VIII</span> (<span class=\"citation\">IX), 9</span> <span dir=\"rtl\">לולבין וז׳</span> (corr. acc.); <span class=\"citation\">Tosef. Maas. Sh. I, 13</span>; <span class=\"citation\">Tosef. Ukts. III, 9</span>; <span class=\"citation\">Ukts. III, 4</span>.</div><div class=\"sense\"><b>—3)</b>  pr. n. (b. h.) <i>Zered</i>, name of a brook, <span dir=\"rtl\">נחלא דז׳</span>. <span class=\"citation\">Targ. O. Num. XXI, 12</span>; a. e.—<span class=\"citation\">Tosef. Shebi. IV, 11</span>; Y. ib. VI, 36ᶜ; <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">דורד</span>; <span class=\"citation\">Yalk. Deut. 874</span> <span dir=\"rtl\">נחלת דור</span> (corr. acc.); v. Hildesh. Beitr. p. 66.</div>","alt":[]},"11841":{"h":"זָרַד","r":"G00670","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"זֶרֶד\">preced.</a>) <span dir=\"rtl\">זָ׳ זֶרֶד</span> (= <span dir=\"rtl\">עשה חיל</span>) <i>to do valiantly</i>. <span class=\"citation\">Yoma 47ᵃ</span>, v. <a href=\"#\" data-headword=\"זֶרֶד\">preced.</a></div><div class=\"sense\"><b>Pi. זֵירֵד</b> <div class=\"sense\"> [<i>to strengthen, accelerate growth;</i> cmp. <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a> <i>Af.</i>,] <i>to trim, nip shoots off</i>. <span class=\"citation\">Sabb. XII, 2</span> <span dir=\"rtl\">המקרסם והמְזָרֵד</span> he who cuts off dry twigs, or young shoots. <span class=\"citation\">Ib. 103ᵃ</span>, v. <a href=\"#\" data-headword=\"זֶרֶד\">preced.</a> <span class=\"citation\">Ab. Zar. III, 10</span> (<span class=\"citation\">49ᵇ</span>). <span class=\"citation\">Tosef. Sabb. IX</span> (<span class=\"citation\">X), 16</span> <a href=\"#\" data-headword=\"וזרד\">וזֵרֵד</a> ed. Zuck. (Var. <span dir=\"rtl\">וזירד</span>).</div></div>","alt":[]},"11842":{"h":"זַרְדָּא","r":"G00671","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זרד</span>) <i>coat of mail, armour</i> (v. P. Sm. 1154, sq. s. vv. <span dir=\"rtl\">זרגא</span>, <span dir=\"rtl\">זרגנא</span>, <a href=\"#\" data-headword=\"זַרְדָּא\">זרדא</a>). <span class=\"citation\">Sabb. 62ᵃ</span>, expl. <a href=\"#\" data-headword=\"שִׁרְיוֹן\">שריון</a>.</div>","alt":[]},"11843":{"h":"זרדן","r":"G00672","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 10</span>, v. <a href=\"#\" data-headword=\"זֶרֶד\">זֶרֶד</a> pl.</div>","alt":[]},"11844":{"h":"זַרְדְּתָא","r":"G00673","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זרד</span>) <i>bushes of sorb</i>, or <i>service-tree</i>, growing in unhealthy marshes (v. Löw. Pfl. p. 289) <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">דבי ז׳ שידי</span> (v. Rabb. D. S. a. l. note 400) the spirits of the sorb-bushes are named <i>shiddé</i> (demons). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ז׳ סמיכא למתא וכ׳</span> a sorb-bush near a town has no less than sixty <i>shiddé;</i> [Ms. M. <span dir=\"rtl\">זַרְזְתָא</span>, <a href=\"#\" data-headword=\"זִירְקְתָא\">זִירְזְתָא</a>, <a href=\"#\" data-headword=\"זַרְתָּא\">זַרְתָּא</a>; v. Rabb. D. S. a. l. notes).—<span class=\"citation\">Kidd. 73ᵇ</span> <span dir=\"rtl\">ז׳ … יש בו וכ׳</span> a child exposed in a sorb-bush near a town (where it is likely to die) is considered a foundling <a href=\"#\" data-headword=\"אֲסוּפִי\">(אֲסוּפִי</a>). <span class=\"citation\">Keth. 79ᵃ</span> <span dir=\"rtl\">אבא ז׳ וכ׳</span> a forest (of timber), a sorb plantation and a fish-pond.</div>","alt":["(זַרְתָּא)"]},"11845":{"h":"זָרָה","r":"G00674","html":"<div class=\"sense\">, fem. of <a href=\"#\" data-headword=\"זָר\">זָר</a> q. v.</div>","alt":[]},"11846":{"h":"זָרָה  I, II","r":"G00675","html":"<div class=\"sense\">, v. <span dir=\"rtl\">זרי I</span>, II.</div>","alt":[]},"11847":{"h":"*זַרְוַאי","r":"G00676","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Melaḥ d’Zarvai</i>, a border place on the east side of the Jordan. <span class=\"citation\">Tosef. Shebi. IV, 11</span> מלח דז׳ Var. (ed. Zuck. <span dir=\"rtl\">מלי חזרואי</span>); <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span> <span dir=\"rtl\">מלח דזרכאיי</span> (read <span dir=\"rtl\">זַרְבַּ׳</span> = <span dir=\"rtl\">זַרְוַ׳</span>, v. Hildesh. Beitr. p. 61, sq.); Sifré Deut. s. 51 <span dir=\"rtl\">עליה זירזא</span>; Yalk. ib. 874 <span dir=\"rtl\">מיליה וירואי</span>. [Hildesh. l. c. a. Neub. Géogr. p. 20 emend <a href=\"#\" data-headword=\"מוּלְיָא\">מוּלְיָא</a> or <span dir=\"rtl\">(<span dir=\"rtl\">מליתא</span>) <a href=\"#\" data-headword=\"מִלְּתָא\">מִלְתָא</a></span> for <a href=\"#\" data-headword=\"מְלַח I\">מלח</a>.]</div>","alt":["מֶלַח דְּזַ׳"]},"11848":{"h":"זֵרוּז","r":"G00677","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זֵירוּז\">זֵירוּז</a></div>","alt":["זֵרוּזִין"]},"11849":{"h":"זְרוֹעַ","r":"G00678","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>arm;</i> (with animals) <i>fore-leg, shoulder; strength, force</i>. <span class=\"citation\">Ber. 17ᵇ</span> <span dir=\"rtl\">ניזונין בז׳</span> receive their sustenance from the Lord by dint of their strength (virtue), opp. <span dir=\"rtl\">בצדקה</span> by divine grace. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> top <span dir=\"rtl\">זְרוֹעָן של כל ישראל</span> the arm (defence, protection) of all Israel. <span class=\"citation\">Sabb. 56ᵃ</span> <span dir=\"rtl\">נטלו בז׳</span> they took by force. <span class=\"citation\">Lev. R. s. 2</span> <span dir=\"rtl\">כבא על חבירו בז׳</span> like one coming against his neighbor with force (confident of victory).—<span class=\"citation\">Ḥull. X, 1</span> <span dir=\"rtl\">הז׳</span> the law concerning the shoulder as the priest’s share (<span class=\"citation\">Deut. XVIII, 3</span>). Ib. 98ᵃ <span dir=\"rtl\">ז׳ בשלה</span>, v. <a href=\"#\" data-headword=\"בָּשֵׁל\">בָּשֵׁל</a>; a. fr.—Pl. <span dir=\"rtl\">זְרוֹעוֹת</span>, constr. <span dir=\"rtl\">זְרוֹעֵי</span>. <span class=\"citation\">Sot. 49ᵇ</span>; <span class=\"citation\">Tosef. ib. XIV, 3</span> <span dir=\"rtl\">ז׳ תורה</span> the supports of the Law.—<span dir=\"rtl\">בעלי ז׳</span> violent men. <span class=\"citation\">B. Mets. 118ᵃ</span>; a. e.</div>","alt":[]},"11850":{"h":"זֵרוּעַ","r":"G00679","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <a href=\"#\" data-headword=\"זֵרוּעַ\">זֵרוּעַ</a>; <a href=\"#\" data-headword=\"זְרַע I\">זרע</a>) <i>sowing; seed</i>. <span class=\"citation\">Targ. O. Lev. XI, 37</span>.—Pl. <span dir=\"rtl\">זֵרוּעִין</span>, <a href=\"#\" data-headword=\"זִיעֲתָא\">זֵי׳</a>. <span class=\"citation\">Targ. Is. LXI, 11</span> <span dir=\"rtl\">זֵרוּעָהָא</span> (ed. Lag. <span dir=\"rtl\">זֵירוּעָהּ</span> sing.). [<span class=\"citation\">Y. Sabb. IX, 12ᵃ</span> top; <span class=\"citation\">Y. Kil. III, beg. 28ᶜ</span> (ref. to Is. l. c.) <span dir=\"rtl\">זֵירוּעֶיהָ מליא</span> <i>zerûëha</i> is spelt <i>plene</i> (with <a href=\"#\" data-headword=\"ו\">ו</a>); v. <a href=\"#\" data-headword=\"יאנא\">יאנא</a>.]</div>","alt":["זֵיר׳"]},"11851":{"h":"זְרוֹק","r":"G00680","html":"<div class=\"sense\"> pr. n., <span dir=\"rtl\">נהר ז׳</span>, v. <a href=\"#\" data-headword=\"יָזֵק\">יָזֵק</a></div>","alt":[]},"11852":{"h":"זְרוּקִינְיָא","r":"G00681","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Z’rukinya</i>, in Babylonia. <span class=\"citation\">Ḥull. 111ᵃ</span></div>","alt":[]},"11853":{"h":"זָרוֹקְפָא","r":"G00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*זְלוּקְפָא\">זְלוּקְפָא</a></div>","alt":[]},"11854":{"h":"זרורזי","r":"G00683","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to II, 9</span>, v. <a href=\"#\" data-headword=\"זְרַז I\"><span dir=\"rtl\">זְרַז</span> I</a></div>","alt":[]},"11855":{"h":"זָרוּת","r":"G00684","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"זָר\">זָר</a>) <i>the legal status of the non-priest, the laws concerning non-priests</i>. <span class=\"citation\">Y. Ter. V, 43ᶜ</span> <span dir=\"rtl\">איסור ז׳</span> the prohibition as far as it concerns the T’rumah to be eaten by non-priests. <span class=\"citation\">Y. Bicc. II, 65ᵃ</span> <span dir=\"rtl\">היתר ז׳</span> inasmuch as they are permitted to non-priests. <span class=\"citation\">Y. Orl. II, end, 62ᶜ</span> <span dir=\"rtl\">משום ז׳</span> for violating the law forbidding non-priests &amp;c.—<span class=\"citation\">Yeb. 68ᵇ</span>, a. e. (ref. to <span dir=\"rtl\">וכל זר</span>, <span class=\"citation\">Lev. XXII, 10</span>) <span dir=\"rtl\">ז׳ אמרתי לך וכ׳</span> the Law treats of non-priests, but not of the mourners; a. e.</div>","alt":[]},"11856":{"h":"זָרַז","r":"G00685","html":"<div class=\"sense\"> (reduplic. of <span dir=\"rtl\">זר</span>, v. <a href=\"#\" data-headword=\"זָרַר\">זרר</a>; cmp. <span dir=\"rtl\">אזר</span>) <i>to be strong, vigorous, quick</i>, v. <a href=\"#\" data-headword=\"זָרַד\">זָרַד</a>.—Part. pass. <a href=\"#\" data-headword=\"זֵרוּז\">זָרוּז</a>, v. <a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>.</div><div class=\"sense\"><b>Pi. זֵירֵז</b> <div class=\"sense\"><b>1)</b> <i>to strengthen, to make active and ready, to instigate</i>. <span class=\"citation\">Pes. 89ᵃ</span> <span dir=\"rtl\">כדי לזַרְזָן … קאמר</span> he said so in order to awaken their emulation in religious acts. <span class=\"citation\">Nidd. 31ᵃ</span>; <span class=\"citation\">Yoma 47ᵃ</span> <span dir=\"rtl\">זֵירַזְתָּנִי</span>, v. <a href=\"#\" data-headword=\"זרי\"><span dir=\"rtl\">זָרָה</span> I</a>.—<i>Part. pass</i>. <span dir=\"rtl\">מְזוֹרָז</span> a) <i>strong, vigorous</i>. Nidd. l. c.; <span class=\"citation\">Snh. 70ᵇ</span>; a. e., v. <a href=\"#\" data-headword=\"לָבַן II\"><span dir=\"rtl\">לָבַן</span> II</a>.—b) <i>active, zealous to do good, valiant</i>. <span class=\"citation\">Macc. 23ᵃ</span> אין מְזָרְזִין אלא למְזוֹרָזִין Ar. (ed. <span dir=\"rtl\">מזורז</span>; some ed. <span dir=\"rtl\">מזרז</span>, corr. acc.) only the strong-minded it is worth encouraging; <span class=\"citation\">Yalk. Deut. 937</span>; <span class=\"citation\">Sifré Num. 1</span> <span dir=\"rtl\">למְזוֹרָזִים</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to admonish, be severe</i>. Tanḥ. Korah 6 <span dir=\"rtl\">התחיל מְזָרֵז בהן</span> (<span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">לדבר להם</span>) he began to speak to them earnestly.</div></div><div class=\"sense\"><b>Hithpa. הִזְדָּרֵז</b> </div><div class=\"sense\"><b>Nithpa. נִזְדָּרֵז</b> <div class=\"sense\"><b>1)</b> <i>to be alert, zealous, conscientious</i>. <span class=\"citation\">Pesik. R. s. 6</span> (ref. to <a href=\"#\" data-headword=\"מָהִר\">מהיר</a>, <span class=\"citation\">Prov. XXII, 29</span>) <span dir=\"rtl\">נִזְדָּרַזְתָּ במלאכתך</span> thou hast been zealous (conscientious) in thy own occupation. Tanḥ. P’kudé 11; a. fr.—V. <a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>.—3) <i>to be armed</i>. <span class=\"citation\">Yalk. Num. 785</span>, v. <a href=\"#\" data-headword=\"זְרַז I\">next w.</a></div></div>","alt":[]},"11857":{"h":"זְרַז I","r":"G00686","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"זָרֵיז\">זָרֵיז</a> same; </div><div class=\"sense\"><b>1)</b> <i>to be quick, to hurry</i>. <span class=\"citation\">Targ. Y. II, Gen. XXIV, 20</span> (h. text <span dir=\"rtl\">מהר</span>).—<span class=\"citation\">Targ. Ps. LXX, 2</span> <a href=\"#\" data-headword=\"זָרֵיז\">זְרֵיז</a> ed. (Ms. <span dir=\"rtl\">זָ׳</span>; h. text <a href=\"#\" data-headword=\"חוּשׁ\">חוש</a>); a. e.—<i>Part. Pe</i>. <a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>, <i>Pa.</i> <span dir=\"rtl\">מְזָרֵז</span>; pl. <span dir=\"rtl\">זְרִיזִין</span>, <span dir=\"rtl\">זַרְזִין</span>, <span dir=\"rtl\">מְזָרְזִין</span>. <span class=\"citation\">Targ. Y. I Num. IX, 8</span>, <span class=\"citation\">Targ. Y. II, Num. IX, 8</span>, opp. <a href=\"#\" data-headword=\"*מתון\">מתון</a>; v. also <a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>.</div><div class=\"sense\"><b>—2)</b> <i>to quicken, strengthen</i>. <span class=\"citation\">Yeb. 102ᵇ</span> (expl. <span dir=\"rtl\">יחליץ</span>, <span class=\"citation\">Is. LVIII, 11</span>) <span dir=\"rtl\">זָרוּזֵי גרמי</span> it means quickening the bones. Cant. R. to II, 10 <span dir=\"rtl\">זָרוֹזִי גרמיך</span> (not <a href=\"#\" data-headword=\"זרורזי\">זרורזי</a>) make thyself ready; <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">זָרְזִי</span>.</div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"זֵיר\">זֵיר</a>, <a href=\"#\" data-headword=\"אָזַר\">אָזַר</a>) <i>to tie around, gird, arm; to harness, saddle</i>. <span class=\"citation\">Targ. O. Gen. XIV, 14</span>. <span class=\"citation\">Targ. Job XXXVIII, 3</span> זָרֵיז Ms. (ed. <a href=\"#\" data-headword=\"זָרֵיז\">זְרֵיז</a>, <a href=\"#\" data-headword=\"זְרַז I\">זְרַז</a>). <span class=\"citation\">Targ. O. Ex. XXIX, 9</span>; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְזָרַז</span>, pl. <span dir=\"rtl\">מְזַרְזִין</span>, <span dir=\"rtl\">מְזַרְזַיָּא</span> <i>armed</i>. <span class=\"citation\">Ib. XIII, 18</span>. <span class=\"citation\">Targ. Is. XV, 4</span>; a. fr.—Yeb. l. c. (ref. to <span dir=\"rtl\">וחלצה</span>, <span class=\"citation\">Deut. XXV, 9</span>) <span dir=\"rtl\">ואימא זָרוּזֵי הוא</span> may I not say, it means <i>tying on?</i></div><div class=\"sense\"><b>Ithpa. אִזְדָּרֵז</b> </div><div class=\"sense\"><b>Ithpe. אִזְדְּרִיז</b> <div class=\"sense\"><b>1)</b> <i>to strengthen one’s self</i> (so as not to give way to emotion). (so as not to give way to emotion). <span class=\"citation\">Targ. Y. Gen. XLIII, 31</span>. <span class=\"citation\">Targ. Esth. V, 10</span>.</div><div class=\"sense\"><b>—2)</b> <i>to gird one’s self, be armed</i>. <span class=\"citation\">Targ. Num. XXXII, 17</span>; <span class=\"citation\">20</span>; a. e.—<span class=\"citation\">Targ. Prov. XXX, 31</span>, v. <a href=\"#\" data-headword=\"זַרְכֵּל\">זַרְכֵּל</a>.—Sifré Num. s. 157 אין החלצו אלא אִיזְדָּרְזוּ <i>heḥal’tsu</i> (<span class=\"citation\">Num. XXXI, 3</span>) means, be armed; Yalk. ib. 785 <span dir=\"rtl\">הִזְדָּרְזוּ</span> (Hebr.).</div></div>","alt":[]},"11858":{"h":"זֶרֶז","r":"G00687","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְרַז I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>strength, valor</i>, v. <a href=\"#\" data-headword=\"זֶרֶד\">זֶרֶד</a>.</div><div class=\"sense\"><b>—2)</b> <i>belt, belt-saddle.</i> <span class=\"citation\">Kel. XXIII, 2</span> זֶ׳ האשקלוני Ar. a. ed. Dehr. (ed. <span dir=\"rtl\">זריז</span>) the Ashkelonian saddle; Sifra M’tsora, Zabim, Par. 2, ch. III; <span class=\"citation\">Yalk. Lev. 568</span> <span dir=\"rtl\">זהו האשתונית</span> (corr. acc.).—Pl. <span dir=\"rtl\">זְרָזִין</span>, constr. <span dir=\"rtl\">(<span dir=\"rtl\">זְרִיזֵי</span>) <span dir=\"rtl\">זַרְזֵי</span></span>. <span class=\"citation\">Erub. 18ᵇ</span> ז׳ תאנים <i>garments</i> of fig-leaves (v. <a href=\"#\" data-headword=\"זְרַז II\">next w.</a>).</div>","alt":["(זָרִיז)"]},"11859":{"h":"זְרַז II","r":"G00688","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. XVIII, 4</span>; a. fr.—<span class=\"citation\">Targ. Is. V, 27</span> <a href=\"#\" data-headword=\"זָרִיז\">זְרִיז</a> (constr., ed. Lag. <a href=\"#\" data-headword=\"זְרַז I\">זרז</a>).—Pl. <span dir=\"rtl\">זְרָזִין</span>, <span dir=\"rtl\">זַרְזִין</span> <i>garments, equipment</i>. <span class=\"citation\">Targ. O. Gen. III, 7</span> (h. text <span dir=\"rtl\">חֲג̇רֹת</span>). <span class=\"citation\">Targ. Jud. XIV, 19</span> <span dir=\"rtl\">זרזיהון</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">זְרָזָהוֹן</span>, h. text <span dir=\"rtl\">חליצות׳</span>).—<span class=\"citation\">Targ. Ps. LXXXIII, 15</span> <span dir=\"rtl\">זַרְזֵי טוריא</span> the <i>crests</i> of mountains (cmp. <a href=\"#\" data-headword=\"זִיר\">זִיר</a>; Ms. <a href=\"#\" data-headword=\"דָּרֵי\">דָּרֵי</a>, v. <a href=\"#\" data-headword=\"דָּר ³\"><span dir=\"rtl\">דָּרָא</span> I</a>).</div>","alt":["זַרְזָא","זָרִיז"]},"11860":{"h":"זִרְזֵיף","r":"G00689","html":"<div class=\"sense\"> (redupl. of <a href=\"#\" data-headword=\"זרף\">זרף</a>, v. <span dir=\"rtl\">זרב</span>) <i>to flow over</i>. <span class=\"citation\">Cant. R. to I, 3</span> <span dir=\"rtl\">מה השמן … מְזַֹרְזֵף בשאר … מְזַרְזְפִים וכ׳</span> (not <span dir=\"rtl\">כשאר</span>) as oil on top of another liquid, when the cup is full, does not flow over with other liquids, so will the words of the Law not flow over (the lips) in connection with words of frivolity.</div>","alt":["זִרְזֵף"]},"11861":{"h":"זַרְזִיפָא","r":"G00690","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"זִרְזֵיף\">preced.</a>) <i>squirtings from a vessel poured out from a height</i>. <span class=\"citation\">Yoma 87ᵃ</span> <span dir=\"rtl\">ז׳ דמיא</span> (Var. <span dir=\"rtl\">זַרְזִיפְתָּא</span> f., pl. <span dir=\"rtl\">זַרְזִיפָתָא</span>, v. Rabb. D. S. a. l. note 6). [Cmp. b. h. <a href=\"#\" data-headword=\"זִרְזֵיף\">זַרְזִיף</a>].</div>","alt":["זַרִזִיפֵי"]},"11862":{"h":"זַרְזִיר I","r":"G00691","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זִירָה\">זִירָה</a>) <i>wrestler, antagonist, gladiator</i>. <span class=\"citation\">Y. R. Hash. I, 57ᵃ</span> bot. <span dir=\"rtl\">זה … לנצח זַרְזִירוֹ וכ׳</span> each is anxious to defeat his antagonist.—Pl. <a href=\"#\" data-headword=\"זַרְזָר\">זַרְזִירִין</a>, <a href=\"#\" data-headword=\"זַרְזָר\">זַרְזָרִין</a>. <span class=\"citation\">Lam. R. to V, 1</span> <span dir=\"rtl\">אדם … שני זרזרין … כובש וכ׳</span> (not <a href=\"#\" data-headword=\"כִּבּוּשׁ\">כבוש</a>) if a man trains two gladiators in his house, he will restrain the stronger one &amp;c. [Bib. Hebr. <a href=\"#\" data-headword=\"זַרְזִיר I\">זַרְזִיר</a> <i>quick</i>, or <i>armed</i>, v. <a href=\"#\" data-headword=\"זְרַז I\">זרז</a>.]</div>","alt":["זַרְזָר"]},"11863":{"h":"זַרְזִיר II","r":"G00692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">זרזירא</span> P. Sm. 1156, Ar. <i>zurzur</i>; prob. fr. <a href=\"#\" data-headword=\"זוּר\">זור</a> <i>to circle</i>) <i>starling</i>, also (collect.) <i>flock of starlings</i>. <span class=\"citation\">Ḥull. 62ᵃ</span> <span dir=\"rtl\">להביא את הז׳</span> (Sifra Sh’mini, Par. 3, ch. V <span dir=\"rtl\">הזַרְזִירִים</span>, Ar. <span dir=\"rtl\">רין …</span>) to include the starling (in the genus raven). Ḥull. l. c.; <span class=\"citation\">B. Kam. 92ᵇ</span> (prov.) <span dir=\"rtl\">לא לחנם הלך ז׳ וכ׳</span> not without cause does the starling follow the raven &amp;c.; <span class=\"citation\">Gen. R. s. 65</span>, beg. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עלה ז׳ אחד וכ׳</span> a flock of starlings came to Palestine.—Pl. <span dir=\"rtl\">זַרְזִירִים</span>, <a href=\"#\" data-headword=\"זַרְזָר\">זַרְזִירִין</a>. <span class=\"citation\">Gen. R. s. 75</span> <span dir=\"rtl\">אין שני ז׳ וכ׳</span> two flocks of starlings cannot sleep on one board (two nations cannot rule at the same time). <span class=\"citation\">Tosef. Ḥull. III (IV), 23</span>.</div>","alt":[]},"11864":{"h":"זִרְזֵף","r":"G00693","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִרְזֵיף\">זִרְזֵיף</a></div>","alt":[]},"11865":{"h":"זַרְזָר","r":"G00694","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זַרְזִיר I\"><span dir=\"rtl\">זַרְזִיר</span> I</a></div>","alt":["זַרְזָרִין"]},"11866":{"h":"זָרַח","r":"G00695","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"זרי\">next w.</a>) [<i>to spread</i>,] <i>to shine, sparkle, rise</i> (cmp. <a href=\"#\" data-headword=\"הָנֵץ\">הָנֵץ</a>). <span class=\"citation\">Ḥull. 91ᵇ</span> <span dir=\"rtl\">וכי שמש … זָרְחָה</span> did the sun rise for him (Jacob) alone? <span class=\"citation\">Y. Snh. VIII, end, 26ᶜ</span> <span dir=\"rtl\">החמה זוֹרַחַת וכי …</span> does the sun shine on him (the thief) alone? a. fr.—Tanḥ. Tsav 13, a. fr. <span dir=\"rtl\">צרעת זרחה וכ׳</span></div><div class=\"sense\"><b>Hif. הִזְרִיחַ</b> <div class=\"sense\"><b>1)</b> <i>to make shine</i>. <span class=\"citation\">Gen. R. s. 22</span> <span dir=\"rtl\">ה׳ לו הצרעת</span> the Lord made leprosy glisten on his face. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ה׳ … חמה</span> he caused the globe of the sun to shine bright for him (a sign of pardon). <span class=\"citation\">Lev. R. s. 28</span>, beg. <span dir=\"rtl\">דיין שהקב&quot;ה מַזְרִיחַ וכ׳</span> it is reward enough for them that the Lord lets the sun rise &amp;c. <span class=\"citation\">Macc. 10ᵃ</span> (ref. to <span dir=\"rtl\">מזרחה</span>, <span class=\"citation\">Deut. IV, 41</span>) <span dir=\"rtl\">הַזְרֵחַ שמש וכ׳</span> let the sun shine on unwilling manslayers (give them safety). Ib. <span dir=\"rtl\">הִזְרַחְתָּ וכ׳</span></div><div class=\"sense\"><b>—2)</b>  (neut. verb) <i>to glisten.</i> <span class=\"citation\">Shebi. IV, 7</span> <span dir=\"rtl\">משיַזְרִיחוּ</span> (Ms. M. <span dir=\"rtl\">משהִזְ׳</span>) when the young figs begin to glisten.</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"מִזְרָח\">מִזְרָח</a>) <i>to go east</i>. <span class=\"citation\">Gen. R. s. 61</span>, end (ref. to <span class=\"citation\">Gen. XXV, 6</span>) <span dir=\"rtl\">כל מה … להַזְרִיחַ תַּזְרִיחוּ</span> go as far east as you can.</div></div>","alt":[]},"11867":{"h":"זרי","r":"G00696","html":"<div class=\"sense\"> (b. h.) <i>to scatter, to winnow</i>. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">הזוֹרֶה</span> he who winnows (on the Sabbath).—Ib. 73ᵇ <span dir=\"rtl\">היינו זורה וכ׳</span> is not winnowing the same process as sifting &amp;c.?—<span class=\"citation\">Ab. Zar. III, 3</span> <span dir=\"rtl\">שוחק וזורה לרוח</span> he must grind it and cast it to the wind; a. fr.—Euphem. <i>to emit semen</i>. <span class=\"citation\">Gen. R. s. 85</span>, v. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a>.</div><div class=\"sense\"><b>Pi. זֵירָה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"זָרַח\">same</a>, also <i>to sift, select</i>. <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">שיחקו וזי׳ וכ׳</span> he ground and scattered it &amp;c.—<span class=\"citation\">Nidd. 31ᵃ</span>; <span class=\"citation\">Yoma 47ᵃ</span> (ref. to <span dir=\"rtl\">ותזרני</span> <span class=\"citation\">II Sam. XXII, 40</span>, a. <span dir=\"rtl\">ותאזרני</span> <span class=\"citation\">Ps. XVIII, 40</span>) <span dir=\"rtl\">זֵירִיתָנִי וזרזתני</span> thou didst sift me (select the best semen for embryonic formation, cmp. <a href=\"#\" data-headword=\"זָרַד\">זָרַד</a>) and make me healthy.</div></div>","alt":["זָרָה I"]},"11868":{"h":"זרי ²","r":"G00697","html":"<div class=\"sense\">, <i>to scatter</i>. <span class=\"citation\">Targ. O. Ex. XXXII, 20</span> (Var. <a href=\"#\" data-headword=\"דרא\">דרא</a>).</div>","alt":["זְרָא"]},"11869":{"h":"זרי ³","r":"G00698","html":"<div class=\"sense\"> (sec. r. of <a href=\"#\" data-headword=\"זוּר\">זוּר</a>) <i>to deviate, to do wrong</i>. <span class=\"citation\">Midr. Till. to Ps. LVIII, 4</span> (ref. to <span dir=\"rtl\">זֹרוּ</span> ib.) <span dir=\"rtl\">מרחם זְרִיתֶם</span> while in the womb you were wrong-doers; <span class=\"citation\">Yalk. Ps. 776</span>. <span class=\"citation\">Midr. Till. to Ps. XC, 5</span>, v. <a href=\"#\" data-headword=\"זוּר I\"><span dir=\"rtl\">זוּר</span> I</a>.</div>","alt":["זָרָה II"]},"11870":{"h":"זְרִיבָה","r":"G00699","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרָב\">זָרַב</a>) <i>flowing over, boiling over, scalding</i>. <span class=\"citation\">Lev. R. s. 7</span>, end (ref. to <span class=\"citation\">Job VI, 17</span>, applied to the deluge) <span dir=\"rtl\">זְרִיבָתָם לחלוטין וכ׳</span> their scalding (destruction by hot water) was final (there is no resurrection for them); <span class=\"citation\">Gen. R. s. 28</span>, end; Y. Snh. X, 29ᵇ bot. (cmp. <a href=\"#\" data-headword=\"חֲלוּטִין\">חֲלוּטִין</a> a. <a href=\"#\" data-headword=\"צְמִיתוּת\">צְמִיתוּת</a>).</div>","alt":[]},"11871":{"h":"זָרִיד","r":"G00700","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זרד</span>) </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"זֶרֶד\">זֶרֶד</a>.</div><div class=\"sense\"><b>—2)</b>  (from its strengthening effect) <i>a broth</i> or <i>porridge of broken grain</i>. <span class=\"citation\">Ber. 37ᵃ</span> ז׳ וערסן וכ׳ Ms. M. (ed. <a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>); expl. (in Ms. M. a. Ar., v. Rabb. D. S. a. l. note 30) <span dir=\"rtl\">ז׳ ארבע ארבע</span> the dish is called <i>zarid</i>, when the grain is broken into four pieces (v. Sm. Ant. s. v. Alica; v. <span class=\"citation\">M. Kat. 13ᵇ</span>). <span class=\"citation\">Y. Ned. VI, 39ᶜ</span> bot. [<span class=\"citation\">Bekh. 44ᵃ</span>, v. <a href=\"#\" data-headword=\"זִיוֵּר\">זִיוֵּר</a>.]</div>","alt":[]},"11872":{"h":"זְרִיָּה","r":"G00701","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (זָרָה II) <i>deviation</i>, (cmp. <a href=\"#\" data-headword=\"זָנָה\">זָנָה</a>) <i>lewdness</i>. <span class=\"citation\">Midr. Till. to Ps. XC, 5</span> (ref. to <span dir=\"rtl\">זרמתם</span> ib., v. <span dir=\"rtl\">זוּד I</span>) <span dir=\"rtl\">זְרִיָּתָם לשעה היתה</span> their debauchery was only for a while; <span class=\"citation\">Yalk. Ps. 841</span> <span dir=\"rtl\">זְרִיָּיתָם</span>.</div>","alt":["זְרִיָּיה"]},"11873":{"h":"זִרְיוֹן","r":"G00702","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זוּרְיוֹן\">זוּרְיוֹן</a></div>","alt":[]},"11874":{"h":"זָרִיז","r":"G00703","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרַז\">זָרַז</a>) </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"זֶרֶז\">זֶרֶז</a>.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"זָרִיד\">זָרִיד</a>.</div><div class=\"sense\"><b>—3)</b>  (adj.) <i>strong, quick; scrupulous; industrious</i>. <span class=\"citation\">Snh. 70ᵇ</span> <span dir=\"rtl\">בן ז׳</span> a healthy child; <span class=\"citation\">Num. R. s. 10</span> <a href=\"#\" data-headword=\"זֵרוּז\">זָרוּז</a>.—<span class=\"citation\">Tosef. Bekh. VI, 10</span> <span dir=\"rtl\">אם היה בנו ז׳</span> if his son is a bright student; <span class=\"citation\">Kidd. 29ᵇ</span>. <span class=\"citation\">Pes. 50ᵇ</span> <span dir=\"rtl\">יש ז׳ ונשכר</span> one is industrious and will be rewarded &amp;c.; <span class=\"citation\">Tosef. Yeb. IV, 8</span>, opp. <a href=\"#\" data-headword=\"שָׁפֵל I\">שפל</a> lazy.; a. fr.—Pl. <span dir=\"rtl\">זְרִיזִין</span>, fem. <a href=\"#\" data-headword=\"זְרִיזוּת\">זְרִיזוֹת</a>. <span class=\"citation\">Pes. 4ᵃ</span>, a. e. <span dir=\"rtl\">ז׳ מקדימיי למצרת</span> the zealous do their religious duty as early as possible. <span class=\"citation\">Sabb. 20ᵃ</span>, a. fr. <span dir=\"rtl\">כהנים ז׳ הן</span> priests are presumed to be scrupulous.—<span class=\"citation\">Pes. 89ᵃ</span>, a. e. <span dir=\"rtl\">נמצאו בנות ז׳ וכ׳</span> the daughters proved to be zealous &amp;c.; a. fr.</div>","alt":[]},"11875":{"h":"זָרֵיז","r":"G00704","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. XXIV, 5</span> (some ed. <span dir=\"rtl\">זדין</span>, corr. acc.). <span class=\"citation\">Targ. Y. Lev. XXIV, 12</span>, opp. <a href=\"#\" data-headword=\"מָתוּן I\">מָתוּן</a>; a. fr.—<span class=\"citation\">Ḥull. 107ᵇ</span> <span dir=\"rtl\">דז׳</span> because he is scrupulous, contrad. to <a href=\"#\" data-headword=\"זָהִיר\">זָהִיר</a>.—Pl. <span dir=\"rtl\">זְרִיזִין</span>, fem. <span dir=\"rtl\">זְרִיזָן</span>. <span class=\"citation\">Targ. Esth. III, 15</span>; a. e.—<span class=\"citation\">Targ. Y. Ex. I, 19</span> (not … <a href=\"#\" data-headword=\"זִין I\">זִין</a>).</div>","alt":["זָרִיז"]},"11876":{"h":"זָרִיז ²","r":"G00705","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>belt</i>, v. <a href=\"#\" data-headword=\"זְרַז II\"><span dir=\"rtl\">זְרַז</span> II</a>.</div>","alt":[]},"11877":{"h":"זְרִיזוּת","r":"G00706","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרִיז\">זָרִיז</a>) <i>strength, quickness, zeal, industry</i>. <span class=\"citation\">Ab. Zar. 20ᵇ</span>, v. <a href=\"#\" data-headword=\"זְהִירוּת\">זְהִירוּת</a>. <span class=\"citation\">Sot. 12ᵇ</span> <span dir=\"rtl\">בז׳ כעלמה</span> quick like a girl. <span class=\"citation\">Lev. R. s. 11</span>, end (ref. to <a href=\"#\" data-headword=\"עַלְמוּת\">על־מות</a>, <span class=\"citation\">Ps. XLVIII, 15</span>) <span dir=\"rtl\">בעלמות בז׳</span> with <i>almuth</i>, that is with alertness. Sifra Sh’mini, beg. <a href=\"#\" data-headword=\"בִּיזּוּעַ\">בז׳</a>; a. fr.</div>","alt":[]},"11878":{"h":"זְרִיזוּתָא","r":"G00707","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Lev. IX, 8</span>, v. preced.—<span class=\"citation\">Ḥull. 16ᵃ</span> <span dir=\"rtl\">זְרִיזוּתֵיה … קמ&quot;ל</span> the Bible verse quoted intimates only Abraham’s zeal.</div>","alt":[]},"11879":{"h":"זְרִיחָה","r":"G00708","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרַח\">זָרַח</a>) <i>rise, brightness</i>. <span class=\"citation\">Y. Erub. V, 22ᶜ</span> <span dir=\"rtl\">זְרִיחַת החמה</span> sunrise, East. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">בזְרִיחָתָהּ</span> in its rise. <span class=\"citation\">Pes. 2ᵃ</span> כן ז׳ שמש וכ׳ Ms. M. (ed. <span dir=\"rtl\">כעין</span>) so will be the sunshine for the righteous &amp;c.; a. fr.</div>","alt":[]},"11880":{"h":"זְרִיָּיה","r":"G00709","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְרִיָּה\">זְרִיָּה</a></div>","alt":[]},"11881":{"h":"זְרִיעַ","r":"G00710","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְרַע I\"><span dir=\"rtl\">זְרַע</span> I</a></div>","alt":[]},"11882":{"h":"זְרִיעָה","r":"G00711","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרַע\">זָרַע</a>) <i>sowing, seed</i>. <span class=\"citation\">Ber. 35ᵇ</span> <span dir=\"rtl\">בשעת ז׳</span> at seed-time. <span class=\"citation\">Sabb. 91ᵃ</span> <span dir=\"rtl\">לז׳</span> to use it for seed; a. fr.</div>","alt":[]},"11883":{"h":"זְרִיקָה","r":"G00712","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרַק\">זָרַק</a>) </div><div class=\"sense\"><b>1)</b> <i>sprinkling</i> the blood on the altar. <span class=\"citation\">Zeb. 25ᵇ</span>. <span class=\"citation\">Y. Pes. VII, 34ᵇ</span> bot.; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>thrusting</i>. <span class=\"citation\">Sabb. 96ᵇ</span> <span dir=\"rtl\">ז׳ תולדה וכ׳</span> thrusting (on the Sabbath from one area, <a href=\"#\" data-headword=\"רָשׁוּת I\">רשות</a>, to another) is forbidden as a subspecies of carrying (v. <a href=\"#\" data-headword=\"הוֹצָאָה\">הוֹצָאָה</a>). Y. Erub. IV, beg. 21ᵈ <span dir=\"rtl\">ע&quot;י ז׳</span> by means of thrusting from place to place; a. fr.</div>","alt":[]},"11884":{"h":"זְרִיקְתָּא","r":"G00713","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זרק</span>) <i>that which is thrown off, pickings in the woods</i>, used as fuel. <span class=\"citation\">Targ. Is. XXXIII, 4</span> <span dir=\"rtl\">זריק׳</span> ed. Lag. (oth. ed. <span dir=\"rtl\">זִירְקְ׳</span>, <span dir=\"rtl\">זִרְקְ׳</span>; h. text <span dir=\"rtl\">גֵּבִים</span>, cmp. <a href=\"#\" data-headword=\"גְּבָבָה\">גְּבָבָה</a>); v. <a href=\"#\" data-headword=\"אֲזִי\">אֲזִי</a>.</div>","alt":["זִירְקְתָא"]},"11885":{"h":"זְרִירָא","r":"G00714","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרַר\">זרר</a>; cmp. <a href=\"#\" data-headword=\"זרי\">זרי</a>; cmp. Lat. sternuo) <i>sputtering, sneezing</i>. <span class=\"citation\">Targ. Job XLI, 10</span> <span dir=\"rtl\">זְרִירוֹי</span> (<span dir=\"rtl\">זְרִירוֹהִי</span>) (Var. <a href=\"#\" data-headword=\"מַקְקָא\">מַקְקָא</a>).</div>","alt":["זְרִירִין"]},"11886":{"h":"זריתיה","r":"G00715","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זַרְתָּא\">זַרְתָּא</a></div>","alt":[]},"11887":{"h":"זרכאי","r":"G00716","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*זַרְוַאי\">זַרְוַאי</a></div>","alt":[]},"11888":{"h":"זַרְכֵּל","r":"G00717","html":"<div class=\"sense\">, <i>Ithpa.</i> <span dir=\"rtl\">אִזְדַּרְכֵּל</span> (orig. Ithpa. of <a href=\"#\" data-headword=\"דרכל\">דרכל</a>, fr. <span dir=\"rtl\">דרך</span>, cmp. <span dir=\"rtl\">אתדרכל</span> P. Sm. 952; v. ib. 1157 s. v. <a href=\"#\" data-headword=\"זַרְכֵּל\">זרכל</a> a. sq.) <i>to walk proudly</i>. <span class=\"citation\">Targ. Prov. XXX, 31</span> <span dir=\"rtl\">מִיזְדַּרְכֵּיל</span> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"מִזְדְּרַע\">מִזְדְּרַז</a>, v. <a href=\"#\" data-headword=\"זְרַז I\">זְרַז</a>), v. <a href=\"#\" data-headword=\"*אַבָּכָא\">אַבָּכָא</a>.</div>","alt":[]},"11889":{"h":"זַרְמִית","r":"G00718","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= b. h. <span dir=\"rtl\">זֶרֶם</span>; cmp. <span dir=\"rtl\">זרב</span>, <a href=\"#\" data-headword=\"זרי\">זרי</a>) <i>shower, storm</i>. <span class=\"citation\">Targ. Is. IV, 6</span> <span class=\"citation\">Ib. XXVIII, 2</span>; a. e.</div>","alt":["זְרָמִית"]},"11890":{"h":"זָרָנָא","r":"G00719","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָרַר\">זרר</a>, cmp. <a href=\"#\" data-headword=\"זְרִירָא\">זְרִירָא</a>) <i>vomiting, nausea</i>. <span class=\"citation\">Lev. R. s. 18</span>, end (expl. <a href=\"#\" data-headword=\"זָרָא\">זָרָא</a>, <span class=\"citation\">Num. XI, 20</span>); (<span class=\"citation\">Num. R. s. 7</span> <span dir=\"rtl\">לזָרָא</span>; Ar. s. v. <a href=\"#\" data-headword=\"בּוּטְנָא I\">בוטנא</a>: <a href=\"#\" data-headword=\"זֵירָנָא\">זֵירָנָא</a>).</div>","alt":[]},"11891":{"h":"זַרְנוּקָא","r":"G00720","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<i>Parel</i> of <a href=\"#\" data-headword=\"זָנַק\">זנק</a>, cmp. <a href=\"#\" data-headword=\"זִיקָא II\"><span dir=\"rtl\">זִיקָא</span> II</a>) <i>leather bag, hose</i>. <span class=\"citation\">Targ. Ps. CXIX, 83</span> (h. text <a href=\"#\" data-headword=\"נֹאד\">נֹאד</a>).—<span class=\"citation\">B. Mets. 103ᵇ</span> <span dir=\"rtl\">דוולא וז׳</span> buckets and hose (for irrigation). <span class=\"citation\">B. Bath. 58ᵃ</span> <span dir=\"rtl\">ז׳ אמרה לכו</span> (comment. <span dir=\"rtl\">זרונקא</span>, Ms. O. <span dir=\"rtl\">זרקונא</span>, corr. acc.) she means a hose (which had been made of the hide of the animal stolen from her). <span class=\"citation\">Ib. 167ᵃ</span> <span dir=\"rtl\">קם אז׳</span> (some ed. <span dir=\"rtl\">אזרונקא</span>, v. Rabb. D. S. a. l. note) he wrote standing on a hose (to imitate a trembling hand-writing).—Pl. <span dir=\"rtl\">זַרְניּקין</span>. <span class=\"citation\">Targ. Job XXXII, 19</span> Ar. (ed. <span dir=\"rtl\">לגינין</span>, insert <a href=\"#\" data-headword=\"הֵיךְ\">היך</a>).</div>","alt":[]},"11892":{"h":"זַרְנִיךְ","r":"G00721","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. P. Sm. 1158) <i>arsenic, orpiment</i> (v. Sm. Ant. s. v. Arsenicon). <span class=\"citation\">Ḥull. 88ᵇ</span> bot.</div>","alt":[]},"11893":{"h":"זָרַע","r":"G00722","html":"<div class=\"sense\"><i>to strew, sow.</i> <span class=\"citation\">Kil. I, 9</span>. <span class=\"citation\">Ib. II, 3</span> <a href=\"#\" data-headword=\"זְרַע I\">אֶזְרַע</a>, v. <a href=\"#\" data-headword=\"אָפַךְ\">אָפַךְ</a>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"זֵרוּעַ\">זָרוּעַ</a>, f. <span dir=\"rtl\">זְרוּעָה</span>; pl. <span dir=\"rtl\">זְרוּעִים</span> &amp;c. Ib. <span dir=\"rtl\">ז׳ חטים</span> sown with wheat; a. fr.—<span class=\"citation\">Y. Sot. I, 17ᵇ</span> top <span dir=\"rtl\">כשם … בנותיהן זרועות וכ׳</span> as well as their vineyards are sown with mixed seeds, so are their daughters &amp;c. (faithless wives).</div><div class=\"sense\"><b>Nif. נִזְרַע</b> <div class=\"sense\"><i>to be sown, to be stocked with seed</i>. <span class=\"citation\">Gen. R. s. 83</span>, end, a. e. <span dir=\"rtl\">בשבילי נִזְרְעָה וכ׳</span> the field has been sown for my sake. <span class=\"citation\">Shebi. IV, 2</span> <span dir=\"rtl\">תִּזָרֵעַ</span> may be sown; a. fr.</div></div><div class=\"sense\"><b>Hif. הִזְרִיעַ</b> <div class=\"sense\"><i>to emit semen</i>(also used of women emitting a secretion at coition). <span class=\"citation\">Ber. 60ᵃ</span>, a. e. <span dir=\"rtl\">איש מַזְרִיעַ תחלה</span> when the male is the first to emit semen; <span dir=\"rtl\">אשה מַזְרַעַת וכ׳</span> when the female is the first &amp;c.; a. fr.</div></div>","alt":[]},"11894":{"h":"זְרַע I","r":"G00723","html":"<div class=\"sense\"><span class=\"citation\">Targ. Jud. VI, 3</span>; a. fr.—Part. <a href=\"#\" data-headword=\"זְרַע I\">זָרֵעַ</a>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"זְרִיעַ\">זְרִיעַ</a>) <a href=\"#\" data-headword=\"זְרִיעַ\">זָרֵיעַ</a></span>. <span class=\"citation\">Targ. Prov. XI, 18</span>; a. fr.—<span class=\"citation\">Targ. Is. XXVIII, 25</span> <span dir=\"rtl\">זָרְעֵי</span>. <span class=\"citation\">Ib. XXXII, 20</span> <span dir=\"rtl\">זָרְעִין</span>.—<span class=\"citation\">R. Hash. 16ᵃ</span> <span dir=\"rtl\">לִיזְרַע חרפא</span> let him sow early seed (barley &amp;c.). <span class=\"citation\">Y. Peah VII, 20ᵇ</span> top <span dir=\"rtl\">הוה ז׳ חקלא וכ׳</span> planted carrots on his field; a. fr.</div><div class=\"sense\"><b>Ithpa. אִזְדָּרַע</b> </div><div class=\"sense\"><b>Ithpe. אִזְדְּרַע</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"זָרַע\">preced.</a> <i>Nif.</i> <span class=\"citation\">Targ. O. Deut. XXIX, 22</span>; a. e.—Y. Peah l. c. <span dir=\"rtl\">אִזְדַּרְעוּן</span> they have been planted.</div></div><div class=\"sense\"><b>Af. אַזְרַע</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"זָרַע\">preced.</a> <i>Hif.</i> Y. Kil. I, 27ᵃ bot. <span dir=\"rtl\">ומַזְרְעִין</span> and they copulated.</div></div>","alt":[]},"11895":{"h":"זֶרַע","r":"G00724","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְרַע I\">preced.</a>) <i>seed;</i> animalic <i>semen</i> (mostly <span dir=\"rtl\">שִׁכְבַת ז׳</span>). <span class=\"citation\">Gen. R. s. 73</span> <span dir=\"rtl\">נעשו המים ז׳ וכ׳</span> the water in their bellies turned into semen. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> bot. <span dir=\"rtl\">נוטל הימנו ז׳</span> he may take seed thereof. <span class=\"citation\">Shebi. II, 8</span> <span dir=\"rtl\">שזרעו לז׳</span> which he planted for the sake of obtaining seed, opp. <span dir=\"rtl\">לירק</span> for using it as vegetable; a. fr.—Trnsf. <i>issue, descent</i>. <span class=\"citation\">Gen. R. s. 23</span>; s. 51 <span dir=\"rtl\">אותו ז׳ שהוא וכ׳</span> that issue which was to come from a foreign place (Moab). <span class=\"citation\">Ber. 31ᵇ</span> <span dir=\"rtl\">ז׳ שמושח וכ׳</span> a descendant who will anoint two men; a. fr.—Pl. <span dir=\"rtl\">זְרָעִים</span>. <span class=\"citation\">Peah II, 3</span> <span dir=\"rtl\">הכל מפסיק לז׳</span> all of them form a partition with regard to seeds (making each field separately subject to Peah), opp. to trees. <span class=\"citation\">Kil. III, 2</span> <span dir=\"rtl\">כל מין ז׳</span> all kinds of seeds (small vegetable), opp. <span dir=\"rtl\">ירקות</span> large beans &amp;c.; a. fr.—<span class=\"citation\">Y. Shebi. II, 34ᵃ</span> top <span dir=\"rtl\">ששה זְרָעִין</span> six <i>sowing seasons</i> during a Sabbatical period.—<span dir=\"rtl\">סֶרֶר ז׳</span> or <span dir=\"rtl\">ז׳</span> <i>Order of Seeds</i>, <i>Z’raim</i>, the first of the six orders of the Mishnah a. Tosefta. <span class=\"citation\">Sabb. 31ᵃ</span>. <span class=\"citation\">Esth. R. to I, 2</span>.</div>","alt":[]},"11896":{"h":"חַסְיָא","r":"H01367","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"*חֲסִי\">preced.</a>) <i>scrubby, lean</i>.—<i>Pl. fem.</i> <span dir=\"rtl\">חַסְיָין</span>. <span class=\"citation\">Targ. Y. Gen. XLI, 3</span> (some ed. <span dir=\"rtl\">חסכן</span>; v. 4 <span dir=\"rtl\">חסירן</span>); ib. v. 19.</div>","alt":[]},"11897":{"h":"חָסִיד","r":"H01368","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>kind, God-fearing, submissive, pious, abstemious</i>. <span class=\"citation\">Tem. 15ᵇ</span> <span dir=\"rtl\">כל היכא דאמר מעשה בח׳ אחד וכ׳</span> wherever we read (in Talmudic writings), ‘It is reported of a pious man’, either R. Juda b. Baba it meant or &amp;c. <span class=\"citation\">Sot. III, 4</span> <span dir=\"rtl\">ח׳ שוטה</span> a foolish saint. <span class=\"citation\">Ab. V, 10</span> <span dir=\"rtl\">שלי … ח׳</span> he who says, Mine is thine and thine is thine, is a <i>ḥasid</i>. <span class=\"citation\">Ib. 11</span>; a. v. fr.—Pl. <span dir=\"rtl\">חֲסִידִים</span>. <span class=\"citation\">Ber. V, 1</span> <span dir=\"rtl\">ח׳ הראשונים</span> the pious men of olden days; a. v. fr.</div>","alt":[]},"11898":{"h":"חֲסִיד","r":"H01369","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חָסִיד\">same</a>. <span class=\"citation\">Targ. Ps. XVIII, 26</span>; a. fr.—<span class=\"citation\">B. Kam. 30ᵃ</span> <span dir=\"rtl\">האי … למיהוי ח׳</span> he who desires to be a conscientious man (in business) let him live up to the laws laid down in <i>N’zikin</i> (v. <a href=\"#\" data-headword=\"נֶזֶק\">נֶזֶק</a>). <span class=\"citation\">B. Bath. 7ᵇ</span>; a. fr.—Frequ. as a distinguishing surname. <span class=\"citation\">M. Kat. 17ᵃ</span>. <span class=\"citation\">Ber. 29ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">חֲסִידַיָּא</span>, <span dir=\"rtl\">חֲסִידֵי</span>. <span class=\"citation\">Targ. Ps. CXLV, 10</span>; a. e.—<span class=\"citation\">Ḥull. 122ᵃ</span>, a. e. <span dir=\"rtl\">ח׳ דבבל</span> the meek men of Babylonia, opp. <span dir=\"rtl\">תקיפי</span>. <span class=\"citation\">M. Kat. 17ᵃ</span> <span dir=\"rtl\">למערתא דח׳</span> to the cave where the pious were buried; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"חֲסִיד\">חֲסִידָא</a>, <a href=\"#\" data-headword=\"חֲסִידְתָּא\">חֲסִידְתָּא</a>. <span class=\"citation\">Sabb. 77ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲסִיתָא\">אֲסִיתָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>graceful</i>. <span class=\"citation\">Targ. Prov. XI, 16</span>. <span class=\"citation\">Ib. XVII, 8</span>.</div>","alt":["חָסִיד","חֲסִידָא"]},"11899":{"h":"חֲסִידָה","r":"H01370","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"חָסִיד\">חָסִיד</a>; v. also <a href=\"#\" data-headword=\"חֲסוּדָה I\">חֲסוּדָה</a>, s. v. <a href=\"#\" data-headword=\"חָסַד I\"><span dir=\"rtl\">חָסַד</span> I</a>. I.</div><div class=\"sense\"><b>—2)</b>  (b. h.) <i>stork</i>. <span class=\"citation\">Ḥull. 63ᵃ</span>, v. <a href=\"#\" data-headword=\"דַּיָּה\">דַּיָּה</a>; <span dir=\"rtl\">ולמה … ח׳ שעושה חסידות וכ׳</span> and she is named ‘the kind’ because she acts kindly with her kind; <span class=\"citation\">Midr. Till. to Ps. CIV, 17</span>. <span class=\"citation\">Ex. R. s. 35</span>.</div>","alt":[]},"11900":{"h":"חֲסִידוּת","r":"H01371","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָסִיד\">חָסִיד</a>) <i>piety, scrupulousness, abstemiousness; kindness</i>. <span class=\"citation\">Ḥull. 63ᵃ</span>, v. preced.—<span class=\"citation\">B. Mets. 52ᵇ</span>; <span class=\"citation\">Ḥull. 130ᵇ</span>, a. fr. <span dir=\"rtl\">מדת ח׳</span> the conduct of a very scrupulous person. <span class=\"citation\">Ab. Zar. 20ᵇ</span>; <span class=\"citation\">Y. Sabb. I, 3ᶜ</span> top; a. fr.</div>","alt":[]},"11901":{"h":"חֲסִידוּתָא","r":"H01372","html":"<div class=\"sense\"><span class=\"citation\">Targ. Cant. III, 6</span>; a. e., v. <a href=\"#\" data-headword=\"חִסְדּוּתָא\">חִסְדּוּתָא</a>.—<span class=\"citation\">Snh. 110ᵇ</span> שַׁבְקָהּ ר&quot;ע לחֲסִידוּתֵיה R. Ak. has abandonned his (usual) kindness, i.e. his harsh opinion does not agree with the liberality shown elsewhere.</div>","alt":[]},"11902":{"h":"חֲסִידְתָּא","r":"H01373","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲסִיד\">חֲסִיד</a></div>","alt":[]},"11903":{"h":"חֲסִיךְ","r":"H01374","html":"<div class=\"sense\"> c. (חסך II, v. <a href=\"#\" data-headword=\"חֲסוֹךְ II\"><span dir=\"rtl\">חֲסוֹךְ</span> II</a> and <a href=\"#\" data-headword=\"חֲשִׁיךְ ²\"><span dir=\"rtl\">חֲשִׁיךְ</span> II</a>) <i>rubbed off, lessened</i>; (of animals or plants) <i>stunted, lean</i>. <span class=\"citation\">Men. 29ᵃ</span> ומי ח׳ כולי האי Ar. (ed. <a href=\"#\" data-headword=\"חָסַר\">חסר</a>; Rashi to <span class=\"citation\">Taan. 11ᵃ</span>: <span dir=\"rtl\">חֲסִיכֵי</span>, pl.) is there so much reduction (loss in weight by smelting)?—Pl. <span dir=\"rtl\">חֲסִיכֵי</span>; fem. <a href=\"#\" data-headword=\"חֲסִיךְ\">חֲסִיכָן</a>, <span dir=\"rtl\">חֲסִיכָתָא</span>. <span class=\"citation\">Targ. Gen. XLI, 19</span>; <span class=\"citation\">20</span>; <span class=\"citation\">27</span> (interch. with <span dir=\"rtl\">חסיר׳</span> a. <span dir=\"rtl\">חסיי׳</span>, v. <a href=\"#\" data-headword=\"חַסְיָא\">חַסְיָא</a>).—<span class=\"citation\">Pes. 48ᵃ</span> <span dir=\"rtl\">חיטי ח׳</span> poor wheat.</div>","alt":["חֲסִיכָא"]},"11904":{"h":"חֲסֵיכְנָא","r":"H01375","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסִיךְ\">preced.</a>) <i>a little less</i>. <span class=\"citation\">Targ. Is. XXVI, 12</span> <span dir=\"rtl\">ח׳ מחובנא</span> a little less that our sins deserved (h. text <a href=\"#\" data-headword=\"גַּם I\">גם</a>, cmp. <span dir=\"rtl\">גמם</span>).</div>","alt":[]},"11905":{"h":"חֲסִיל","r":"H01376","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲסַל\">חֲסַל</a></div>","alt":[]},"11906":{"h":"חָסִיל","r":"H01377","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>the peeler</i>,] name of <i>a species of locusts</i>. <span class=\"citation\">Snh. 94ᵇ</span>. <span class=\"citation\">Y. Taan. III, 66ᵈ</span>, v. <a href=\"#\" data-headword=\"חָסַל\">חָסַל</a>.</div>","alt":[]},"11907":{"h":"חָסִילָא","r":"H01378","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַל\">חֲסַל</a>) <i>weaned child, infant</i>. <span class=\"citation\">Targ. Is. XI, 8</span> (h. text <a href=\"#\" data-headword=\"גְּמוּל\">גָּמוּל</a>); a. e.</div>","alt":["חֲ׳"]},"11908":{"h":"חֲסִים","r":"H01379","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"חֲסַם\">חֲסַם</a></div>","alt":[]},"11909":{"h":"חֲסִימָה I","r":"H01380","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָסַם I) <i>muzzling, the law forbidding muzzling</i> (<span class=\"citation\">Deut. XXV, 4</span>). <span class=\"citation\">B. Mets. 88ᵇ</span> <span dir=\"rtl\">אתה מצווה על חֲסִימָתוֹ</span> thou art warned not to muzzle him. <span class=\"citation\">Ib. 89ᵃ</span> <span dir=\"rtl\">כל מילי איתנהו בח׳</span> all things (animals) are implied in the law &amp;c. <span class=\"citation\">Ib. 90ᵇ</span> <span dir=\"rtl\">ח׳ מעלייתא הוא</span> it is a real case of muzzling; a. fr.</div>","alt":[]},"11910":{"h":"חֲסִימָה II","r":"H01381","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָסַם II) </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"חִיסּוּם\">חִיסּוּם</a>, <i>steel-edge</i>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 7</span>.</div><div class=\"sense\"><b>—2)</b> <i>varnish, glaze</i>. Ib. I, 3 (quot. in R. S. to <span class=\"citation\">Kel. XI, 4</span>), v. <a href=\"#\" data-headword=\"מַחֲסוֹמִית\">מַחְסוֹמִית</a>.</div>","alt":[]},"11911":{"h":"חסין","r":"H01382","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 43</span> <span dir=\"rtl\">קאלא ח׳</span>, v. <a href=\"#\" data-headword=\"*קאלוחסין\">קאלוחסין</a></div>","alt":[]},"11912":{"h":"חָסִין","r":"H01383","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חֲסַן I) <i>strong; hard</i>. <span class=\"citation\">Targ. Ez. XXIII, 31</span> (<span class=\"citation\">32</span>). <span class=\"citation\">Targ. Am. II, 9</span>; a. e.—Pl. <span dir=\"rtl\">חֲסִינִין</span>, <span dir=\"rtl\">חֲסִינַיָּא</span>; f. <a href=\"#\" data-headword=\"חָסִין\">חֲסִינָן</a>, <a href=\"#\" data-headword=\"חָסִין\">חֲסִינָתָא</a>. <span class=\"citation\">Targ. O. Deut. XXVIII, 23</span>. <span class=\"citation\">Targ. Is. XXVIII, 2</span>. <span class=\"citation\">Ib. XXI, 1</span>; <span class=\"citation\">Targ. Deut. X, 21</span> <i>mighty deeds</i></div>","alt":["חֲסִינָא","חֲסִינְתָּא"]},"11913":{"h":"חֲסִינָה","r":"H01384","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חִסְנָא\">חִסְנָא</a>) [<i>storage</i>,] <i>a wicker work</i> used for purposes of storage. <span class=\"citation\">Kel. XVI, 5</span>.</div>","alt":[]},"11914":{"h":"חֲסִיסָא","r":"H01385","html":"<div class=\"sense\"> (<span dir=\"rtl\">חסס</span>, v. <a href=\"#\" data-headword=\"חַסְיָא\">חַסְיָא</a>) <i>stunted grains</i> used for parching, v. <a href=\"#\" data-headword=\"אַבְשׁוּנָא\">אַבְשׁוּנָא</a>. <span class=\"citation\">Ned. 49ᵇ</span>. <span class=\"citation\">Pes. 40ᵇ</span></div>","alt":["חֲסִיסֵי"]},"11915":{"h":"חֲסִיסָה","r":"H01386","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">חסחיסה</span>) = <a href=\"#\" data-headword=\"חַסְחָסוּת\">חַסְחָסוּת</a>. <span class=\"citation\">Tosef. Bekh. IV, 13</span> <span dir=\"rtl\">חסו׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"חָסֵר II\">חסי׳</a>).—Pl. <span dir=\"rtl\">חֲסִיסוֹת</span>. Ib.</div>","alt":[]},"11916":{"h":"חָסֵיר","r":"H01387","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָסֵר\">חָסֵר</a></div>","alt":["חֲסֵירָה"]},"11917":{"h":"חֲסִיר","r":"H01388","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַר\">חֲסַר</a>) <i>wanting, less; reduced, lean</i> (v. <a href=\"#\" data-headword=\"חַסְיָא\">חַסְיָא</a> a. <a href=\"#\" data-headword=\"חֲסִיךְ\"><a href=\"#\" data-headword=\"חֲסִיךְ\">חֲסִיךְ</a>)</a>. <span class=\"citation\">Targ. Prov. VII, 7</span>; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"חָסִין\">חֲסִירָא</a>, <a href=\"#\" data-headword=\"חָסֵר II\">חַסִּי׳</a><i>.</i> Pl. <span dir=\"rtl\">חֲסִירָן</span>, <span dir=\"rtl\">חַסִּ׳</span>. <span class=\"citation\">Targ. Gen. XLI, 3</span>; <span class=\"citation\">4</span>; a. e.—V. also <a href=\"#\" data-headword=\"חָסֵר\">חָסֵר</a> ch.</div>","alt":["חַסִּיר"]},"11918":{"h":"חַסִּירוּתָא","r":"H01389","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסִיר\">preced.</a>) <i>want, absence</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 48</span>; a. e.—V. <a href=\"#\" data-headword=\"חוּסְרָן\">חוּסְרָנָא</a>.</div>","alt":["חֲסֵירוּ׳","חַסְרוּ׳"]},"11919":{"h":"חָסִית I","r":"H01390","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">חססית</span>; <span dir=\"rtl\">חסס</span>, cmp. Ar. <i>ḥassa</i>) <i>peeling plants, alliacea, leek plants.</i> <span class=\"citation\">Ter. X, 10</span> <span dir=\"rtl\">אלא עם הח׳</span> (Ms. M. <span dir=\"rtl\">החִיסוֹת</span>; Y. ed. <span dir=\"rtl\">החִיסִית</span>) except they are combined with leek-plants. Y. ib. 47ᵇ <span dir=\"rtl\">ח׳ בח׳ מין במינו</span> if the same species of leek plants (of T’rumah and Ḥullin) are pressed together. <span class=\"citation\">Lam. R. to II, 11</span>, v. <a href=\"#\" data-headword=\"דִּמְעָה\">דִּמְעָה</a>.—Pl. <span dir=\"rtl\">חָסִיּוֹת</span>. <span class=\"citation\">Tosef. Ter. IX, 3</span> <span dir=\"rtl\">אלו הן מיני ח׳ וכ׳</span> (ed. Zuck. <span dir=\"rtl\">חרסיות</span>, Var. <span dir=\"rtl\">חוריות</span>, <span dir=\"rtl\">חסיות</span>) the following belong to the leek-plants, common leek, garlic, onion and allium porrum, v. <a href=\"#\" data-headword=\"קַפְלוֹט\">קַפְלוֹט</a>.</div>","alt":[]},"11920":{"h":"חָסִית II","r":"H01391","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  (<a href=\"#\" data-headword=\"חוּס\">חוּס</a>) <i>saving, protection</i>. <span class=\"citation\">Yalk. Ex. 200</span> <span dir=\"rtl\">אין פסיחה אלא ח׳</span> passing over (the root <a href=\"#\" data-headword=\"פסח\">פסח</a>) means sparing; (Mekh. Bo, Pisḥa, s. 11 <a href=\"#\" data-headword=\"חַיִיס I\">חַיִיס</a>).</div><div class=\"sense\"><b>—2)</b>  (<span dir=\"rtl\">חָסָה</span>) <i>shady place</i>, v. <a href=\"#\" data-headword=\"חָסוּת\">חָסוּת</a>.</div>","alt":[]},"11921":{"h":"חָסַךְ","r":"H01392","html":"<div class=\"sense\"> [<i>to scrape off</i>,] <i>to diminish, deduct; to stint, withhold.</i> <span class=\"citation\">Dem. VII, 3</span> (<span class=\"citation\">4</span>) <span dir=\"rtl\">וחוֹסֵךְ גרוגרת וכ׳</span> Ar. a. ed. Y. (Mish. a. Bab. ed. <span dir=\"rtl\">חוֹשֵׂךְ</span>, Ms. M. repeatedly <span dir=\"rtl\">חתך</span>) and retains one fig (which he does not eat). Ib. <span dir=\"rtl\">לא יַחְסוֹךְ</span> (Var. same).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חֲסוֹךְ I\">חָסוּךְ</a> <i>stripped, wanting.</i> <span class=\"citation\">Kel. I, 2</span> <span dir=\"rtl\">(<span dir=\"rtl\">וחֲשׂוּכֵי</span>) <span dir=\"rtl\">וחֲסוּכֵי בגדים</span></span> and to make unclean the persons alone but not their clothes. <span class=\"citation\">Erub. 28ᵃ</span> חֲסוּכֵי בנים Ms. M. a. oth. (ed. <span dir=\"rtl\">חשוכי</span>) those who want children, opp. <span dir=\"rtl\">מרובי בנים</span>.</div><div class=\"sense\"><b>Pi. חִיסֵּךְ</b> <div class=\"sense\"><i>to spare, be regardful, lenient</i>. <span class=\"citation\">Tosef. Sot. VI, 7</span> <span dir=\"rtl\">ח׳ עליו הכתוב</span> the Biblical text (the Lord) spared him (did not rebuke him). Ib. <span dir=\"rtl\">מְחַסְּכִין לו</span> they (in heaven) spare him. <span class=\"citation\">Zeb. 6ᵇ</span> <span dir=\"rtl\">חי׳ הכתוב</span> the Biblical law has regard to expenses; v. <a href=\"#\" data-headword=\"חִיסָּכוֹן\">חִיסָּכוֹן</a>.</div></div>","alt":[]},"11922":{"h":"חֲסַךְ","r":"H01393","html":"<div class=\"sense\">Part. pass. <a href=\"#\" data-headword=\"חֲסִיךְ\">חֲסִיךְ</a> q. v. <span class=\"citation\">Targ. Y. Gen. XLI, 3</span> <span dir=\"rtl\">חַסְכָן</span>, read: <a href=\"#\" data-headword=\"חֲסִיךְ\">חֲסִיכָן</a>.</div>","alt":[]},"11923":{"h":"חִסָּכוֹן","r":"H01394","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶסֶד ²\">חִיסָּ׳</a></div>","alt":[]},"11924":{"h":"חָסַל","r":"H01395","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"חִסָּכוֹן\">preced.</a> wds.) <i>to peel off, to bare</i>. <span class=\"citation\">Y. Taan. III, 66ᵈ</span> the locust is called <i>ḥasil</i> <span dir=\"rtl\">שהוא חוֹסֵל וכ׳</span> because it bares everything.</div>","alt":[]},"11925":{"h":"חֲסַל","r":"H01396","html":"<div class=\"sense\">, [<i>to scrape off</i>; (cmp. <a href=\"#\" data-headword=\"חָנַךְ\">חָנַךְ</a>) <i>to finish</i>,] </div><div class=\"sense\"><b>1)</b> <i>to cease, have done</i> (cmp. <a href=\"#\" data-headword=\"גָּמַר I\">גָּמַר</a>). <span class=\"citation\">Targ. II Chr. IV, 11</span>.—חֲסִיל <i>to be exhausted, gone</i>. <span class=\"citation\">Targ. Y. II, Gen. XLVII, 15</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXI, 24</span>; a. e.—<span class=\"citation\">Targ. Y. II, Gen. L, 19</span> <span dir=\"rtl\">חַסְלַת וכ׳</span> the evil is paid off (atoned for; cmp. <span dir=\"rtl\">גמל</span>).—Y. R. Hash. II, 58ᵇ top <span dir=\"rtl\">מן דַחֲסַל … מן וכ׳</span> when R. … had ceased from praying. <span class=\"citation\">Gen. R. s. 17</span>, beg. <span dir=\"rtl\">מן דחַסְלִין</span> (not <span dir=\"rtl\">דמן ח׳</span>) when they had finished their studies; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to mature, ripen</i>. <span class=\"citation\">Targ. Y. II, Num. XVII, 23</span> (h. text <span dir=\"rtl\">גמל</span>).</div><div class=\"sense\"><b>—3)</b> <i>to wean</i>. <span class=\"citation\">Targ. I Sam. I, 24</span> (h. text <span dir=\"rtl\">גמל</span>); a. fr.</div><div class=\"sense\"><b>Af. אַחְסִיל</b> </div><div class=\"sense\"><b>Pa. חַסַּל</b> <div class=\"sense\"><b>1)</b> <i>to peel off, lay bare</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 38</span>.</div><div class=\"sense\"><b>—2)</b> <i>to finish</i>. <span class=\"citation\">Targ. Y. II, Gen. XLVI, 18</span>.—Y. Bicc. I, 64ᵃ <span dir=\"rtl\">מְחַסֵּל לה</span> finished the sentence (by adding a general rule). Cant. R. beg. <span dir=\"rtl\">זימנין מח׳ לה וכ׳</span> sometimes he goes through the entire alphabet &amp;c.; (<span class=\"citation\">Koh. R. to I, 13</span> <span dir=\"rtl\">חשל</span>); a. fr.</div></div><div class=\"sense\"><b>Ithpe. אִתְחֲסִיל</b> <div class=\"sense\"><i>to be weaned</i>. <span class=\"citation\">Targ. O. Gen. XXI, 8</span> (ed. Berl. <a href=\"#\" data-headword=\"חֲרַר ³\">אִתְחַ׳</a>); a. e.</div></div>","alt":["חֲסִיל"]},"11926":{"h":"חָסַם I","r":"H01397","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"חֲסַל\">preced.</a> wds.,  [<i>to withhold, prevent</i>, v. <span class=\"citation\">Ez. XXXIX, 11</span>,] </div><div class=\"sense\"><b>1)</b> <i>to muzzle</i>, esp. <i>to prevent the animal from eating while at work</i> (with ref. to <span class=\"citation\">Deut. XXV, 4</span>). <span class=\"citation\">B. Mets. 90ᵃ</span> <span dir=\"rtl\">עובר משום בל תַּחְסוֹם</span> he trespasses the law forbidding to muzzle (if he prevents the animal from eating). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חֲסוֹם פרתי</span> muzzle my cow. <span class=\"citation\">Ib.ᵇ</span>, a. e. <span dir=\"rtl\">חֲסָמָהּ בקול</span> if he prevents her from eating by shouting at her; a. fr.—Trnsf. (an adaptation of Deut. l. c. which is followed by the law concerning leviratical marriage) <i>to tie a woman to a man</i> (<i>Yabam</i>) <i>with whom she cannot live</i>; [Rashi: <i>to shut a woman’s mouth, ignore her objections</i>]. <span class=\"citation\">Yeb. 4ᵃ</span> <span dir=\"rtl\">שאין חוֹסְמִין אותה</span> that we do not coërce her (to be the wife of a leper).</div><div class=\"sense\"><b>—2)</b> <i>to form the rim of basket work or of a leather bag.</i> <span class=\"citation\">Kel. XVI, 2</span>; <span class=\"citation\">3</span>; <span class=\"citation\">4</span>.</div><div class=\"sense\"><b>Nif. נֶחְסַם</b> <div class=\"sense\"><i>to be muzzled, to be prevented from eating while at work</i>. <span class=\"citation\">B. Mets. 89ᵃ</span> <span dir=\"rtl\">לאקושי חוֹסֵם לנֶחְסָם וכ׳</span> to draw a parallel between the muzzler (human laborer) and the muzzled (laboring brute).</div></div><div class=\"sense\"><b>Hithpa. הִתְחַסֵּם</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַסֵּם</b> <div class=\"sense\"><i>to be bent into a rim.</i> <span class=\"citation\">Kel. XX, 2</span>.</div></div>","alt":[]},"11927":{"h":"חֲסַם","r":"H01398","html":"<div class=\"sense\">, <i>to muzzle</i>; trnsf. <i>to silence</i>. <span class=\"citation\">Sot. 35ᵃ</span> <span dir=\"rtl\">וחַסְמִין לי</span> and they will silence me. <span class=\"citation\">Snh. 32ᵇ</span></div><div class=\"sense\"><b>Ithpe. אִתְחַסַּם</b> <div class=\"sense\"><i>Ithpe.</i> <a href=\"#\" data-headword=\"חֲסַם\">אִתְחֲסַם</a>, <a href=\"#\" data-headword=\"חֲרַךְ\">אִיחֲ׳</a> <i>to be muzzled, silenced</i>. <span class=\"citation\">Targ. Ps. XXXII, 9</span>. <span class=\"citation\">Ib. CVII, 42</span>.—Snh. l. c. <span dir=\"rtl\">ולִיחַסְּמוּ</span> let them be silenced (intimidated).</div></div>","alt":[]},"11928":{"h":"חָסַם II","r":"H01399","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">חסל</span>) <i>to peel, scrape, to polish, glaze, harden</i> (<i>steel</i>). <span class=\"citation\">Tosef. Shebi. VI, 10</span>; Y. ib. VIII, 38ᵇ bot. <span dir=\"rtl\">אין חוֹסְמִין וכ׳</span> you must not use it for glazing stoves or ranges. <span class=\"citation\">Tosef. Bets. III, 16</span> <span dir=\"rtl\">כדי לחוֹסְמָן</span> for the purpose of glazing them; <span class=\"citation\">Bets. 34ᵃ</span> <span dir=\"rtl\">לחַסְּמָן</span> (<i>Pi.</i>).—Y. M. Kat. I, end, 81ᵃ, v. infra.—[<span class=\"citation\">Tosef. Dem. IV, 12</span> <span dir=\"rtl\">משיחסום</span>, read: <span dir=\"rtl\">משיתנם</span>?]</div><div class=\"sense\"><b>Pi. חִיסֵּם</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲסַם\">same</a>. Bets. l. c., v. supra. Ib. <span dir=\"rtl\">מפני שצריך לחַסְּמָן</span> because it is necessary to glaze the tiles (by heating them).</div></div><div class=\"sense\"><b>Hithpa. הִתְחַסֵּם</b> <div class=\"sense\"><i>to be glazed</i>. Y. M. Kat. I, end, 81ᵃ [read:] <span dir=\"rtl\">ואין מפיגין אותן בצונן כדי שיִתְחַסְּמוּ</span> nor must you cool them off suddenly in order that they may be glazed (hardened). V. <a href=\"#\" data-headword=\"חִיסּוּם\">חִיסּוּם</a>.</div></div>","alt":[]},"11929":{"h":"חֲסַם ²","r":"H01400","html":"<div class=\"sense\"><i>Part. pass</i>. <a href=\"#\" data-headword=\"חֲסִים\">חֲסִים</a> <i>bright and hard, flinty</i>.—Pl. <span dir=\"rtl\">חֲסִימִין</span>. <span class=\"citation\">Targ. Y. II, Deut. VIII, 9</span>; (Y. I <span dir=\"rtl\">שאילן מסימן</span>, read: <span dir=\"rtl\">הֲסִימַן</span> fem. pl.). Targ. Y. ib. XXXIII, 25.</div><div class=\"sense\"><b>Pa. חַסֵּם</b> <div class=\"sense\"> [<i>to scrape</i>, cmp. <span dir=\"rtl\">גמגם</span>, <a href=\"#\" data-headword=\"חָכַךְ II\"><span dir=\"rtl\">חָכַךְ</span> II</a>] <i>to hesitate, be uncertain what to do</i>. <span class=\"citation\">Sabb. 147ᵃ</span> <span dir=\"rtl\">הוה קא מְחַסֵּם וכ׳</span> he hesitated to hand it to him. <span class=\"citation\">Keth. 20ᵇ</span>. <span class=\"citation\">B. Mets. 23ᵇ</span>. <span class=\"citation\">Ḥull. 50ᵃ</span>. [Ar. a. some Mss. have <a href=\"#\" data-headword=\"הֲסַם\">הסם</a>; v. Koh. Ar. Compl. s. v. <a href=\"#\" data-headword=\"הֲסַם\">הסם</a> a. Rabb. D. S. to B. Mets. l. c.]</div></div><div class=\"sense\"><b>Ithpa. אִתְחַסֵּם</b> <div class=\"sense\"><b>1)</b> <i>to receive a steel edge</i>; trnsf. (of the mouth) <i>to become able to speak</i>. <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Cant. R. to II, 2</span> אתח׳ ר׳ וכ׳ R. E. (who on a former occasion was unable to pronounce a blessing) has received a steel edge, and they named him R. E. Ḥisma; [Ar.: <span dir=\"rtl\">הא חֲסִים אלעזר</span>, v. supra].</div><div class=\"sense\"><b>—2)</b> <i>to rub against</i>, trnsf. (cmp. <a href=\"#\" data-headword=\"גָּרַר I\">גָּרַר</a>) <i>to seek a quarrel, to vie with</i> (v. P. Sm. 1333). <span class=\"citation\">Targ. Prov. XXIV, 19</span> (h. text <span dir=\"rtl\">תתחר</span>).</div></div>","alt":[]},"11930":{"h":"חֲסַן I","r":"H01401","html":"<div class=\"sense\"><b>1)</b> <i>to be strong</i>. [<span class=\"citation\">Targ. Is. LXIII, 15</span>, v. <i>Ithpa.</i>]—V. <a href=\"#\" data-headword=\"חוּסְנָא\">חוּסְנָא</a></div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">חזק</span>) <i>to take possession</i> (mostly in <i>Af.</i>).</div><div class=\"sense\"><b>Pa. חַסֵּין</b> <div class=\"sense\"><i>to strengthen</i>. <span class=\"citation\">Targ. Is. XXXV, 3</span> (h. text <a href=\"#\" data-headword=\"אָמַץ\">אמץ</a>).</div></div><div class=\"sense\"><b>Af. אַחְסֵין</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חֲסַם ²\">same</a>. <span class=\"citation\">Targ. O. Gen. XLIX, 24</span>. <span class=\"citation\">Targ. Am. II, 14</span> (h. text same. <span class=\"citation\">Targ. O. Gen. XLIX, 24</span>. <span class=\"citation\">Targ. Am. II, 14</span> (h. text <a href=\"#\" data-headword=\"אָמַץ\">אמץ</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to take possession</i> (for one’s self and heirs). <span class=\"citation\">Targ. Ps. XXXVII, 29</span>. <span class=\"citation\">Targ. O. Lev. XXV, 46</span> (Y. <span dir=\"rtl\">תִחְסְ׳</span>, <i>Pe</i>.); a. fr.—<span class=\"citation\">B. Bath. 148ᵇ</span> bot. <span dir=\"rtl\">אף יַחְסִין וירת וכ׳</span> also if he uses the expression <i>yaḥsin</i>, he shall take possession, or <i>yereth</i>, he shall inherit, referring to an heir.</div><div class=\"sense\"><b>—3)</b> <i>to give possession, to bequeathe</i>. <span class=\"citation\">Targ. O. Deut. XXXII, 8</span> <span dir=\"rtl\">באחסנא</span> (Y. <span dir=\"rtl\">באַחְסָנוּת</span> verbal noun, constr.). <span class=\"citation\">Targ. Y. I Num. XI, 26</span>.</div><div class=\"sense\"><b>—4)</b> <i>to hoard up</i> (v. <a href=\"#\" data-headword=\"חִסְנָא\">חִסְנָא</a>). <span class=\"citation\">Targ. Am. II, 6</span>; <span class=\"citation\">VIII, 6</span> (h. text <span dir=\"rtl\">נעלים</span>, v. <a href=\"#\" data-headword=\"נַעַל\">נַעַל</a>).</div><div class=\"sense\"><b>—5)</b>  (cmp. <a href=\"#\" data-headword=\"חָזַק\">חָזַק</a> Hif.) <i>to hold, have room for</i>. Y. Snh. X, 29ᵃ top (ref. to <span class=\"citation\">II Kings VI, 1</span>) <span dir=\"rtl\">לא א׳ אוכלוסייא וכ׳</span> (not <span dir=\"rtl\">אסחין</span></div></div><div class=\"sense\"><b>Ithpa. אִתְחַסֵּין  אִתְחַסַּן</b> <div class=\"sense\"><b>1)</b> <i>to strengthen one’s self, to betake one’s self; to control one’s own emotions</i>. <span class=\"citation\">Targ. Jer. III, 8</span>. <span class=\"citation\">Targ. Is. LXIII, 15</span> ed. Lag. (oth. ed. <span dir=\"rtl\">יֶחְסְ׳</span>).—<span class=\"citation\">Targ. O. Gen. XLIII, 31</span> (v. <a href=\"#\" data-headword=\"זְרַז I\">זְרַז</a>). <span class=\"citation\">Targ. I Sam. XIII, 12</span>; a. fr. (h. text <span dir=\"rtl\">התאפק</span>).</div><div class=\"sense\"><b>—2)</b> <i>to be put in possession</i>. <span class=\"citation\">Targ. Job VII, 3</span> (h. text <span dir=\"rtl\">הָנְחַלְתִּי</span>).</div></div>","alt":[]},"11931":{"h":"חֲסַן II","r":"H01402","html":"<div class=\"sense\"> (= <span dir=\"rtl\">חֲסַל I</span>), <i>Af.</i> אַחְסֵין <i>to wean</i>. <span class=\"citation\">Targ. Y. Gen. XXI, 8</span>.</div><div class=\"sense\"><b>Ithpa. אִתְחַסַּן</b> <div class=\"sense\"><b>1)</b> <i>to be weaned</i>. Ib.</div><div class=\"sense\"><b>—2)</b> <i>to be fully compensated</i>. <span class=\"citation\">Targ. Prov. XI, 31</span> (h. text <span dir=\"rtl\">יְשֻׁלָּם</span>).</div></div>","alt":[]},"11932":{"h":"חֹסֶן","r":"H01403","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוֹסֶן\">חוֹסֶן</a></div>","alt":[]},"11933":{"h":"חִסְנָא","r":"H01404","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַן I\">חֲסַן</a>) </div><div class=\"sense\"><b>1)</b> <i>strength, power.</i> <span class=\"citation\">Dan. II, 37</span>; v. <a href=\"#\" data-headword=\"חוּסְנָא\">חוּסְנָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>stronghold, store-house</i> (b. h. <a href=\"#\" data-headword=\"חֹסֶן\">חֹסֶן</a>).—Pl. <span dir=\"rtl\">חִסְנַיָּא</span>. <span class=\"citation\">Targ. Joel I, 17</span> Ar. (ed. Lag. <a href=\"#\" data-headword=\"חוּסְמָנָא\">חוּסְנַיָּא</a>; v. <a href=\"#\" data-headword=\"אִסְנָא\">אִסְנָא</a>).</div>","alt":[]},"11934":{"h":"חֲסַף I","r":"H01405","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָסַל\">חָסַל</a>) <i>to peel off</i>; (neut. verb) <i>to be scaly, rough</i>.</div><div class=\"sense\"><b>Pa. חַסַּף</b> <div class=\"sense\"><i>to pound grain</i> &amp;c. Y. Sabb. VII, 10ᵇ bot. <span dir=\"rtl\">ח׳ פלפלין</span> pounds pepper (cmp. <span dir=\"rtl\">מחספס</span>, <span class=\"citation\">Ex. XVI, 14</span>). [Y. B. Mets. II, 8ᶜ bot. <span dir=\"rtl\">וחספתה</span>, v. <a href=\"#\" data-headword=\"חֲפַס\">חֲפַס</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִתְחַסֵּף</b> <div class=\"sense\"> [<i>to become white</i>, cmp. <a href=\"#\" data-headword=\"כְּסַף I\">כסף</a>,] <i>to feel ashamed</i>. Targ. II Esth. VI, 12.</div></div>","alt":[]},"11935":{"h":"חֲסַף II","r":"H01406","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַף I\">preced.</a>) (= h. <a href=\"#\" data-headword=\"חֶרֶשׂ\">חֶרֶשׂ</a>) </div><div class=\"sense\"><b>1)</b> <i>rough clay</i>, <span dir=\"rtl\">מאנא דח׳</span> <i>clay vessel</i> (common and easily broken). (common and easily broken). <span class=\"citation\">Targ. O. Lev. XI, 33</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  [<i>something with which to peel or scrape</i>,] <i>fragment of a vessel, potsherd</i>. <span class=\"citation\">Targ. Prov. XXVI, 23</span>.—<span class=\"citation\">Yeb. 92ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"דְּלֵי\">דְּלֵי</a>. <span class=\"citation\">Kidd. 18ᵃ</span> (prov.) <span dir=\"rtl\">נקיט … יהיבנא ליה ח׳</span> he had a pearl in his hand, and we give him a sherd, i.e. for a valuable object we give him a valueless paper; a. fr.—Pl. <span dir=\"rtl\">חַסְפִּין</span>, <a href=\"#\" data-headword=\"חֲסַף II\">חִ׳</a>. <span class=\"citation\">Gen. R. s. 14</span>, v. <a href=\"#\" data-headword=\"דְּבֵק\">דְּבַק</a>; <span class=\"citation\">Midr. Till. to Ps. II</span>; a. e.</div>","alt":["חַסְפָּא","חִ׳ I"]},"11936":{"h":"חַסְפָּא","r":"H01407","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַף I\">חסף</a>; cmp. <a href=\"#\" data-headword=\"כִּסּוּפָא\">כסופא</a>) <i>shame;</i> (cmp. b. h. <a href=\"#\" data-headword=\"בּשֶׁת\">בּשֶׁת</a>) <i>idol</i>. <span class=\"citation\">Y. Ned. I, 37ᵃ</span> top (in answer to the question, ‘Does not <i>ḥeres</i> mean a sherd?’) <span dir=\"rtl\">לשון אומות … קריין לח׳ כספא</span> (<i>ḥeres</i> may be used as a substitute for <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>) for it is a gentile dialect, the Nabatæans say <i>ḥispa</i> for <i>kispa</i> (<a href=\"#\" data-headword=\"כִּסּוּפָא\">כסופא</a>) (which means <i>shame</i> or <i>idol</i>); <span class=\"citation\">Y. Naz. I, beg. 51ᵃ</span> (corr. acc.); v. <span class=\"citation\">Ned. 10ᵇ</span> top.</div>","alt":["חִ׳ II"]},"11937":{"h":"חַסְפְּיָה","r":"H01408","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḥaspiah</i> (<i>Hasbeya</i>), a border town in Northern Palestine. Y. Dem. II, 22ᵈ top; <span class=\"citation\">Tosef. Shebi. IV, 10</span> <span dir=\"rtl\">צפיח</span> ed. Zuck. (Var. <span dir=\"rtl\">חצפיא</span>, <a href=\"#\" data-headword=\"צִפְיָא\">צפיא</a>).</div>","alt":[]},"11938":{"h":"חַסְפְּנִיתָא","r":"H01409","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַף I\">חֲסַף</a>) </div><div class=\"sense\"><b>1)</b> <i>scaly skin</i>. <span class=\"citation\">Num. R. s. 19</span>; <span class=\"citation\">Koh. R. to VII, 23</span> <span dir=\"rtl\">רגלוי … לח׳ דנונא</span> the feet of chickens resemble (as to their covering) the scale-covered skin of the fish, v. <a href=\"#\" data-headword=\"חַרְסְפִיתִין\">חַרְסְפִיתִין</a>.</div><div class=\"sense\"><b>—2)</b> <i>scab, eruption</i>. <span class=\"citation\">Sabb. 133ᵇ</span>, sq. <span dir=\"rtl\">האי מאן דמשי … ליה ח׳</span> (Ms. M. <span dir=\"rtl\">חוספנתא</span>) he who washes his face and does not dry it well, will get a scab. <span class=\"citation\">Ab. Zar. 28ᵇ</span>, sq. (Rashi: <span dir=\"rtl\">חוס׳</span>).</div>","alt":[]},"11939":{"h":"חָסַר","r":"H01410","html":"<div class=\"sense\"> [<i>to scrape off</i>,] <i>to diminish, take off; to be diminished, less; to want, miss; to be imperfect</i>. <span class=\"citation\">Snh. 68ᵃ</span> <span dir=\"rtl\">ולא חָסַרְתִּי מרבותי וכ׳</span> yet I skimmed of the knowledge of my teachers no more than a dog takes who licks out of the sea. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ולא חֲסָרוּנִי וכ׳</span> they skimmed of my knowledge &amp;c.; <span class=\"citation\">Cant. R. to I, 3</span> <span dir=\"rtl\">לא חֲסַרְתִּיהָ וכ׳</span> what wisdom I skimmed of the Law, was no more than &amp;c., v. <a href=\"#\" data-headword=\"זַכְרוּת\">זַכְרוּת</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רבותי חֲסָרוּהָ וכ׳</span> my teachers carried off at least a real smattering of it &amp;c. <span class=\"citation\">B. Kam. 20ᵃ</span> bot. <span dir=\"rtl\">מאי חֲסַרְתִּיךָ</span> what loss have I occasioned to thee?—<span class=\"citation\">Ib.ᵇ</span>, a. fr. <span dir=\"rtl\">זה נהנה … חָסֵר</span> the one profits while the other loses nothing (therefore can claim no damages). <span class=\"citation\">Lev. R. s. 1</span> <span dir=\"rtl\">מה חָסַרְתָּ</span>, v. <a href=\"#\" data-headword=\"דֵּעָה\">דֵּעָה</a>. <span class=\"citation\">Men. 30ᵃ</span>, a. e. is it possible <span dir=\"rtl\">ס&quot;ת ח׳ אות וכ׳</span> that the Book of the Law wanted one letter yet (to be written) &amp;c.?—<span class=\"citation\">Pesik. R. s. 3</span> (ref. to <span dir=\"rtl\">מתה עלי</span>, <span class=\"citation\">Gen. XLVIII, 7</span>) <span dir=\"rtl\">שחֲסרְתִּיהָ</span> for I miss her; a. fr.</div><div class=\"sense\"><b>Pi. חִיסֵּר</b> <div class=\"sense\"><i>to lessen, omit; to deprive</i>. <span class=\"citation\">Ker. 6ᵃ</span> <span dir=\"rtl\">חי׳ אחת וכ׳</span> if he left out one of its ingredients. <span class=\"citation\">Erub. 13ᵃ</span> <span dir=\"rtl\">שמא אתה מְחַסֵּר וכ׳</span> for if thou omit one letter. <span class=\"citation\">Koh. R. to I, 15</span> (ref. to <a href=\"#\" data-headword=\"חֶסְרוֹן\">חסרון</a>, ib.) <span dir=\"rtl\">משאדם מְחַ׳ עצמו וכ׳</span> as soon as a man deprives himself of the words of the Law (neglecting them); <span class=\"citation\">ib.</span> <span dir=\"rtl\">מַחֲסִיר</span> (<i>Hif.</i>). Y. Snh. XI, beg. 30ᵃ <span dir=\"rtl\">אפי׳ לא חי׳</span> even if on inflicting an injury (v. <a href=\"#\" data-headword=\"חַבּוּרָה\">חַבּוּרָה</a>) he did not create a diminution (open wound); a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְחוּסָּר</span>, constr. <span dir=\"rtl\">מְחוּסַּר</span> <i>wanting, requiring</i>. <span class=\"citation\">R. Hash. 6ᵃ</span> <span dir=\"rtl\">מח׳ זמן</span> wanting time, i.e. too young for sacrifice. <span class=\"citation\">Ker. II, 1</span> <span dir=\"rtl\">מח׳ כפרה</span> requires a ceremony of atonement (before he may partake of a sacred meal). <span class=\"citation\">Gen. R. s. 32</span>, a. e. <span dir=\"rtl\">מח׳ אמנה</span>, v. <a href=\"#\" data-headword=\"אֲמָנָה II\"><span dir=\"rtl\">אֲמָנָה</span> I</a>. <span class=\"citation\">Ḥull. 25ᵃ</span>, v. <a href=\"#\" data-headword=\"חֲטִיטָה\">חֲטִיטָה</a>.—Y. B. Mets. V, 10ᶜ bot. <span dir=\"rtl\">מח׳ מעשה אחד</span> wanting one action to be available; a. fr.—Pl. constr. <span dir=\"rtl\">מְחוּסְּרֵי</span>. Ker. l. c. <span dir=\"rtl\">ארבעה מ׳ וכ׳</span> there are four persons requiring a ceremony of atonement before being permitted &amp;c., v. supra; a. fr.</div></div><div class=\"sense\"><b>Hif. הֶחְסִיר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חַסְפְּנִיתָא\">same</a>, v. supra.</div></div>","alt":["חָסֵר I"]},"11940":{"h":"חֲסַר","r":"H01411","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Ex. XVI, 18</span> (O. ed. Berl. <a href=\"#\" data-headword=\"חָסַר\">חַסָּר</a>, oth. ed. <a href=\"#\" data-headword=\"חֲסַר\">חֲסַר</a>, <a href=\"#\" data-headword=\"חֲסִיר\">חַסִּיר</a>) had less. <span class=\"citation\">Targ. Deut. II, 7</span>; a. fr.—<span class=\"citation\">Nidd. 68ᵃ</span> <span dir=\"rtl\">חַסְרַת</span>, v. <a href=\"#\" data-headword=\"דּוּדָא\">דּוּדָא</a>; a. e.</div><div class=\"sense\"><b>Pa. חַסַּר</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חָסַר\">same</a>, v. supra.—2) </div><div class=\"sense\"><i>to lessen, deprive, reduce</i>. <span class=\"citation\">Targ. Ps. VIII, 6</span>. <span class=\"citation\">Targ. Koh. IV, 8</span>; a. fr.—<span class=\"citation\">Snh. 22ᵃ</span> <span dir=\"rtl\">חַסְּרֵיה וכ׳</span> v. <a href=\"#\" data-headword=\"גַּנָּבָא\">גַּנָּבָא</a>; a. e.—<i>Part. pass</i>. <span dir=\"rtl\">מְחַסַּר</span> (v. <a href=\"#\" data-headword=\"חָסַר\">preced.</a> <i>Pi.</i>) <i>wanting</i>. <span class=\"citation\">Targ. Y. Num. XI, 32</span>.—<span class=\"citation\">Bets. 24ᵃ</span>; <span class=\"citation\">Bekh. 39ᵃ</span>, a. fr. <span dir=\"rtl\">חַסּוּרֵי מְחַסְּרָא</span> (or <span dir=\"rtl\">מִיחַסְּרָא</span> <i>Ithpa.</i>) the relation is defective (a clause has been omitted).</div></div>","alt":["חָסַר"]},"11941":{"h":"חָסֵר II","r":"H01412","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>wanting, defective; less</i>. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">ארבעים ח׳ אחת</span> forty (labors) less one. <span class=\"citation\">B. Bath. VII, 2</span>, v. <a href=\"#\" data-headword=\"הֵן\">הֵן</a>. <span class=\"citation\">Ib. 89ᵇ</span> <span dir=\"rtl\">מדה ח׳ וכ׳</span> a measure too small or too large. <span class=\"citation\">Tosef. Taan. I, 2</span> <span dir=\"rtl\">אם … השנה ח׳</span> if the year had a deficiency of rain; Y. ib. I, 64ᵇ; a. fr.—Pl. <span dir=\"rtl\">חֲסֵירִים</span>, … <a href=\"#\" data-headword=\"בלקטורים\">רִין</a>; <span dir=\"rtl\">חֲסֵירוֹת</span>. <span class=\"citation\">Macc. 23ᵃ</span> <span dir=\"rtl\">חֲסֵירֵי כח</span> of feeble physics; a. fr.—Esp. a) (calendar) <a href=\"#\" data-headword=\"חָסֵר\">חָסֵר</a> <i>a defective month</i> (of 29 days), opp. <a href=\"#\" data-headword=\"מָלֵא I\">מלא</a> of thirty days. <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">ואיחליף מלא לח׳ …</span> and he made a mistake between a full and a defective month (thought it was the thirtieth day of the preceding month). <span class=\"citation\">R. Hash. 19ᵇ</span>; a. fr.—<i>Pl.</i> as ab. Ib.— b) (orthogr.) <i>a defective writing, omission of the vowel letter</i>, opp. <a href=\"#\" data-headword=\"מָלֵא I\">מלא</a> (plene), e. g. <a href=\"#\" data-headword=\"חֹדֶשׁ\">חֹדֶשׁ</a>, plene <a href=\"#\" data-headword=\"חוֹדֶשׁ\">חוֹדֶשׁ</a>.—<i>Pl.</i> f. <span dir=\"rtl\">חֲסֵירוֹת</span>. <span class=\"citation\">Erub. 13ᵃ</span>; <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">ח׳ ויתרות</span> the rules concerning <i>defective</i> and <i>plene</i>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>creating a defect</i>. <span class=\"citation\">Ḥag. 3ᵇ</span> (ref. to <span class=\"citation\">Koh. XII, 11</span>) <span dir=\"rtl\">אי מה … ח׳ וכ׳</span> you might think, as the nail (driven in) creates a hole and not an addition, <span dir=\"rtl\">אף ד&quot;ת חֲסֵירִין וכ׳</span> so do the words of the Law &amp;c.; <span class=\"citation\">Yalk. Koh. 989</span> end <span dir=\"rtl\">אף ד&quot;ת מְחַסְּרִין וכ׳</span>.</div>","alt":["חֲסֵרָה","חֲסֵי׳"]},"11942":{"h":"חָסֵר","r":"H01413","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings XI, 22</span>. <span class=\"citation\">Targ. I Sam. XXI, 16</span>; a. fr.—Targ. II Esth. III, 8 <span dir=\"rtl\">חד ח׳</span> one month is defective (of 29 days).—Pl. <span dir=\"rtl\">חֲסֵרִין</span>, <a href=\"#\" data-headword=\"חָסֵר II\">חֲסֵי׳</a>. <span class=\"citation\">Targ. Prov. XXVII, 12</span> (ed. Wil. <span dir=\"rtl\">חַסְרִין</span>, v. <a href=\"#\" data-headword=\"חֲסַר\">חֲסַר</a>).—Targ. II Esth. l. c. (ed. Lag. <a href=\"#\" data-headword=\"חֲסוֹרִין\">חֲסוֹרִין</a>) <i>starving</i></div>","alt":["חֲסַר"]},"11943":{"h":"*חֶסֶר","r":"H01414","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָסֵר\">preced.</a>) <i>diminution</i>. <span class=\"citation\">Keth. 66ᵇ</span>, v. <a href=\"#\" data-headword=\"מֶלַח\">מֶלַח</a>.</div>","alt":[]},"11944":{"h":"חֶסְרוֹן","r":"H01415","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*חֶסֶר\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>want, loss</i>.—<span dir=\"rtl\">ח׳ כיס</span> loss of money. <span class=\"citation\">Sabb. 157ᵃ</span>, a. fr., v. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>. <span class=\"citation\">Kidd. 32ᵇ</span> <span dir=\"rtl\">שאין בה ח׳ כיס</span> with which no material loss is connected. <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">המקום ימלא חֶסְרוֹנְךָ</span> the Lord replace thy deficiency; <span class=\"citation\">Ber. 16ᵇ</span>. <span class=\"citation\">Tosef. Taan. I, 2</span> <span dir=\"rtl\">נותנין לה חִיסְּרוֹנָהּ</span> the year’s deficiency (of rain) will be supplied to him (who prays); Y. ib. I, 64ᵇ <span dir=\"rtl\">חסרונה</span>. Ib.ᵈ top (ref. to <span class=\"citation\">Job XXX, 3</span>) <span dir=\"rtl\">אם ראית ח׳ בא וכ׳</span> when thou seest scarcity &amp;c.; (<span class=\"citation\">Gen. R. s. 31</span>; s. 34 <a href=\"#\" data-headword=\"חוֹסֶר\">חוֹסֶר</a>), v. <a href=\"#\" data-headword=\"גַּלְמוּד\">גַּלְמוּד</a>. <span class=\"citation\">Ḥull. 47ᵇ</span>, a. fr. <span dir=\"rtl\">נקב שיש בו ח׳</span> a perforation connected with a loss of substance. Ib.; <span class=\"citation\">Bekh. 39ᵃ</span>, a. e. <span dir=\"rtl\">ח׳ מבפנים … ח׳</span> a deficiency of substance inside of an organ is not considered a defect (in ritual law); a. fr.</div>","alt":["חִסָּרוֹן","חִי׳"]},"11945":{"h":"חֶסְרוֹנָא","r":"H01416","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּסְרָן\">חוּסְרָנָא</a></div>","alt":["חֶסְרָנָא"]},"11946":{"h":"חָף","r":"H01417","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּף I\">חוף</a>, <a href=\"#\" data-headword=\"חֲפַף\"><a href=\"#\" data-headword=\"חֲפַף\">חפף</a>.</a></div>","alt":["חַף"]},"11947":{"h":"חָף ²","r":"H01418","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. b. h. <a href=\"#\" data-headword=\"חָף\">חֹף</a>; <a href=\"#\" data-headword=\"חָפַף I\"><span dir=\"rtl\">חפף</span> I</a>) </div><div class=\"sense\"><b>1)</b> <i>border, shore</i>. <span class=\"citation\">Num. R. s. 13</span> (ref. to <span class=\"citation\">Num. VII, 26</span>) <span dir=\"rtl\">אין כף אלא חף וכ׳</span> <i>Kaf</i> (bowl) means the same as <i>ḥaf</i> (shore), as it is said (<span class=\"citation\">Ps. XCVIII, 8</span>) rivers strike the <i>Kaf.</i></div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חִיפָּא\">חִיפָּא</a>) [<i>rim, ridge</i>,] <i>ward of a lock</i> <a href=\"#\" data-headword=\"פּוֹתַחַת\">(פותחת</a>); <i>bit of a key</i> (corresponding to the ward); <i>pivot of a door</i> (v. Sm. Ant. s. vv. Cardo, Clavis). <span class=\"citation\">Sabb. VIII, 6</span> <span dir=\"rtl\">כדי … חף</span> bone large enough to make of it a <i>ḥaf</i>; expl. <span class=\"citation\">ib. 81ᵃ</span> <span dir=\"rtl\">חַפֵּי פותחת</span> the rims (ward) of a lock; Y. ib. 11ᵇ bot <span dir=\"rtl\">מהו חף סרגיד</span> what <i>ḥaf</i> is meant? (Answ.) the key-ward; <span class=\"citation\">ib.</span> <span dir=\"rtl\">תמן היא עביד חף בלוט וכ׳</span> (not <a href=\"#\" data-headword=\"כלוט\">כלוט</a>) there (<span class=\"citation\">Kel. XIV, 8</span>) he (R. Judah) uses <i>ḥaf</i> in the sense of a key-bit, and here (Sabb. l. c.) in the sense of a key-ward.</div><div class=\"sense\"><b>—3)</b> <i>the border of a web</i>, used for starting a new web by fastening the warp to it. Y. ib. VII, 10ᶜ, v. <a href=\"#\" data-headword=\"נִיר IV\"><span dir=\"rtl\">נִיר</span> IV</a>.—Pl. <span dir=\"rtl\">חַפִּים</span>, <span dir=\"rtl\">חַפִּין</span>. <span class=\"citation\">Kel. XIII, 6</span> <span dir=\"rtl\">פותחת של עץ וח׳ וכ׳</span> if the lock is of wood and its key-bits of metal (ed. Dehr. <span dir=\"rtl\">חָפִין</span>). <span class=\"citation\">Ib. XIV, 8</span> <span dir=\"rtl\">ניטלו ח׳</span> if the teeth of the bit are broken off (damaged). <span class=\"citation\">Sabb. 81ᵃ</span>, v. supra. Y. ib. IV, 7ᵃ top <span dir=\"rtl\">חַפֵּי לסוטות</span> borders used for weaving veils. <span class=\"citation\">Cant. R. to III, 10</span> (expl. <span dir=\"rtl\">פתות</span>, <span class=\"citation\">I Kings VII, 50</span>) <a href=\"#\" data-headword=\"*חפיפות\">חפיפות</a>, read: <span dir=\"rtl\">חַפֵּי פותחות</span> the pivots; (<span class=\"citation\">Pesik. R. s. 6</span> <span dir=\"rtl\">בלוטין שבפותחות</span>, v. <a href=\"#\" data-headword=\"בָּלוּט\">בָּלוּט</a>).—<span class=\"citation\">Kel. XI, 4</span> <span dir=\"rtl\">הַפִּין</span> = <span dir=\"rtl\">החפין</span>.</div>","alt":[]},"11948":{"h":"חָפָא","r":"H01419","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חפי\">חפי</a></div>","alt":["חֲפָא"]},"11949":{"h":"חפאטיקון","r":"H01420","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִיפָּטִיקוֹס\">הִיפָּטִיקוֹס</a></div>","alt":[]},"11950":{"h":"חֳפָאִים","r":"H01421","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (pl. of <a href=\"#\" data-headword=\"חָפֵי\">חֳפִי</a>; <a href=\"#\" data-headword=\"חָפָה\">חָפָה</a>) <i>covering</i> over burnt clay vessels. <span class=\"citation\">Tosef. Kel. B. Kam. III, 14</span>; ib. <span class=\"citation\">Par. V</span> (<span class=\"citation\">IV), 2</span> <span dir=\"rtl\">(<span dir=\"rtl\">לח׳</span>) <span dir=\"rtl\">גילה ח׳ וכ׳</span></span> ed. Zuck. (ed. corrupt) if he removes the covering and finds dust on the vessels (proving that none had touched them; v. R. S. to <span class=\"citation\">Par. V, 1</span> for correct version).</div>","alt":["חֳפָאִין"]},"11951":{"h":"חֵפָה","r":"H01422","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֵפֶת\">חֵפֶת</a></div>","alt":[]},"11952":{"h":"חָפָה","r":"H01423","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חפי\">חפי</a></div>","alt":[]},"11953":{"h":"חִפּוּי","r":"H01424","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָפָה\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>covering, wrapping.</i> <span class=\"citation\">Kel. XVI, 8</span> <span dir=\"rtl\">(<span dir=\"rtl\">חעשוי</span>) <span dir=\"rtl\">לח׳</span></span> whatever is intended for wrapping, opp. <a href=\"#\" data-headword=\"תֵּיק\">תיק</a>, casing. <span class=\"citation\">Ib. XXVI, 6</span>. <span class=\"citation\">Tosef. Kel. B. Bath. IV, 11</span>; a. e.—Pl. <span dir=\"rtl\">חִפּוּיִם</span>, <a href=\"#\" data-headword=\"חוּלְתָּא\">חִי׳</a>. Ib. XVI, 8 <span dir=\"rtl\">חִפּוּיֵ האלה וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>upholstered seat</i>. Ib. XXII, 4 a bridal chair <span dir=\"rtl\">שנטל חִפּוּיוֹ</span> whose seat is missing; (<span class=\"citation\">Eduy. I, 11</span> <a href=\"#\" data-headword=\"חִפּוּיָא\">חִפּוּיָו</a>, Ms. M. <span dir=\"rtl\">דפניו</span>, Mish. Nap. <span dir=\"rtl\">חופיו</span>, v. Rabad a. l.). Kel. l. c. 6 <span dir=\"rtl\">שנטל חִפּוּיוֹ האמצעי</span> whose middle cushion (of the three forming the seat) is wanting.—Pl. as ab. Ib. 5 <span dir=\"rtl\">שלא היו חִפּוּיָו יוצאין</span> (ed. Dehr. <span dir=\"rtl\">חִפּוּיָיו</span>) whose seats were not movable (v. Rabad to Eduy. l. c.); a. fr.—[<span class=\"citation\">Tosef. Sabb. IV</span> (<span class=\"citation\">V), 7</span> <span dir=\"rtl\">כל חיפוי</span> ed. Zuck., read with ed.: <a href=\"#\" data-headword=\"נוֹי\">נוֹי</a>.]</div>","alt":["חִי׳"]},"11954":{"h":"חִפּוּיָא","r":"H01425","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"חִפּוּי\">same</a>, <i>covering, coating, overlaying</i>. <span class=\"citation\">Targ. Ex. XXXVIII, 17</span>; <span class=\"citation\">19</span> (h. text <a href=\"#\" data-headword=\"צִפּוּי\">צִפּוּי</a>). <span class=\"citation\">Targ. Is. XXX, 22</span>.</div>","alt":["חִפּוּי","חִי׳"]},"11955":{"h":"חִפּוּפִיתָא","r":"H01426","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִיפּוּשִׂיתָא\">חִיפּ׳</a></div>","alt":[]},"11956":{"h":"חפופתא","r":"H01427","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲפִיפוּתָא II\"><span dir=\"rtl\">חֲפִיפוּתָא</span> II</a></div>","alt":[]},"11957":{"h":"חָפוֹר","r":"H01428","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲפַר I\">חָפַר</a>) <i>digger, attendant of earth-work on farms</i>.—Pl. <span dir=\"rtl\">חֲפוֹרוֹת</span>. <span class=\"citation\">Tosef. B. Mets. IX, 14</span> (ed. Zuck. <a href=\"#\" data-headword=\"חופורות\">חופורות</a>, corr. acc.; Y. ib. IX, beg. 12ᵃ <span dir=\"rtl\">החוֹפֵר</span>).</div>","alt":[]},"11958":{"h":"חֲפוּרָא","r":"H01429","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲפוּרָה ²\"><span dir=\"rtl\">חֲפוּרָה</span> II</a></div>","alt":["חֲפוּרֵי"]},"11959":{"h":"חֲפוּרָא ²","r":"H01430","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲפוּרְתָּא\">חֲפוּרְתָּא</a></div>","alt":["חֲפוּרַת"]},"11960":{"h":"זְרַע II","r":"G00725","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. I, 11</span>; a. fr. <a href=\"#\" data-headword=\"זִיזָא III\">בר ז׳</a> that which is fit for propagation, <i>seed-capsule</i>, v. <a href=\"#\" data-headword=\"בִּיזְרָא\">בִּיזְרָא</a>. <span class=\"citation\">Targ. Prov. XI, 21</span>; a. fr.—<span class=\"citation\">Targ. Ps. XXXVII, 26</span> Ms. (ed. <span dir=\"rtl\">דרעיה</span>, v. <a href=\"#\" data-headword=\"דְּרַע II\"><span dir=\"rtl\">דְּרַע</span> II</a>).—<span class=\"citation\">Y. Snh. VII, end, 25ᵈ</span> <span dir=\"rtl\">ז׳ דכיתן</span> flax-seed.</div>","alt":["זַרְעָא"]},"11961":{"h":"זֵרָעוֹן","r":"G00726","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְרַע II\">preced.</a> wds.) <i>rows of plants in one bed</i>, also (= <span dir=\"rtl\">זְרָעִים</span>) <i>seeds.</i> <span class=\"citation\">Kil. II, 2</span> <span dir=\"rtl\">זֵרְעוֹנֵי גנה וכ׳</span> garden seeds which are not used for food, i.e. seeds of vegetables; <span class=\"citation\">Tosef. Maasr. III, 14</span>; <span class=\"citation\">Sabb. IX, 7</span>. Tosef. l. c. <span dir=\"rtl\">ז׳ שדה</span> field seeds (e.g. vetch &amp;c.). <span class=\"citation\">Kil. III, 1</span> <span dir=\"rtl\">חמשה ז׳</span> five rows of different seeds; a. fr.</div>","alt":["זֵרְעוֹנִין","זֵרְעוֹנִים"]},"11962":{"h":"זרעות","r":"G00727","html":"<div class=\"sense\">, <span class=\"citation\">Snh. 37ᵃ</span>, v. <a href=\"#\" data-headword=\"זַרְעִית\">זַרְעִית</a></div>","alt":[]},"11963":{"h":"זַרְעִי","r":"G00728","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"זַרְעִית ²\">זַרְעִיתָא</a></div>","alt":[]},"11964":{"h":"זַרְעִית","r":"G00729","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זַרְעִי\">preced.</a> wds.) <i>descendants, family</i>.—Pl. <span dir=\"rtl\">זַרְעִיֹּות</span>. <span class=\"citation\">Snh. IV, 5</span> (<span class=\"citation\">37ᵃ</span>) <span dir=\"rtl\">דמו ודם זַרְעִיֹּותָיו</span> Mish. a. Y. ed. (Bab. ed. <span dir=\"rtl\">זרעותיו</span>, v. Rabb. D. S. a. l. note 10) his own (the murdered man’s) blood and that of his eventual descendants; <span class=\"citation\">Gen. R. s. 22</span>; <span class=\"citation\">Yalk. Gen. 38</span>.</div>","alt":[]},"11965":{"h":"זַרְעִית ²","r":"G00730","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XXIX, 17</span>. <span class=\"citation\">Targ. Josh. VII, 14</span>; a. e.—<span class=\"citation\">Y. Kil. IX, 32ᶜ</span> top <span dir=\"rtl\">זַרְעִיתֵיה לא פסיקה וכ׳</span> his race shall never cease; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> top <span dir=\"rtl\">זרעייתא</span> (corr. acc.). <span class=\"citation\">Koh. R. to IV, 9</span> <span dir=\"rtl\">והא ז׳ ז׳ וכ׳</span> here is the third generation of that family &amp;c.—Pl. <a href=\"#\" data-headword=\"*זַעֲיָיתָא\">זַרְעֲיָיתָא</a>, <span dir=\"rtl\">זַרְעֲיָין</span>; constr. <span dir=\"rtl\">זַרְעֲיַית</span>. <span class=\"citation\">Targ. O. Gen. IV, 10</span> (cmp. <span class=\"citation\">Snh. IV, 5</span> quot. in <a href=\"#\" data-headword=\"זַרְעִית\">preced.</a>; ed. Berl. <span dir=\"rtl\">זְרַעֲיַן</span>). <span class=\"citation\">Targ. Zech. XII, 12</span>; <span class=\"citation\">14</span> (not <span dir=\"rtl\">זרעִין</span>). <span class=\"citation\">Targ. O. Ex. VI, 14</span> (ed. Berl. <a href=\"#\" data-headword=\"זַרְעִית\">זַרְעַיָת</a>); a. fr.—<span class=\"citation\">Kidd. 70ᵇ</span> <span dir=\"rtl\">תרתי ז׳ איכא וכ׳</span></div>","alt":["זַרְעִיתָא","זַרְעִי"]},"11966":{"h":"זרף","r":"G00731","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 18ᵇ</span> נזרפיה Ar. (ed. <span dir=\"rtl\">לייתיה</span>, Var. Ar. <span dir=\"rtl\">נטרפיה</span>, Ms. M. <span dir=\"rtl\">לתפסיה</span>) prob. a corrupt. for <span dir=\"rtl\">נִגְרְבֵיה</span>, v. <a href=\"#\" data-headword=\"גְּרַב\">גְּרַב</a></div>","alt":[]},"11967":{"h":"זְרַף","r":"G00732","html":"<div class=\"sense\">, <i>Pa.</i> <span dir=\"rtl\">זָרֵיף</span> (cmp. <span dir=\"rtl\">זרב</span>) <i>to form a rim</i> or <i>elevation around a wound</i> (cmp. <a href=\"#\" data-headword=\"כָּתִית\">כָּתִית</a>, <a href=\"#\" data-headword=\"סַפַּחַת\">סַפַּחַת</a>), <i>to cause a swelling and inflammation</i>. <span class=\"citation\">Ab. Zar. 28ᵇ</span> <span dir=\"rtl\">מִיזְרַף זָרֵיף</span> the operation with the hand creates soreness. <span class=\"citation\">Ḥull. 77ᵃ</span>; <span class=\"citation\">Yeb. 76ᵃ</span> <span dir=\"rtl\">פרזלא מז׳ ז׳</span> cutting with an iron tool causes inflammation.</div>","alt":[]},"11968":{"h":"זִרְפָּא","r":"G00733","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְרַף\">preced.</a>) <i>inflammation, swelling of a wound</i>. <span class=\"citation\">Sabb. 67ᵃ</span> דעבדי ליה לז׳ Ms. M. (ed. <span dir=\"rtl\">דעבדי לזי׳</span></div>","alt":["זִירְ׳"]},"11969":{"h":"זָרַק","r":"G00734","html":"<div class=\"sense\"><i>to sprinkle; to cast, throw</i>. <span class=\"citation\">Keth. 103ᵇ</span> <span dir=\"rtl\">זְרוֹק וכ׳</span>, v. <a href=\"#\" data-headword=\"מָרָה IV\"><span dir=\"rtl\">מָרָה</span> I</a>. <span class=\"citation\">Sabb. XI, 1</span> <span dir=\"rtl\">הזוֹרֵק מרשות וכ׳</span> he who throws an object from private to public ground; a. fr.—Esp. <i>to sprinkle blood on the altar</i> (<span class=\"citation\">Lev. I, 5</span>). <span class=\"citation\">Yoma III, 4</span> <span dir=\"rtl\">קבל … וזְרָקוֹ</span> he received the blood and did the required sprinkling. <span class=\"citation\">Zeb. I, 4</span>; a. fr.—<span class=\"citation\">Yoma 67ᵇ</span>, v. <a href=\"#\" data-headword=\"זָקַר\">זָקַר</a>.</div><div class=\"sense\"><b>Nif. נִזְרַק</b> <div class=\"sense\"><i>to be sprinkled</i>. <span class=\"citation\">Pes. V, 3</span>; a. fr.</div></div>","alt":[]},"11970":{"h":"זְרַק","r":"G00735","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Ex. XXIV, 6</span> (Y. <a href=\"#\" data-headword=\"דְּרַק\">דריק</a>); a. fr.—<span class=\"citation\">Gen. R. s. 53</span>, end; s. 86, end [read:] <span dir=\"rtl\">זְרוֹק חוטרא … נפיל</span> throw a stick in the air and it will fall back to its origin (the ground), i.e. innate disposition will always come forth; (cmp. Tanḥ. Balak 17; <span class=\"citation\">Num. R. s. 20</span>).</div><div class=\"sense\"><b>Ithpe. אִזְדְּרֵיק</b> <div class=\"sense\"><i>to be sprinkled</i>. <span class=\"citation\">Targ. Num. XIX, 13</span>; a. e.—<span class=\"citation\">Pes. 78ᵇ</span> bot. <span dir=\"rtl\">אשתקד כי איז׳ דם</span> last year when the blood of the Passover sacrifice was sprinkled.</div></div>","alt":[]},"11971":{"h":"זִרְקְתָא","r":"G00736","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְרִיקְתָּא\">זְרִיקְתָּא</a></div>","alt":[]},"11972":{"h":"זָרַר","r":"G00737","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"זוּר\">זוּר</a> a. </div><div class=\"sense\"><b>1)</b> <i>to press, stamp;</i></div><div class=\"sense\"><b>2)</b> <i>to scatter</i>.</div><div class=\"sense\"><b>Nif. נָזַר  נִיזָּר</b> <div class=\"sense\"><i>to be scattered</i>. Pesik. Vayhi, p. 64ᵇ <span dir=\"rtl\">היתה נדקת … ונִזֶּרֶת</span> was crushed, ground, and scattered; <span class=\"citation\">Pesik. R. s. 17</span>; <span class=\"citation\">Yalk. Ex. 186</span>; Mekh. Bo s. 13 <span dir=\"rtl\">וכִזָּרוֹת …</span> (pl.).</div></div><div class=\"sense\"><b>Hof. הוּזָר</b> <div class=\"sense\"><i>to be smashed</i>. Part. <span dir=\"rtl\">מוּזָר</span>, fem. <span dir=\"rtl\">מוּזֶרֶת</span>, pl. <span dir=\"rtl\">מוּזָרוֹת</span>. <span dir=\"rtl\">ביצה מ׳</span> an egg smashed in the nest, <i>rotten</i> (cmp. <a href=\"#\" data-headword=\"מָאַס\">מָאַס</a>). <span class=\"citation\">Snh. 82ᵇ</span>; Tanḥ. Pinḥ. 2; a. e., v. <a href=\"#\" data-headword=\"*זָמַר III\"><span dir=\"rtl\">זָמַר</span> III</a>.—<span class=\"citation\">Nidd. 35ᵇ</span>. <span class=\"citation\">Ḥull. XII, 3</span>.</div></div>","alt":[]},"11973":{"h":"זֶרֶת","r":"G00738","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זָרַר\">preced.</a>) <i>span</i> (the spread fingers); <i>distance from the little finger to the thumb of a spread hand</i>. <span class=\"citation\">Keth. 5ᵇ</span>; <span class=\"citation\">Men. 11ᵃ</span> <span dir=\"rtl\">זו ז׳</span> this one (the little finger) is used for measuring the span. <span class=\"citation\">Tosef. Kel. B. Mets. VI, 12</span> ז׳ אמורה וכ׳ <i>zereth</i> mentioned therein (in measures), is half a cubit of six handbreadths; a. fr.—<i>Du.</i> <span dir=\"rtl\">זֵרָתַיִים</span>, <a href=\"#\" data-headword=\"זֵרוּעַ\">זֵירָ׳</a>. <span class=\"citation\">Men. 85ᵃ</span>; <span class=\"citation\">Tosef. ib. IX, 3</span> <span dir=\"rtl\">קנה זרת ושבולת ז׳</span> the halm one span long, and the ear two; <span class=\"citation\">Taan. 5ᵃ</span> <span dir=\"rtl\">יֵרָתַיִם</span>.</div>","alt":[]},"11974":{"h":"זַרְתָּא","r":"G00739","html":"<div class=\"sense\">, also <i>fist, hand</i>. <span class=\"citation\">Targ. Ex. XXVIII, 16</span> (ed. Amst. <a href=\"#\" data-headword=\"זַרְתָּא\">זֵרְתָּא</a>). <span class=\"citation\">Targ. Is. XL, 12</span>; a. e.—<span class=\"citation\">Gen. R. s. 63</span> (play on <span dir=\"rtl\">זֹרוּ</span>, <span class=\"citation\">Ps. LVIII, 4</span>) <span dir=\"rtl\">זר׳ מתיחא וכ׳</span> Ar. (ed. <span dir=\"rtl\">וֵירְתֵיה</span>) his fist was directed against him (Jacob); <span class=\"citation\">Yalk. Gen. 110</span>; <span class=\"citation\">Yalk. Deut. 938</span> <span dir=\"rtl\">זירתיה</span>;—Tanḥ. Ki Thetsé 4; <span class=\"citation\">Yalk. Jer. 261</span>; <span class=\"citation\">Yalk. Ps. 868</span> <a href=\"#\" data-headword=\"זריתיה\">זריתֵיה</a>; Tanḥ., ed. Bub. l. c. <span dir=\"rtl\">זירתיה</span>.</div>","alt":["זֵירְתָא"]},"11975":{"h":"זֵתָא","r":"G00740","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זֵיתָא I\">זֵיתָא</a></div>","alt":[]},"11976":{"h":"זֵתִים","r":"G00741","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זַיִת\">זַיִת</a></div>","alt":[]},"11977":{"h":"ח","r":"H00000","html":"<div class=\"sense\"><i>Ḥeth</i>, eighth letter of the Alphabet. It interchanges with <a href=\"#\" data-headword=\"א\">א</a>. <a href=\"#\" data-headword=\"ה\">ה</a> a. <a href=\"#\" data-headword=\"ע\">ע</a>, v. letters <a href=\"#\" data-headword=\"א\">א</a>, a. <a href=\"#\" data-headword=\"ה\">ה</a>; also with <a href=\"#\" data-headword=\"ג\">ג</a> a. <a href=\"#\" data-headword=\"ק\">ק</a>, as <a href=\"#\" data-headword=\"חָבַב I\">חבב</a>, <span dir=\"rtl\">גבב</span>, a. <span dir=\"rtl\">קבב</span>; <a href=\"#\" data-headword=\"חָרָה\">חָרָה</a> a. <a href=\"#\" data-headword=\"גָּרָה\">גָּרָה</a> &amp;c.—For dialectical pronunciation, v. <a href=\"#\" data-headword=\"ה\">ה&quot;א</a> a. <a href=\"#\" data-headword=\"חי\">חי&quot;ת</a>.</div>","alt":[]},"11978":{"h":"ח׳","r":"H00001","html":"<div class=\"sense\">, as a numeral letter, <i>eight</i>.</div>","alt":[]},"11979":{"h":"חָאִי","r":"H00002","html":"<div class=\"sense\">, part. of <a href=\"#\" data-headword=\"חֲיִי\">חֲיִי</a>.</div>","alt":[]},"11980":{"h":"חָאִיךְ","r":"H00003","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּךְ I\">חוּךְ</a>, <a href=\"#\" data-headword=\"חוּס\">חוּס</a>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"חֲקַק\">חֲקַק</a>) <a href=\"#\" data-headword=\"חוּק\">חוּק</a></span>.</div>","alt":["חָאִיס","חָאִיק"]},"11981":{"h":"*חַאיְתָא","r":"H00004","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">חוו</span>, cmp. <a href=\"#\" data-headword=\"חָבַב I\">חבב</a>, <i>to be arched</i>, cmp. <a href=\"#\" data-headword=\"גְּבִינָה\">גְּבִינָה</a>; Syr. <span dir=\"rtl\">חאותא</span>, P. Sm. 1166) <i>clotted cream</i>. <span class=\"citation\">Targ. Prov. XXX, 33</span> Ms. (Var. ed. Lag. <a href=\"#\" data-headword=\"ה׳\">ה׳</a>; ed. Lag. a. oth. <a href=\"#\" data-headword=\"חֶמְאֲתָא\">חֶמְאֲתָא</a>).</div>","alt":[]},"11982":{"h":"חאסטו","r":"H00005","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*הָאַסְטוּ\">הָאַסְטוּ</a></div>","alt":[]},"11983":{"h":"חָאפוּן","r":"H00006","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָפַן\">חָפַן</a>) <i>a handful, a grab</i>. <span dir=\"rtl\">בן ח׳</span> <i>grabber</i> (a play on <span dir=\"rtl\">כְּאָפוּן</span>, v. <a href=\"#\" data-headword=\"אָפוּן\">אָפיּן</a>). Y. Yoma IV, 43ᶜ bot. (Bab. <span class=\"citation\">ib. 39ᵃ</span> sq. <span dir=\"rtl\">בן חַמְצָן</span>).</div>","alt":[]},"11984":{"h":"חָאֵק","r":"H00007","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּק\">חוּק</a> ch.</div>","alt":[]},"11985":{"h":"חָב","r":"H00008","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּב\">חוּב</a></div>","alt":["חַב"]},"11986":{"h":"חָבָא","r":"H00009","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חבי\">חבי</a></div>","alt":["חֲבָא"]},"11987":{"h":"חֻבָּא","r":"H00010","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"חוּבָּא I\">חוּבָּא</a>.</div>","alt":[]},"11988":{"h":"חֵבָא","r":"H00011","html":"<div class=\"sense\">, <span class=\"citation\">B. Kam. 101ᵇ</span>, v. <a href=\"#\" data-headword=\"חֵבָה\">חֵבָה</a></div>","alt":[]},"11989":{"h":"חָבַב I","r":"H00012","html":"<div class=\"sense\"> (b. h.) [<i>to be arched;</i> denom. <a href=\"#\" data-headword=\"חוֹב II\"><span dir=\"rtl\">חוֹב</span> II</a>;] <i>to bosom, love</i>.</div><div class=\"sense\"><b>Pi. חִיבֵּב  חִבֵּב</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חֵבָא\">same</a>, <a href=\"#\" data-headword=\"חֵבָא\">same</a>, <i>to love, cherish;</i> with <span dir=\"rtl\">לפני</span> or <span dir=\"rtl\">בפני</span>, <i>to prefer</i>. <span class=\"citation\">Ex. R. s. 27</span>; Tanḥ. Yithro 4 Yithro is named <span dir=\"rtl\">חוֹבָב</span>, <span dir=\"rtl\">שח׳ את וכ׳</span> because he loved the Law; <span class=\"citation\">Sifré Num. 78</span>. <span class=\"citation\">Sabb. 13ᵇ</span> <span dir=\"rtl\">היו מְחַבְּבִין את הצרות</span> they cherished the memory of past troubles (devoting memorial days to the relief from them). <span class=\"citation\">Ib. 51ᵃ</span>, a. e. <span dir=\"rtl\">כמה מחבבין זה את זה</span> how they honor each other. <span class=\"citation\">Pes. 100ᵃ</span> <span dir=\"rtl\">בכל יום היית מחבב … בפני</span> thou didst always prefer my opinions to those of R. J., and now thou embracest his opinion in my presence; Y. ib. X, beg. 37ᵇ; <span class=\"citation\">Tosef. Ber. V, 2</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"חָבִיב\">חָבִיב</a>) <i>to make beloved</i>. <span class=\"citation\">Gen. R. s. 39</span> <span dir=\"rtl\">כדי לחַבְּבָהּ בעיניו</span> in order to make him feel the dearness of home; <span dir=\"rtl\">כדי לחַבְּבוֹ וכ׳</span> to make him feel how dear was his son to him.</div></div>","alt":[]},"11990":{"h":"חֲבַב","r":"H00013","html":"<div class=\"sense\"><i>Pa.</i> <a href=\"#\" data-headword=\"חָבִיב\">חַבֵּיב</a> same, </div><div class=\"sense\"><b>1)</b> <i>to love, honor</i>. <span class=\"citation\">Targ. Prov. IV, 8</span> <span dir=\"rtl\">חַבִּבְיָהּ</span> honor her. <span class=\"citation\">Targ. O. Deut. XXXIII, 3</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make beloved</i>. Targ. Y. ib.—<span class=\"citation\">Sabb. 130ᵃ</span> is it <span dir=\"rtl\">משום חַבּוּבֵי מצוה</span> (Rashi <a href=\"#\" data-headword=\"חִיבּוּבָא\">חִיבּוּב</a>) in order to show the high appreciation of the ceremony (of circumcision)?—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">אלא לחַבּיּבֵי</span> (Ms. M. <span dir=\"rtl\">לחַבֵּב</span>). <span class=\"citation\">Ḥull. 133ᵃ</span> <span dir=\"rtl\">חבובי קא מְחַבֵּב וכ׳</span></div><div class=\"sense\"><b>Ithpa. אִיתְחַבֵּיב</b> <div class=\"sense\"><i>to be tied together</i> (in affection). <span class=\"citation\">Targ. I Sam. XVIII, 1</span> (h. text <span dir=\"rtl\">נקשרה</span>).</div></div>","alt":[]},"11991":{"h":"*חָבַב II","r":"H00014","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֲבַב\">preced.</a> wds.) <i>to embrace</i> (in a fight), <i>to wrestle</i>. <span class=\"citation\">Tosef. Shebu. VI, 2</span> <span dir=\"rtl\">כל זמן שהיו חוֹבְבִין זה את זה</span> (Var. <span dir=\"rtl\">חוֹכְכִין</span>) as long as they were fighting each other, i.e. if the case comes up immediately after the fight took place; ib. <span class=\"citation\">B. Kam. IX, 28</span> <span dir=\"rtl\">חוככין</span>; <span class=\"citation\">Y. Shebu. VII, 37ᵈ</span> bot. <span dir=\"rtl\">חוככין</span>.—V. <a href=\"#\" data-headword=\"*חֲבִיבָאֵי\">חֲבִיבָאֵי</a>.</div>","alt":[]},"11992":{"h":"חֲבָבָאֵי","r":"H00015","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*חֲבִיבָאֵי\">חֲבִיבָאֵי</a></div>","alt":[]},"11993":{"h":"חִבָּה","r":"H00016","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲבָבָאֵי\">preced.</a> wds.) <i>love, esteem, honor</i>. Koh. K. to V, 14 <span dir=\"rtl\">בא לעולם בח׳ וכ׳</span> man enters the world with love (caressed by his nearest), and leaves with love. <span class=\"citation\">Y. Bicc. II, 64ᵈ</span> top <span dir=\"rtl\">לשבעה מיתה של ח׳</span> a death after seven days of sickness is a death of (divine) love; (ib.ᶜ bot. <span dir=\"rtl\">לשבעים מיתה של ח׳</span>, read <a href=\"#\" data-headword=\"שֵׂיבָה\">שֵׂיבָה</a>).—<span class=\"citation\">Ab. III, 14</span> <span dir=\"rtl\">ח׳ יתירה וכ׳</span> the greater divine love consists in its being made known to him &amp;c. <span class=\"citation\">Ḥull. 33ᵃ</span>, a. e. <span dir=\"rtl\">חִיבַּת הקדש מכשרתן</span> the honor in which sacred objects are held makes them fit for levitical uncleanness (even without contact with liquids, v. <a href=\"#\" data-headword=\"כָּשַׁר\">כָּשַׁר</a>). <span class=\"citation\">Ex. R. s. 2</span>, a. fr. <span dir=\"rtl\">לשון ח׳</span> the repetition of a name intimates endearment. <span class=\"citation\">Y. Succ. IV, 54ᵈ</span> top <span dir=\"rtl\">לשון ח׳</span> (the word <a href=\"#\" data-headword=\"שֵׁכָר\">שֵׁכָר</a>, <span class=\"citation\">Num. XXVIII, 7</span>) expresses something dear; (Bab. ib. 49ᵇ; <span class=\"citation\">Num. R. s. 21</span> <a href=\"#\" data-headword=\"שְׁתִיָּיה\">שתייה</a>).—<span class=\"citation\">Keth. 56ᵃ</span> <span dir=\"rtl\">חיבת חופה וכ׳</span> the affection produced by the seclusion in the bridal department is the final act of possession. <span class=\"citation\">Gen. R. s. 93</span>; <span class=\"citation\">Yalk. ib. 150</span> [read:] <span dir=\"rtl\">על חיבת העין כך על בעל אכסניא וכ׳</span> if this was done for a dear object of sight (our sister), how much more shall we do in defence of the host of the Lord (Benjamin, v. <a href=\"#\" data-headword=\"אוּשְׁפִּיזְכָן\">אוּשְׁפִּיזְכָן</a>); a. fr.—Ch. <a href=\"#\" data-headword=\"חִיבְּתָא\">חִיבְּתָא</a>.</div>","alt":["חִיבָּה"]},"11994":{"h":"חֵבָה","r":"H00017","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">חבא</span>) <i>reserve, storage</i>. <span class=\"citation\">B. Kam. 101ᵇ</span> שגיבבן בחיבה Ms. M. (oth. <span dir=\"rtl\">בחבה</span>; ed. <span dir=\"rtl\">בחֵבָא</span>, v. Rabb. D. S. a. l. note) which he gathered up for storage; <span class=\"citation\">Succ. 40ᵃ</span> <span dir=\"rtl\">לחוּבָה</span> ed. (Ms. Ms. 2 <span dir=\"rtl\">בחיבה</span>, v. Rabb. D. S. a. l. note 200).</div>","alt":["חֵיבָה"]},"11995":{"h":"חָבוּ","r":"H00018","html":"<div class=\"sense\">, pr. n. m. <a href=\"#\" data-headword=\"חִירְיָא\">בר ח׳</a>, v. <a href=\"#\" data-headword=\"הָבוּ\">הָבוּ</a></div>","alt":[]},"11996":{"h":"חִבּוּבָא","r":"H00019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲבוּלְיָא\">חִיבּ׳</a></div>","alt":[]},"11997":{"h":"חבוורתא","r":"H00020","html":"<div class=\"sense\">, <span class=\"citation\">Ḥull. 57ᵇ</span>, v. <a href=\"#\" data-headword=\"חַבָּרוּתָא\">חַבְרוּתָא</a></div>","alt":[]},"11998":{"h":"חִבּוּט","r":"H00021","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"חֲבוּלְיָא\">חִיבּ׳</a>.</div>","alt":[]},"11999":{"h":"חָבוּט","r":"H00022","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָבַט\">חָבַט</a>) <i>pressed down</i>, esp. <i>ḥabut</i>, a legal fiction by which an inclined projection is assumed to be like a horizontal plane. <span class=\"citation\">Erub. 9ᵃ</span> <span dir=\"rtl\">או לבוד … או ח׳ אמרינן וכ׳</span> either we assume the fiction of a junction (v. <a href=\"#\" data-headword=\"לָבוּד\">לָבוּד</a>) or of <i>ḥabut</i>, but both of them we do not assume. [Rashi reads <span dir=\"rtl\">חֲבוֹט</span> or ch. <span dir=\"rtl\">חביט</span>, as imperative: <i>press it down</i>.]</div>","alt":[]}};
